PSLE.subjects["chinese"] = {"name":"Chinese","sections":{"p1":"Paper 1","p2":"Paper 2"},"topics":[{"id":"pinyin","name":"汉语拼音 Hanyu Pinyin","icon":"🔤"},{"id":"vocabulary","name":"词语 Vocabulary","icon":"📖"},{"id":"sentences","name":"语法与句子 Grammar and Sentences","icon":"🔧"},{"id":"cloze","name":"短文填空 Cloze Passage","icon":"🧩"},{"id":"comprehension-mcq","name":"阅读理解一 Comprehension (MCQ)","icon":"📰"},{"id":"dialogue","name":"完成对话 Complete the Dialogue","icon":"💬"},{"id":"functional-text","name":"实用文 Notices and Messages","icon":"📋"},{"id":"comprehension-open","name":"阅读理解二 Comprehension (Open-ended)","icon":"📝"},{"id":"writing","name":"作文 Composition","icon":"✍️"}],"papers":[{"id":"2026-prelim-acsj","year":2026,"exam":"Prelim","school":"ACSJ","count":40},{"id":"2026-prelim-ai-tong","year":2026,"exam":"Prelim","school":"Ai Tong","count":40},{"id":"2026-prelim-chij-st-nicholas","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","count":40},{"id":"2026-prelim-henry-park","year":2026,"exam":"Prelim","school":"Henry Park","count":39},{"id":"2026-prelim-nan-hua","year":2026,"exam":"Prelim","school":"Nan Hua","count":42},{"id":"2026-prelim-nanyang","year":2026,"exam":"Prelim","school":"Nanyang","count":41},{"id":"2026-prelim-plmgs","year":2026,"exam":"Prelim","school":"PLMGS","count":40},{"id":"2026-prelim-raffles-girls","year":2026,"exam":"Prelim","school":"Raffles Girls","count":42},{"id":"2026-prelim-red-swastika","year":2026,"exam":"Prelim","school":"Red Swastika","count":37},{"id":"2026-prelim-tao-nan","year":2026,"exam":"Prelim","school":"Tao Nan","count":33}],"questions":[{"id":"chinese-2026-prelim-acsj-p2-q1","cite":"2026 Prelim ACSJ Paper 2 Question 1","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n外婆++临时++决定今晚不出去吃饭了。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“临”是前鼻音 lín，不是后鼻音 líng。","“时”读第二声 shí，不是第三声 shǐ。","“临时”读 lín shí，答案是（1）。"]}],"options":["lín shí","lín shǐ","líng shí","líng shǐ"]},{"id":"chinese-2026-prelim-acsj-p2-q2","cite":"2026 Prelim ACSJ Paper 2 Question 2","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n爷爷会给我们讲故事，也会跟我们分享生活++经验++。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“经”的声母是 j，读 jīng，不是 qīng。","“验”读第四声 yàn，不是第二声 yán。","“经验”读 jīng yàn，答案是（4）。"]}],"options":["qīng yán","qīng yàn","jīng yán","jīng yàn"]},{"id":"chinese-2026-prelim-acsj-p2-q3","cite":"2026 Prelim ACSJ Paper 2 Question 3","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n华语讲故事比赛的报名______止日期是这个星期五。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“截止”的意思是到某个时间就停止，“截止日期”就是最后一天。","“载”是“记载、载客”的载，“戴”是“戴帽子”的戴，“栽”是“栽树”的栽，这三个字样子很像，但意思不对。","答案是（1）截。"]}],"options":["截","载","戴","栽"]},{"id":"chinese-2026-prelim-acsj-p2-q4","cite":"2026 Prelim ACSJ Paper 2 Question 4","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n我们应该珍______时间，不要浪费。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“珍惜”的意思是看重、爱护，不随便浪费。","“惜”是竖心旁，和心里的感觉有关。“熟悉”的“悉”读音一样，但意思是知道、了解。","答案是（3）惜。"]}],"options":["系","席","惜","悉"]},{"id":"chinese-2026-prelim-acsj-p2-q5","cite":"2026 Prelim ACSJ Paper 2 Question 5","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n外公每天清晨都会到附近的公园______身体。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“锻炼身体”是固定搭配，意思是做运动让身体更健康。","“修理”用在坏了的东西上，“照顾”用在人身上（照顾病人），“保护身体”不需要特地到公园去。","答案是（1）锻炼。"]}],"options":["锻炼","修理","照顾","保护"]},{"id":"chinese-2026-prelim-acsj-p2-q6","cite":"2026 Prelim ACSJ Paper 2 Question 6","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老师常常______我们要做一个诚实的人，不要说谎。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“教育”的意思是教导人明白道理。“教育我们要……”是正确的用法。","“训练”是反复练习一种本领；“培养”后面要接习惯、能力（培养好习惯），不能说“培养我们要……”。","答案是（2）教育。"]}],"options":["训练","教育","培养","介绍"]},{"id":"chinese-2026-prelim-acsj-p2-q7","cite":"2026 Prelim ACSJ Paper 2 Question 7","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n妈妈听到这个好消息，++激动++得流下眼泪。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“激动”是心情很不平静。句子里妈妈听到的是“好消息”，所以是高兴、兴奋得流泪。","“觉得难过”也会流泪，但是听到好消息不会难过。","答案是（1）感到兴奋。"]}],"options":["感到兴奋","感到奇怪","觉得着急","觉得难过"]},{"id":"chinese-2026-prelim-acsj-p2-q8","cite":"2026 Prelim ACSJ Paper 2 Question 8","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n林伯伯++灵机一动++，解决了这个问题。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“灵机一动”的意思是脑子一转，突然想到了好办法。","“心里早有了主意”是早就想好了，不是“突然”想到的，所以不对。","答案是（3）突然想出好方法。"]}],"options":["很喜欢自作聪明","心里早有了主意","突然想出好方法","冷静面对新挑战"]},{"id":"chinese-2026-prelim-acsj-p2-q9","cite":"2026 Prelim ACSJ Paper 2 Question 9","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______这次你取得了好成绩，也要继续努力。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["后面有“也”，要找能和“也”搭配的关联词：“就算……也……”。","“虽然”要配“但是”，“只要”要配“就”，“不仅”要配“而且”。","句子的意思是：即使成绩好，还是要努力。答案是（4）就算。"]}],"options":["只要","虽然","不仅","就算"]},{"id":"chinese-2026-prelim-acsj-p2-q10","cite":"2026 Prelim ACSJ Paper 2 Question 10","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______周末的天气不好，我们______不去海边野餐了。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["天气不好是一种假设的情况，不去野餐是结果，要用表示假设的“要是……就……”。","“只有……才……”表示必须有的条件；“不管……都……”表示什么情况结果都一样，后面要有“怎么、多么”等词。","答案是（3）要是……就。"]}],"options":["只有……才","除了……还","要是……就","不管……都"]},{"id":"chinese-2026-prelim-acsj-p2-q11","cite":"2026 Prelim ACSJ Paper 2 Question 11","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，靠的是大家的齐心协力。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“靠的是大家的齐心协力”说明前面是一件大家一起努力才做成的好事。","“钢琴独奏”是一个人表演，不需要大家齐心协力；“对方表现不佳”也不是靠我们齐心协力。","答案是（4）我们班能赢得比赛。"]}],"options":["对方选手表现不佳","钢琴独奏十分精彩","游戏规则需要更换","我们班能赢得比赛"]},{"id":"chinese-2026-prelim-acsj-p2-q12","cite":"2026 Prelim ACSJ Paper 2 Question 12","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老师宣布明天去参观动物园，____________。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["注意时间：老师只是“宣布”，参观是“明天”的事，现在还没去。","（1）（2）（4）都是已经去了动物园才会发生的事，时间不对。","听到好消息，同学们马上的反应是欢呼。答案是（3）。"]}],"options":["同学们都观看了动物表演","同学们便依依不舍地离开","同学们都开心地欢呼起来","同学们兴高采烈地出发了"]},{"id":"chinese-2026-prelim-acsj-p2-q13","cite":"2026 Prelim ACSJ Paper 2 Question 13","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“吩咐”是长辈或上级口头叫晚辈或下级去做事。","（3）是爸爸叫“我”做事，用得对。","（4）孩子不能“吩咐”妈妈，应该用“请求”；（2）应该用“解释”；（1）应该用“表现”。","答案是（3）。"]}],"options":["由于小杰++吩咐++得很好，所以老师奖励了他。","听了老师的++吩咐++，我终于明白了这个词语。","出门之前，爸爸++吩咐++我要记得把大门关好。","我++吩咐++妈妈，明天一定要带我去游乐场玩。"]},{"id":"chinese-2026-prelim-acsj-p2-q14","cite":"2026 Prelim ACSJ Paper 2 Question 14","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“贡献”是为国家、社会或大家做有益的事，常说“作出贡献”。","（2）志明帮助邻居，为社区作出贡献，用得对。","（3）应该用“牺牲”了休息的时间；（4）应该用“提供”了便利；（1）书里有的是“内容、道理”，不是贡献。","答案是（2）。"]}],"options":["那本书内容非常精彩，里面有许多好的++贡献++。","志明经常帮助邻居，为社区作出了许多++贡献++。","老师改作业一直到半夜，++贡献++了休息的时间。","组屋区有很多熟食中心，为居民++贡献++了便利。"]},{"id":"chinese-2026-prelim-acsj-p2-q15","cite":"2026 Prelim ACSJ Paper 2 Question 15","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“坚固”形容东西（房子、城墙、桥）很结实，不容易坏。它不能用来形容人。","（1）形容城墙，用得对。","（2）应该用“固执”，（3）应该用“坚持”，（4）应该用“坚强”。","答案是（1）。"]}],"options":["那座城墙非常++坚固++，敌人都无法攻打进来。","志明是个++坚固++的孩子，从来不听别人的话。","我们遇到困难不能退缩，一定要++坚固++到底。","石缝里的小花不怕风吹雨打，++坚固++地活着。"]},{"id":"chinese-2026-prelim-acsj-p2-q16","cite":"2026 Prelim ACSJ Paper 2 Question 16","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“困难”。“克服困难”是固定搭配，意思是战胜困难。","“控制”是管住（控制情绪、控制时间），不能说“控制困难”。","答案是（1）克服。"]}],"group":"chinese-2026-prelim-acsj-g1","options":["克服","解释","表现","控制"]},{"id":"chinese-2026-prelim-acsj-p2-q17","cite":"2026 Prelim ACSJ Paper 2 Question 17","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["伟强“认真查找资料”，所以订出来的计划内容很多、很周到，是“详细的计划”。","“仔细”形容人做事小心、认真（仔细地看），不用来形容计划本身。","答案是（2）详细。"]}],"group":"chinese-2026-prelim-acsj-g1","options":["清楚","详细","简单","仔细"]},{"id":"chinese-2026-prelim-acsj-p2-q18","cite":"2026 Prelim ACSJ Paper 2 Question 18","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["伟强得了冠军，同学们“发自内心地”为他高兴、觉得光荣，这就是“为他感到骄傲”。","“意外”是没想到，但“发自内心地为他感到意外”说不通。","答案是（3）骄傲。"]}],"group":"chinese-2026-prelim-acsj-g1","options":["意外","幸福","骄傲","成功"]},{"id":"chinese-2026-prelim-acsj-p2-q19","cite":"2026 Prelim ACSJ Paper 2 Question 19","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看后面：这些同学“主动向他道歉”。做错了事才要道歉，所以他们以前是取笑伟强。","如果以前是“称赞”或“鼓励”他，就不需要道歉了。","答案是（1）嘲笑。"]}],"group":"chinese-2026-prelim-acsj-g1","options":["嘲笑","称赞","讨论","鼓励"]},{"id":"chinese-2026-prelim-acsj-p2-q20","cite":"2026 Prelim ACSJ Paper 2 Question 20","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["老师“看着这一切”，亲眼看到伟强一步一步进步，这叫“见证了伟强的成长”。","成长不是老师“安排”出来的，是伟强自己努力得来的。","答案是（2）见证。"]}],"group":"chinese-2026-prelim-acsj-g1","options":["安排","见证","产生","检查"]},{"id":"chinese-2026-prelim-acsj-p2-q21","cite":"2026 Prelim ACSJ Paper 2 Question 21","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"明华的心跳得很快，是因为______","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["找到第三段第一句：“看着这些钱，明华的心跳加速。”","心跳加速是因为看到钱包里有好几张五十元的钞票。","担心失主出现是后来“连忙把钱包塞进书包”的原因，不是心跳加速的原因。答案是（1）。"]}],"group":"chinese-2026-prelim-acsj-g2","options":["他发现钱包里有很多钱。","他担心失主会突然出现。","他实在是累得喘不过气。","他怕一个人留在操场上。"]},{"id":"chinese-2026-prelim-acsj-p2-q22","cite":"2026 Prelim ACSJ Paper 2 Question 22","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"明华离开操场前，打算做什么？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["第三段最后：“连忙把钱包塞进书包，准备离开操场。”","他想用这些钱买玩具，所以打算把钱包带走。","他怕老师和失主看到他，所以不是去找老师，也不是等失主。答案是（2）。"]}],"group":"chinese-2026-prelim-acsj-g2","options":["找伙伴一起玩耍。","赶紧把钱包带走。","去办公室找老师。","等失主来领钱包。"]},{"id":"chinese-2026-prelim-acsj-p2-q23","cite":"2026 Prelim ACSJ Paper 2 Question 23","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"什么事情让小男生哭得那么伤心？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看第四段小男生说的话：“那是妈妈给我买书的钱啊，弄丢了她会责怪我的……”","他弄丢了妈妈给的钱，怕被妈妈责怪，所以哭。","答案是（3）。"]}],"group":"chinese-2026-prelim-acsj-g2","options":["他不小心跌倒受伤了。","他忘了带书本去上课。","他弄丢了妈妈给他的钱。","他找不到可以一起玩的朋友。"]},{"id":"chinese-2026-prelim-acsj-p2-q24","cite":"2026 Prelim ACSJ Paper 2 Question 24","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["inference","character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"文中“两只脚像生了根一样”说明了什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["这句话在第五段。明华本来准备带着钱包离开，听到小男生哭着说的话以后，就“一步也走不动了”。","接着他想起老师讲过的道理和父母的教导，说明他知道自己想拿走钱包是不对的，心里惭愧，所以走不了。","这里不是真的腿酸；如果不想被发现，他会赶快走开。答案是（4）。"]}],"group":"chinese-2026-prelim-acsj-g2","options":["明华的腿酸得走不动。","明华不想被小男生发现。","明华急得在操场上团团转。","明华为自己的想法感到惭愧。"]},{"id":"chinese-2026-prelim-acsj-p2-q25","cite":"2026 Prelim ACSJ Paper 2 Question 25","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["inference","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"最后，明华为什么放下了心中的大石？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“放下心中的大石”的意思是不再担心，心里轻松了。","明华把钱包还给了失主，做了对的事，心里就踏实了。","小男生只是说“谢谢”，明华不是为了得到称赞；钱包是明华还给他的，不是小男生自己找到的。答案是（1）。"]}],"group":"chinese-2026-prelim-acsj-g2","options":["因为他把钱包还给了小男生。","因为他得到了小男生的赞许。","因为没人看见他把钱包拿走了。","因为小男孩在操场找到了钱包。"]},{"id":"chinese-2026-prelim-acsj-p2-q26","cite":"2026 Prelim ACSJ Paper 2 Question 26","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["我的爸妈会带我去旅行"]},"explanation":["叶明问“假期你会做什么？”，洋洋的回答后面是“好好放松一下”。","下一句叶明问“你们会去哪里？”，“你们”说明洋洋是和别人一起去一个地方。","所以选 4：我的爸妈会带我去旅行。"]}],"group":"chinese-2026-prelim-acsj-g3"},{"id":"chinese-2026-prelim-acsj-p2-q27","cite":"2026 Prelim ACSJ Paper 2 Question 27","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["看一看以前贵族居住的城堡"]},"explanation":["前面说“他们会带我去欧洲”，空格要说去欧洲做什么。","叶明接着说“我也喜欢传统建筑”，所以洋洋说的是和古老建筑有关的事。","所以选 6：看一看以前贵族居住的城堡。"]}],"group":"chinese-2026-prelim-acsj-g3"},{"id":"chinese-2026-prelim-acsj-p2-q28","cite":"2026 Prelim ACSJ Paper 2 Question 28","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"1","accept":["机票肯定很贵"]},"explanation":["叶明说“可是欧洲那么远，______，我的父母不会带我去的”，空格是父母不带他去的原因。","后面洋洋说“等你以后自己赚钱了再去”，说明原因和钱有关。","所以选 1：机票肯定很贵。（8“父母工作太忙”和“赚钱”接不上。）"]}],"group":"chinese-2026-prelim-acsj-g3"},{"id":"chinese-2026-prelim-acsj-p2-q29","cite":"2026 Prelim ACSJ Paper 2 Question 29","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"7","accept":["要不我多拍一些照片给你看吧"]},"explanation":["空格后面是“这样你不出国也能看到美丽的风景了”。","不出国也能看到风景，办法就是看照片。叶明还说“这真是个好主意”，说明洋洋提了一个建议。","所以选 7：要不我多拍一些照片给你看吧。"]}],"group":"chinese-2026-prelim-acsj-g3"},{"id":"chinese-2026-prelim-acsj-p2-q30","cite":"2026 Prelim ACSJ Paper 2 Question 30","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"举办儿童节庆祝会的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["目的通常写在通告的开头。第一句是：“为了让孩子们度过一个有意义的儿童节……”","“为了”后面就是举办的目的。","帮助有需要的儿童只是美食摊位卖得的钱的用处，不是整个庆祝会的主要目的。答案是（4）。"]}],"group":"chinese-2026-prelim-acsj-g4","options":["帮助那些有需要的孩子。","鼓励孩子们参加探险活动。","邀请家人陪同孩子一起做运动。","让孩子们度过一个有意义的儿童节。"]},{"id":"chinese-2026-prelim-acsj-p2-q31","cite":"2026 Prelim ACSJ Paper 2 Question 31","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"今年的庆祝会和往年有什么不一样？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["找“往年”和“今年”：“将和往年一样在儿童节当天举办四个庆祝活动。此外，今年还将新增美食摊位”。","四个活动、儿童节当天举行、由俱乐部举办，都是“和往年一样”的。","“新增”就是今年才有的。答案是（3）。"]}],"group":"chinese-2026-prelim-acsj-g4","options":["举办了四个活动。","在儿童节当天举行。","增加了售卖美食的摊位。","由欢乐民众俱乐部来举办。"]},{"id":"chinese-2026-prelim-acsj-p2-q32","cite":"2026 Prelim ACSJ Paper 2 Question 32","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":32,"topic":"functional-text","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"小乐对环保和美术感兴趣，她应该参加哪些活动？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["环保：“变废为宝”是利用可回收物品制作手工艺品，和环保有关。","美术：“小画家”是由画家教孩子画画，和美术有关。","“欢乐运动会”是运动，“探险家”是看夜间动物，都不合适。答案是（2）。"]}],"group":"chinese-2026-prelim-acsj-g4","options":["变废为宝和探险家。","小画家和变废为宝。","欢乐运动会和小画家。","探险家和欢乐运动会。"]},{"id":"chinese-2026-prelim-acsj-p2-q33","cite":"2026 Prelim ACSJ Paper 2 Question 33","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是李强，看到儿童节庆祝活动的通告后，想邀请今年读六年级的智康一起参加“探险家”活动。请你写一个手机短信给他，告诉他这个活动的报名方法，以及他需要注意的事情。\n\n短信的开头是：\n智康，我看到“欢乐民众俱乐部儿童节庆祝活动”的通告，想邀请你和我一起参加“探险家”这个活动。你一定要在……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"智康，我看到“欢乐民众俱乐部儿童节庆祝活动”的通告，想邀请你和我一起参加“探险家”这个活动。你一定要在9月20日前上欢乐民众俱乐部网站报名。活动当天必须带手电筒和防蚊用品。"},"explanation":["内容 2 分，语文 2 分，一共 4 分。","内容第一点（报名方法）：在通告最后一段找——9月20日前，上欢乐民众俱乐部网站报名。日期和“上网站报名”都要写。","内容第二点（要注意的事情）：在“探险家”的注意事项里找——必须带手电筒和防蚊用品。","“10岁以下儿童需家长陪同”不用写，因为智康读六年级，已经超过10岁了。","语文：接着“你一定要在……”写下去，句子要通顺、完整，不要写错字。"]}],"group":"chinese-2026-prelim-acsj-g4"},{"id":"chinese-2026-prelim-acsj-p2-q34","cite":"2026 Prelim ACSJ Paper 2 Question 34","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“东西减少到完全没有或完全不见”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"消失"},"explanation":["要找一个意思是“不见了”的词语。","第二段：贴纸和发夹“好像变魔术一样消失了”。","答案是“消失”。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q35","cite":"2026 Prelim ACSJ Paper 2 Question 35","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“独自一人，无人陪伴”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"孤单"},"explanation":["要找一个意思是“只有自己一个人，没有人陪”的词语。","第二段最后：同学们不敢靠近小安，“使他变得更加孤单”。","答案是“孤单”。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q36","cite":"2026 Prelim ACSJ Paper 2 Question 36","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual"],"format":"structured","marks":3,"difficulty":2,"stem":"六年级甲班发生了什么事？","parts":[{"label":"","answer":{"type":"self","value":"李明桌上的一张星星贴纸和丽华桌上的金色发夹，好像变魔术一样消失了。"},"explanation":["答案在第二段第一句。第一段说班上发生了“怪事”，第二段就说是什么怪事。","要写出三点：李明的星星贴纸、丽华的金色发夹、它们消失（不见）了。","谁的东西、什么东西都要写清楚，不能只写“有东西不见了”。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q37","cite":"2026 Prelim ACSJ Paper 2 Question 37","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":37,"topic":"comprehension-open","subtypes":["cause-and-effect","factual"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"李明和丽华怀疑小安的原因是什么？","marks":2,"answer":{"type":"self","value":"那是因为小安没来之前，班上从来没丢过东西，而且这个班上只有小安家境贫穷。"},"explanation":["有两个原因，各 1 分，都要写。","第一个在第三段李明的话里：“他没来之前，我们班从来没丢过东西！”","第二个在第四段丽华的话里：“这个班上只有小安家境贫穷”。"]},{"label":"b","prompt":"他们的行为对小安造成什么影响？","marks":1,"answer":{"type":"self","value":"李明和丽华总在小安背后说他的坏话，同学们不敢靠近小安，使他变得更加孤单。"},"explanation":["答案在第二段最后一句。","他们的行为是在小安背后说他的坏话；影响是同学们更不敢靠近小安，他变得更加孤单。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q38","cite":"2026 Prelim ACSJ Paper 2 Question 38","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":38,"topic":"comprehension-open","subtypes":["inference"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"“会不会是它”这句话说明了什么？","marks":2,"answer":{"type":"self","value":"它说明了文文猜想是小鸟拿走了东西。"},"explanation":["先弄清楚“它”是谁：文文刚看到小鸟飞进课室，从丽华桌上抓走亮晶晶的糖果纸，所以“它”是小鸟。","“会不会”表示猜想、怀疑。所以这句话说明文文猜是小鸟拿走了贴纸和发夹。"]},{"label":"b","prompt":"为什么文文看了鸟窝后脸上露出笑容？","marks":2,"answer":{"type":"self","value":"因为文文在鸟窝里找到了李明和丽华的东西，可以证明小安不是小偷。"},"explanation":["文文一直想找出“偷东西的人”。他看了鸟窝就笑了，说明他在鸟窝里找到了不见的东西（星星贴纸和金色发夹）。","还要写出这件事的意义：这可以证明小安不是小偷。两点各 1 分。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q39","cite":"2026 Prelim ACSJ Paper 2 Question 39","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":39,"topic":"comprehension-open","subtypes":["character-and-feelings","inference"],"format":"structured","marks":4,"difficulty":2,"stem":"丽华两次脸红的感受和原因有什么不同？","parts":[{"label":"","answer":{"type":"self","value":"丽华第一次脸红时，她感到生气。因为她以为文文在帮小安。丽华第二次脸红时，她感到惭愧。因为她错怪了小安。","accept":["第一次脸红时，丽华感到生气，因为她以为文文在帮小安。第二次脸红时，丽华感到惭愧，因为她错怪了小安。"]},"explanation":["题目问“感受”和“原因”，两次都要写，一共四点，每点 1 分。","第一次在第四段：“丽华则觉得文文在帮小安，气得涨红了脸”。感受是生气，原因是她以为文文在帮小安。","第二次在最后一段：听了文文的发现，“丽华脸红得像番茄，不停地跟小安道歉”。感受是惭愧（不好意思），原因是她知道自己错怪了小安。","回答时用“第一次……第二次……”分开写，才看得出“不同”。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-acsj-p2-q40","cite":"2026 Prelim ACSJ Paper 2 Question 40","year":2026,"exam":"Prelim","school":"ACSJ","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"如果你是小安，你会原谅李明吗？为什么？","parts":[{"label":"","answer":{"type":"self","value":"如果我是小安，我会原谅李明。因为同学之间不该计较。李明低下头说明他已经知道错了，只是没有认错的勇气。","accept":["如果我是小安，我不会原谅李明。因为他怀疑我偷东西，还在我背后说我的坏话，知道自己错怪我后却没有向我道歉。"]},"explanation":["这是看法题，回答“会”或“不会”都可以，但是一定要先说清楚自己的选择，再说理由。","用“如果我是小安，我会／不会原谅李明。因为……”来回答。","理由要用短文里的事：选“会”，可以写同学之间不该计较，李明把头低得快碰到胸口，说明他已经知道错了，只是没有勇气认错。","选“不会”，可以写他没有弄清楚就怀疑我偷东西，还在背后说我的坏话，知道错怪我以后也没有道歉。","只写“会”或“不会”，没有理由，是拿不到分数的。"]}],"group":"chinese-2026-prelim-acsj-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q1","cite":"2026 Prelim Ai Tong Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n为了实现自己的梦想，他从不因为困难而++退缩++。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“退”读第四声 tuì，不是第三声 tuǐ（tuǐ 是“腿”）。","“缩”读第一声 suō，不是第四声 suò。","“退缩”读 tuì suō，答案是（3）。"]}],"options":["tuǐ suō","tuǐ suò","tuì suō","tuì suò"]},{"id":"chinese-2026-prelim-ai-tong-p2-q2","cite":"2026 Prelim Ai Tong Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n小明非常++珍惜++时间，一有空就阅读各种课外书，充实自己。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“珍”是前鼻音 zhēn，不是后鼻音 zhēng。","“惜”读第一声 xī，不是第二声 xí。","“珍惜”读 zhēn xī，答案是（1）。"]}],"options":["zhēn xī","zhèn xí","zhēng xī","zhèng xí"]},{"id":"chinese-2026-prelim-ai-tong-p2-q3","cite":"2026 Prelim Ai Tong Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n外公认真地听我说话，脸上带着慈______的笑容。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“慈祥”形容老人的样子和态度很和气、很亲切。","“祥”是示字旁（礻）。“详”是言字旁，是“详细”的详；“洋”是“海洋”的洋；“样”是“样子”的样。","答案是（2）祥。"]}],"options":["洋","祥","详","样"]},{"id":"chinese-2026-prelim-ai-tong-p2-q4","cite":"2026 Prelim Ai Tong Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n经过不断练习，她终于成为班上最______害的象棋高手。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“厉害”的意思是本领很高、很了不起。","这四个字读音一样，要看意思：“历”是“历史、经历”的历，“励”是“鼓励”的励，“力”是“力气”的力。","答案是（2）厉。"]}],"options":["力","厉","历","励"]},{"id":"chinese-2026-prelim-ai-tong-p2-q5","cite":"2026 Prelim Ai Tong Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n他这次预考成绩很不好，妈妈为他的小六会考感到______。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“担忧”的意思是担心、发愁。成绩不好，妈妈自然会为会考担心。","“感到”后面要接一种心情。“急忙”是形容动作很快（急忙跑去），不是心情；“打扰”是动作。","答案是（1）担忧。"]}],"options":["担忧","麻烦","打扰","急忙"]},{"id":"chinese-2026-prelim-ai-tong-p2-q6","cite":"2026 Prelim Ai Tong Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n为了______发生交通意外，司机应该小心开车。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“避免”的意思是想办法不让不好的事情发生。“避免发生意外”是常见搭配。","“阻拦”是拦住人，不让他做某件事；“克服”后面接困难；“躲过”是事情已经来了才躲开。","答案是（4）避免。"]}],"options":["阻拦","克服","躲过","避免"]},{"id":"chinese-2026-prelim-ai-tong-p2-q7","cite":"2026 Prelim Ai Tong Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n我听到门外有++动静++，于是起身去查看。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["句子里说“听到”门外有动静，能听到的是声音。","“动静”在这里的意思是动作或说话的声音。它有时也指“消息、情况”，但是那样就不会说“听到门外有”。","答案是（1）声音、响动。"]}],"options":["声音、响动","消息、情况","调整、变化","影响、作用"]},{"id":"chinese-2026-prelim-ai-tong-p2-q8","cite":"2026 Prelim Ai Tong Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这里的风景++宜人++，大家都舍不得离开。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“宜”是合适的意思。“宜人”就是适合人的心意，让人觉得舒服。","“令人向往”是还没去、很想去；句子里大家已经在那里了，是“舍不得离开”。","答案是（3）合人心意。"]}],"options":["感觉合适","让人开心","合人心意","令人向往"]},{"id":"chinese-2026-prelim-ai-tong-p2-q9","cite":"2026 Prelim Ai Tong Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______你这次更努力一些，也许就会成功。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“更努力一些”是一种假设，“就会成功”是结果，要用“要是……就……”。","“即使”要配“也”，“虽然”要配“但是”，“由于”说的是已经发生的原因。","答案是（3）要是。"]}],"options":["由于","虽然","要是","即使"]},{"id":"chinese-2026-prelim-ai-tong-p2-q10","cite":"2026 Prelim Ai Tong Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______她的手已经受伤，她______坚持打完比赛。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["手受伤了，本来应该停下来，可是她却坚持打完。前后意思相反，是转折关系。","“尽管……还是……”表示转折。“因为……所以……”是因果关系：受伤不是坚持打完比赛的原因。","答案是（4）尽管……还是。"]}],"options":["不但……反而","不是……而是","因为……所以","尽管……还是"]},{"id":"chinese-2026-prelim-ai-tong-p2-q11","cite":"2026 Prelim Ai Tong Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，大家都喜出望外。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“喜出望外”的意思是遇到没想到的好事，特别高兴。","所以前面要是一件让大家意外的好事：全校放假一天。","有测验不是好事；在操场踢足球很平常，不会“喜出望外”。答案是（3）。"]}],"options":["老师叫大家安静下来","老师宣布明天有测验","校长宣布全校放假一天","同学们在操场上踢足球"]},{"id":"chinese-2026-prelim-ai-tong-p2-q12","cite":"2026 Prelim Ai Tong Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n他从小爱打抱不平，____________。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“打抱不平”的意思是看见不公平的事，就站出来帮助受欺负的人。","所以后面接“常常帮助弱小同学”。","不要看到“打”字就以为是打人。答案是（2）。"]}],"options":["因此一直被人欺负","常常帮助弱小同学","总是动不动就打人","所以时常乱发脾气"]},{"id":"chinese-2026-prelim-ai-tong-p2-q13","cite":"2026 Prelim Ai Tong Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“巧妙”形容方法或做法很聪明、很特别。","（4）把讲故事和说唱结合起来，是一种聪明的做法，用得对。","（1）应该用“美妙、愉快”，（2）应该用“碰巧”，（3）形容手要用“灵巧”。","答案是（4）。"]}],"options":["我们一家人去环球影城玩，这真是一段++巧妙++的旅程。","小安迟到了，他正想溜进课室，++巧妙++遇到训导主任。","小丽的双手非常++巧妙++，能够编织各种可爱的布娃娃。","他++巧妙++地把讲故事和说唱结合起来，得了比赛冠军。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q14","cite":"2026 Prelim Ai Tong Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“发扬”的意思是让好的精神、作风继续下去并且更多人去做，常说“发扬……精神”。","（1）“发扬互助友爱精神”，用得对。","（2）和（4）应该用“发现”，（3）应该用“发挥”。","答案是（1）。"]}],"options":["这段录像让他明白了++发扬++互助友爱精神的重要。","研究人员在海边++发扬++了一种从没见过的小贝壳。","这次演讲比赛中，他++发扬++了实力，赢得了胜利。","康康++发扬++弟弟做了坏事，便马上跑去告诉妈妈。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q15","cite":"2026 Prelim Ai Tong Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“齐心协力”的意思是大家一条心，一起努力做成一件事。","（2）和（3）只有一个人，不能说“齐心协力”。","（1）打羽毛球是玩，不是大家一起努力完成的一件事。（4）是几个人一起把舞台布置好，用得对。","答案是（4）。"]}],"options":["我们++齐心协力++，在体育馆里打羽毛球。","小丽++齐心协力++地帮妈妈把碗碟洗干净。","他++齐心协力++地完成了老师布置的作业。","他们++齐心协力++，终于把舞台布置好了。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q16","cite":"2026 Prelim Ai Tong Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["前面说写毛笔字“需要坚持练习”。要坚持，就不能偷懒。","“懒惰”的意思是不爱做事、不肯努力，和“坚持练习”正好相反。","答案是（2）懒惰。"]}],"group":"chinese-2026-prelim-ai-tong-g1","options":["紧张","懒惰","担心","烦恼"]},{"id":"chinese-2026-prelim-ai-tong-p2-q17","cite":"2026 Prelim Ai Tong Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["前面说“妈妈不断地鼓励他”，妈妈一直在他身边支持他。","“在妈妈的陪伴下”是常见的说法。“控制”和“管理”不是鼓励的意思。","答案是（1）陪伴。"]}],"group":"chinese-2026-prelim-ai-tong-g1","options":["陪伴","控制","管理","计划"]},{"id":"chinese-2026-prelim-ai-tong-p2-q18","cite":"2026 Prelim Ai Tong Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["空格形容文华怎样练习了三年，后面说“总算有了收获”：努力才有收获。","“勤奋”的意思是不停地努力学习或工作，“勤奋练习”搭配得当。","“顽强”多用在和困难、敌人作斗争的时候；“继续练习了三年”说不通。答案是（4）勤奋。"]}],"group":"chinese-2026-prelim-ai-tong-g1","options":["顽强","充实","继续","勤奋"]},{"id":"chinese-2026-prelim-ai-tong-p2-q19","cite":"2026 Prelim Ai Tong Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["空格后面有一个“起”字。“回忆起”是正确的搭配，意思是想起以前的事。","得奖是已经发生的事，所以不是“想象”。不能说“记得起”或“浮现起”。","答案是（2）回忆。"]}],"group":"chinese-2026-prelim-ai-tong-g1","options":["记得","回忆","想象","浮现"]},{"id":"chinese-2026-prelim-ai-tong-p2-q20","cite":"2026 Prelim Ai Tong Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“严格要求自己”是固定搭配，意思是对自己的要求很高，一点也不放松。","“努力”后面常接动作（努力练习），不说“努力地要求自己”。","答案是（1）严格。"]}],"group":"chinese-2026-prelim-ai-tong-g1","options":["严格","努力","肯定","正确"]},{"id":"chinese-2026-prelim-ai-tong-p2-q21","cite":"2026 Prelim Ai Tong Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"为什么志明一直认为自己是个慷慨的人？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["第一段：每当同学过生日，志明总会送上一份礼物，“他觉得自己十分慷慨”。","他送的大多是自己不再喜欢或不再需要的旧物品，不是买的，所以（2）不对。","（1）是他觉得自己“爱惜东西”的原因，不是“慷慨”的原因。答案是（3）。"]}],"group":"chinese-2026-prelim-ai-tong-g2","options":["因为他不会随便把旧东西丢掉。","因为他总是买礼物送给同学们。","因为他常把自己的旧东西送给别人。","因为同学收到礼物都会对他说谢谢。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q22","cite":"2026 Prelim Ai Tong Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["inference","character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"当志明收到旧书包时，为什么会感到失望？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["第三段：他“满心期待”地拆开礼物，“却发现”里面是一个旧书包。“却”说明这是他没想到的。","他失望地说：“这不是你都不用的旧东西吗？”他失望是因为礼物是旧东西。","书包“还能用”，所以（1）不对；他事先不知道有篮球，所以（3）不对。答案是（4）。"]}],"group":"chinese-2026-prelim-ai-tong-g2","options":["因为书包已经掉色了，不能继续使用。","因为他原以为能收到更多的生日礼物。","因为他觉得生日礼物应该是一个篮球。","因为他没想到妈妈会送他一个旧书包。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q23","cite":"2026 Prelim Ai Tong Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["vocabulary-in-context","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"文中“这句话像当头棒喝”是什么意思？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“当头棒喝”比喻一句话或一件事让人一下子清醒过来。","第四段：志明“顿时沉默了”，“忽然明白了妈妈的用意”，知道自己其实只是把不要的东西送出去。","所以是妈妈的话让他马上明白自己错了。答案是（2）。"]}],"group":"chinese-2026-prelim-ai-tong-g2","options":["妈妈的话让志明感到十分不好意思。","妈妈的话让志明立刻明白了自己的错误。","妈妈的话让志明觉得同学们在故意欺骗他。","妈妈的话让志明以为自己受到了不公平的对待。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q24","cite":"2026 Prelim Ai Tong Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["inference","purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"妈妈送旧书包给志明，目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["妈妈说：“你平时送给同学们的礼物，不也都是你不需要的旧东西吗？”","妈妈是要志明自己尝一尝收到旧礼物的滋味，明白“收到礼物的人未必会开心”。","志明明白以后，妈妈才拿出真正的礼物（新篮球），可见旧书包只是用来教他的。答案是（2）。"]}],"group":"chinese-2026-prelim-ai-tong-g2","options":["让志明知道旧的东西也有用处。","让志明体会收到旧礼物的感受。","让志明养成爱惜东西的好习惯。","让志明懂得珍惜自己的旧东西。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q25","cite":"2026 Prelim Ai Tong Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["inference","main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"志明后来有什么改变？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["妈妈最后说：送礼物最重要的“是要考虑别人是否喜欢、是否需要”。志明“使劲地点了点头”，表示他明白了。","“是否喜欢”就是别人的感受，“是否需要”就是别人的需求。","（4）只说了妈妈的话的前半句，不是重点。答案是（3）。"]}],"group":"chinese-2026-prelim-ai-tong-g2","options":["他学会了怎样为别人选生日礼物。","他学会了主动帮助有需要的同学。","他学会了考虑别人的感受和需求。","他学会了选礼物不看价格的高低。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q26","cite":"2026 Prelim Ai Tong Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"2","accept":["我借了图书馆的书","2 我借了图书馆的书"]},"explanation":["空格后面是“今天是还书的最后期限”，下一句乐文说“我陪你去图书馆还书吧”。","要还书，就是之前借了书。所以小丽说的是她借了图书馆的书，没时间去买面。","所以选 2：我借了图书馆的书。（1“鱼丸面的队伍太长”和后面的“还书”接不上。）"]}],"group":"chinese-2026-prelim-ai-tong-g3"},{"id":"chinese-2026-prelim-ai-tong-p2-q27","cite":"2026 Prelim Ai Tong Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["连书的影子都没有看到","4 连书的影子都没有看到"]},"explanation":["前面说“我在家里翻遍了每一个角落”，空格要说找的结果。","书“不见了”，所以结果是找不到。“连影子都没有看到”就是一点也找不到。","所以选 4：连书的影子都没有看到。"]}],"group":"chinese-2026-prelim-ai-tong-g3"},{"id":"chinese-2026-prelim-ai-tong-p2-q28","cite":"2026 Prelim Ai Tong Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["或者会不会是在课室里","6 或者会不会是在课室里"]},"explanation":["乐文在帮小丽想书可能在哪里：先问“有没有放在书包里”，空格后面是问号，所以是再猜一个地方。","下一句小丽说“这些地方我当然都找了”，“这些地方”说明乐文说了不止一个地方。","所以选 6：或者会不会是在课室里。（3“为什么不去课室里找”和前半句接不上。）"]}],"group":"chinese-2026-prelim-ai-tong-g3"},{"id":"chinese-2026-prelim-ai-tong-p2-q29","cite":"2026 Prelim Ai Tong Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["我要不要去找老师承认错误","8 我要不要去找老师承认错误"]},"explanation":["小丽找不到书，问“怎么办？”，空格是她想到的做法，后面是问号。","乐文回答“对呀！我觉得你先去主动认错比较好”，“认错”和“承认错误”意思一样。","所以选 8：我要不要去找老师承认错误。"]}],"group":"chinese-2026-prelim-ai-tong-g3"},{"id":"chinese-2026-prelim-ai-tong-p2-q30","cite":"2026 Prelim Ai Tong Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"今年举办欢乐家庭节的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["目的在第一段：今年的主题是“加倍幸福，由我开始”，“鼓励大家从日常生活中的小事做起，用行动表达对家人的关爱”。","（2）只是活动一的内容，（4）只是开幕典礼办活动的原因，都不是整个家庭节的主要目的。","答案是（3）。"]}],"group":"chinese-2026-prelim-ai-tong-g4","options":["提醒大家参加今年欢乐家庭节的活动。","通过游戏的方式进一步了解家庭成员。","鼓励大家通过生活中的小事关爱家人。","吸引全家人一起参与开幕典礼的活动。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q31","cite":"2026 Prelim Ai Tong Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"想了解 7 月 10 日活动详情的人应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["7 月 10 日在 7 月 2 日至 31 日之间，是民众俱乐部举办的活动。","最后一段：想了解活动详情，“请上民众俱乐部的网站查看，或拨打民众俱乐部的热线电话”。","（3）说的是“欢乐家庭节的热线电话”，通告里的热线是民众俱乐部的，所以不对。答案是（2）。"]}],"group":"chinese-2026-prelim-ai-tong-g4","options":["去全岛的民众俱乐部报名。","到民众俱乐部的网站查看。","拨打欢乐家庭节的热线电话。","到滨海艺术中心办公室询问。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q32","cite":"2026 Prelim Ai Tong Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"民众俱乐部不负责以下哪项活动？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["最后一段：民众俱乐部举办的活动有“户外电影、手工制作及数码健康活动等”。","“体育健身活动”是活动二，是 7 月 1 日在滨海艺术中心举行的，不是民众俱乐部办的。","答案是（4）。"]}],"group":"chinese-2026-prelim-ai-tong-g4","options":["手工制作活动。","数码健康活动。","户外电影活动。","体育健身活动。"]},{"id":"chinese-2026-prelim-ai-tong-p2-q33","cite":"2026 Prelim Ai Tong Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是国文，看到这则广告后，想起这个周末爸爸要去爷爷奶奶家看望他们。请你写一个手机短信给爸爸，让他带你和爷爷奶奶去参加家庭节开幕典礼早上的活动，告诉他活动的地点和时间，以及参加该项活动的好处。\n\n短信的开头是：\n爸爸，我知道您周末会去爷爷奶奶家。我想要您带我和爷爷奶奶去参加家庭节的开幕活动，您可以……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"爸爸，我知道您周末会去爷爷奶奶家。我想要您带我和爷爷奶奶去参加家庭节的开幕活动，您可以带我们参加亲子互动游戏。活动的地点是滨海艺术中心，时间是7月1日早上十点到十一点。我们可以通过玩游戏，了解家庭成员。"},"explanation":["内容 2 分，语文 2 分，一共 4 分。","先找对活动：题目说的是“早上的活动”，就是活动一“亲子互动游戏”（上午十点到十一点）。活动二在下午，不要写。","内容第一点（地点和时间）：地点是滨海艺术中心，时间是 7 月 1 日上午十点到十一点。地点和时间各 0.5 分。","内容第二点（好处）：通过玩游戏，了解家庭成员。两个部分各 0.5 分。","语文：接着“您可以……”写下去，句子要通顺、完整，不要写错字。对爸爸说话要用“您”。"]}],"group":"chinese-2026-prelim-ai-tong-g4"},{"id":"chinese-2026-prelim-ai-tong-p2-q34","cite":"2026 Prelim Ai Tong Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“心里十分愿意”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"甘愿"},"explanation":["要找一个意思是“心里很愿意”的词语。","第二段：他非常喜欢足球，“当然不甘愿离开球队”。“不甘愿”就是心里不愿意。","答案是“甘愿”。注意不要把“不”字也写进去。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q35","cite":"2026 Prelim Ai Tong Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“终于、最后”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"总算"},"explanation":["要找一个意思是“终于”的词语。","第三段：虽然起床后还是有些拖延，“但他总算在七点半赶到了集合地点”。","答案是“总算”。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q36","cite":"2026 Prelim Ai Tong Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"明华有什么坏习惯？","marks":1,"answer":{"type":"self","value":"明华总爱迟到。","accept":["明华总是迟到。"]},"explanation":["答案在第一段：“可是他有一个坏习惯就是总爱迟到。”","写“总爱迟到”或“总是迟到”都可以。"]},{"label":"b","prompt":"对于这个坏习惯，明华的想法是什么？","marks":2,"answer":{"type":"self","value":"明华觉得迟到几分钟不是什么大事。"},"explanation":["答案在第一段最后一句：“他觉得迟到几分钟不是什么大事”。","“觉得”后面就是他的想法。“迟到”“几分钟”“不是什么大事”都要写出来。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q37","cite":"2026 Prelim Ai Tong Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":37,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"听到教练说再迟到就要受罚，明华有什么反应？","marks":2,"answer":{"type":"self","value":"明华顿时紧张了起来，连忙向教练保证他明天一定会准时到达。"},"explanation":["答案在第二段：“听了教练的话，明华顿时紧张起来。”这是第一点（1 分）。","接着他“连忙向教练保证：‘教练，我明天一定会准时到达。’”这是第二点（1 分）。","把明华说的话改成自己的句子：“我”要改成“他”。"]},{"label":"b","prompt":"他为什么会有这样的反应？","marks":2,"answer":{"type":"self","value":"因为他非常喜欢足球，不甘愿离开球队。"},"explanation":["答案在第二段：“他非常喜欢足球，当然不甘愿离开球队”。","两点各 1 分：非常喜欢足球；不甘愿离开球队。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q38","cite":"2026 Prelim Ai Tong Paper 2 Question 38","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":38,"topic":"comprehension-open","subtypes":["vocabulary-in-context","inference"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"文中“那可真是太阳从西边出来了”的意思是什么？","marks":2,"answer":{"type":"self","value":"这指的是队员们不相信明华能准时到达。"},"explanation":["太阳每天从东边出来，不可能从西边出来。所以“太阳从西边出来”比喻不可能发生的事。","队员说的是“他如果能准时出现”，所以意思是：队员们不相信明华能准时到达。"]},{"label":"b","prompt":"队员们为什么会这么说？","marks":2,"answer":{"type":"self","value":"因为以前队员们经常提醒明华不要迟到，可是明华把大家的话当耳边风。"},"explanation":["要回到第一段找原因：“队员们也经常提醒明华不要迟到，可是明华却把大家的话当成耳边风。”","两点各 1 分：队员们经常提醒他不要迟到；他把大家的话当耳边风（还是总迟到）。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q39","cite":"2026 Prelim Ai Tong Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":39,"topic":"comprehension-open","subtypes":["cause-and-effect","factual"],"format":"structured","marks":3,"difficulty":2,"stem":"明华七点半准时到了训练场地，为什么教练还是觉得明华迟到了？","parts":[{"label":"","answer":{"type":"self","value":"因为其他的队员已经做好了训练前的准备，可是明华还需要时间换衣服和热身，他还是减少了全队的训练时间。"},"explanation":["答案在第四段教练说的话里。一共三点，每点 1 分。","第一点：很多（其他）队员已经做好了训练前的准备。","第二点：明华还需要时间换衣服和热身。","第三点：这样还是减少了全队的训练时间。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-ai-tong-p2-q40","cite":"2026 Prelim Ai Tong Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Ai Tong","section":"p2","number":40,"topic":"comprehension-open","subtypes":["main-idea","opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"明华最后明白了什么道理？","marks":1,"answer":{"type":"self","value":"明华最后明白了真正的准时不只是按时到达，更应该要提前做好准备。"},"explanation":["答案在第四段教练最后说的话：“真正的准时，不只是按时到达，更应该要提前做好准备。”","接着说明华“似乎明白了其中的道理”，“其中的道理”就是这句话。"]},{"label":"b","prompt":"你同意这个道理吗？试用生活中的例子加以说明。","marks":3,"answer":{"type":"self","value":"我同意这个道理。例如：休息时间结束前，我提早回到课室，还准备好下一节课所需要的课本，这样可以开始专心上课。"},"explanation":["先表明看法：“我同意这个道理。”","然后举一个自己生活中的例子，例子要有三个部分，每部分 1 分：【事情】什么时候、什么事（例如：休息时间结束前）；【做法】我怎样提前做好准备（例如：提早回到课室，准备好下一节课的课本）；【结果】这样做有什么好处（例如：可以马上开始专心上课）。","例子可以不一样（例如：比赛前提早到场热身；出门前一晚收拾好书包），但是一定要说到“提前做好准备”。","不要再抄短文里明华的事，题目要的是“生活中的例子”。"]}],"group":"chinese-2026-prelim-ai-tong-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q1","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 1","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n尤金是新加坡++著名++的作家。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“著”是翘舌音 zhù，不是平舌音 zù。","“名”是后鼻音 míng，不是前鼻音 mín。","“著名”读 zhù míng，答案是（4）。"]}],"options":["zù mín","zù míng","zhù mín","zhù míng"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q2","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 2","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n每逢过年，牛车水都充满了浓浓的春节++气氛++。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“气”的声母是 q，读 qì，不是 cì。","“氛”读第一声 fēn，不是第四声 fèn。","“气氛”读 qì fēn，答案是（3）。"]}],"options":["cì fēn","cì fèn","qì fēn","qì fèn"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q3","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 3","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n奶奶在食堂______了一个摊位卖豆花水。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“租”是付钱借用别人的地方或东西，“租摊位”就是付租金用这个摊位做生意。","“组”是小组的组，“祖”是祖父的祖，“阻”是阻止的阻，样子很像，但意思不对。","答案是（2）租。"]}],"options":["组","租","祖","阻"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q4","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 4","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n店内的______售员热情地向顾客介绍商品。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“销售”的意思是卖东西，“销售员”就是卖东西的人。","“销”是金字旁；“消”是消失的消，读音一样，但意思是不见了。","答案是（3）销。"]}],"options":["稍","消","销","悄"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q5","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 5","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n考试快到了，老师______我们要复习功课。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“提醒”是怕别人忘记，特地告诉他。考试快到了，老师怕我们忘记复习，所以提醒我们。","“命令”是上级一定要下级照着做，语气太重；“请求”是求别人帮忙，老师不会请求学生。","答案是（4）提醒。"]}],"options":["教导","命令","请求","提醒"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q6","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 6","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n花木兰在战场上英勇杀敌，______自己的国家。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“保卫”是保护国家、家园，不让敌人侵犯，常说“保卫国家”。","“保管”是看管东西，“保持”是让情况不改变（保持安静），“保证”是答应一定做到。","答案是（3）保卫。"]}],"options":["保管","保持","保卫","保证"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q7","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 7","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n我++打败++所有的对手，取得了冠军。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“打败”在这里的意思是在比赛中胜过对方，也就是赢了对方。","句子后面说“取得了冠军”，所以是赢了所有的对手。","“攻打对手”只是去打，不一定赢。答案是（1）。"]}],"options":["赢了对手","赶走对手","推倒对手","攻打对手"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q8","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 8","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n听了哥哥的解释后，我++恍然大悟++，发现我错怪了他。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“恍然大悟”的意思是一下子明白过来。“悟”就是明白。","听了解释以后才知道自己错怪了哥哥，所以是突然明白。","“突然想起”是记起以前的事，不是明白道理。答案是（2）。"]}],"options":["突然醒来","突然明白","突然猜中","突然想起"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q9","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 9","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______明天是否下雨，我们______会去探望外婆。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“是否下雨”有两种情况：下雨或不下雨。两种情况结果都一样，要用“不管……都”。","“就算……也”后面只能跟一种情况（就算下雨，也会去），不能跟“是否”。","答案是（2）不管……都。"]}],"options":["如果……就","不管……都","除了……还","就算……也"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q10","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 10","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______我们有时间，______去老人院做义工。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“反正”表示情况已经确定：我们有时间。“不如”用来提出建议：去老人院做义工。","“与其……不如”是在两件事里选后一件，可是“我们有时间”不是一件可以选的事。","答案是（4）反正……不如。"]}],"options":["与其……不如","除非……不然","尽管……还是","反正……不如"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q11","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 11","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n一开始我对新学校感到陌生，______。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“一开始”后面常常接“后来”，说明情况有了改变。","“陌生”的反义词是“熟悉”：一开始陌生，后来慢慢熟悉了。","（3）认识新朋友和“感到陌生”接不上，中间少了“后来”。答案是（2）。"]}],"options":["总是忘记完成作业","后来就慢慢熟悉了","认识了很多新朋友","时不时被老师批评"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q12","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 12","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______，才把钢琴搬上楼。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“才”表示事情很不容易做到，前面要说花了很大的力气。","“九牛二虎之力”比喻很大的力气，和“才把钢琴搬上楼”配得上。","“不费吹灰之力”是非常容易，后面不能用“才”。答案是（4）。"]}],"options":["搬家工人不费吹灰之力","同学们浪费了很多体力","我和妹妹花费不少日子","爸爸费了九牛二虎之力"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q13","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 13","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“表达”是用话、文字或作品把心里的想法和感情说出来。","（4）用一首歌说出对祖国的热爱，用得对。","（1）应该用“表示”，（2）应该用“称赞”，（3）应该用“表现”。","答案是（4）。"]}],"options":["爸爸点点头++表达++同意大家的看法。","老师++表达++他是个乐于助人的孩子。","我们在比赛中有非常出色的++表达++。","我写了一首歌++表达++对祖国的热爱。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q14","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 14","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“津津有味”形容吃东西很香，或者看书、听故事很有兴趣。","（3）听故事听得很有兴趣，用得对。","准备晚餐、打扫课室、回答问题是做事，不能说“津津有味”，可以用“认真”。","答案是（3）。"]}],"options":["放工回家之后，妈妈++津津有味++地准备晚餐。","一大早，校工阿姨就++津津有味++地打扫课室。","华文课上，我们++津津有味++地听老师讲故事。","考试时，同学们++津津有味++地回答每道问题。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q15","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 15","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“贴心”形容一个人很会关心别人，知道别人需要什么。","（3）看到爷爷冷，就为他披上外套，是很贴心的做法。","（1）应该用“耐心”，（2）应该用“细心”，（4）“贴心”后面不能直接跟人，应该用“关心”。","答案是（3）。"]}],"options":["我们有问题时，老师都会++贴心++地为我们解答。","我需要更加++贴心++，才不会犯这种粗心的错误。","看到爷爷冷得发抖，我++贴心++地为他披上外套。","妹妹会++贴心++爸爸妈妈，体谅他们工作的辛苦。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q16","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 16","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["空格前面是“觉得十分”，后面要填形容词。“觉得十分有趣”就是觉得很有意思。","“乐趣”和“兴趣”是名词，不能说“十分乐趣”；“风趣”形容人说话幽默。","答案是（2）有趣。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g1","options":["乐趣","有趣","兴趣","风趣"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q17","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 17","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“一点动静都没有”是固定说法，意思是什么变化都没有——种子没有发芽。","“反应”是受到刺激以后的回应，种子发芽不说“反应”。","答案是（4）动静。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g1","options":["反应","声音","影响","动静"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q18","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 18","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["第一次种花失败了，小云决定“再试一次”。“尝试”就是试着做。","“坚持”是不停地做下去，不能说“再坚持一次”种花。","答案是（2）尝试。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g1","options":["制作","尝试","练习","坚持"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q19","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 19","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["前两次因为种得太深、太心急而失败，这次小云要很注意，所以是“小心地种下”。","“详细”形容内容很多很清楚（详细的计划），不能形容种种子的动作。","答案是（3）小心。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g1","options":["努力","详细","小心","勇敢"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q21","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 21","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"马丽在去面试的路上发生了什么事情？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["找到第一段：“半路上，马丽碰见一名突然昏倒的女孩”。","接到院长的电话是几天后的事；脸色发白的是女孩，不是马丽。","答案是（2）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g2","options":["她接到院长的电话。","她看见女孩昏倒了。","她的脸色变得苍白。","她遇见医院的医生。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q23","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 23","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"马丽没有后悔帮女孩，因为","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["找到第二段最后：“但是她并不后悔。她认为救人比面试重要。”","第二次面试是几天后才知道的，她不后悔的时候还不知道。","答案是（1）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g2","options":["救人比参加面试更重要。","那名医生最后认出了她。","展示医术的机会很难得。","她有第二次面试的机会。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q24","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 24","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一项++不是++院长让马丽再参加面试的原因？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["注意题目问的是“不是”原因的一项。","院长说：他听说了马丽救人的事（3），她具备了医生最重要的品德（4），失去这样的医生会非常可惜（2）。","院长没有说是因为马丽很想来面试。答案是（1）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g2","options":["因为马丽非常希望到医院面试当医生。","因为失去马丽这样的医生会非常可惜。","因为马丽为了救人而错失第一次面试。","因为马丽拥有作为医生最重要的品德。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q25","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 25","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"这个故事告诉我们什么道理？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["道理常常在故事最后。院长说：“一名医生最重要的不是医术，而是拥有一颗善良的心和强烈的责任感。”","马丽因为善良和有责任感，最后得到了工作。","（1）和（4）只是故事里的小事，不是整个故事要说的道理。答案是（2）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g2","options":["发烧时一定要到阴凉的地方去。","善良的心和责任感都非常重要。","要把遇到的好人好事都说出来。","救人后要确保对方没事才离开。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q26","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 26","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 9）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["我昨天在学校网站上看到活动通知","6 我昨天在学校网站上看到活动通知"]},"explanation":["伟明问“你有没有看到……活动通知？”，小丽回答“有啊！”，后面要说她在哪里看到。","选 6：我昨天在学校网站上看到活动通知。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g3"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q27","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 27","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 9）","parts":[{"label":"","answer":{"type":"text","value":"1","accept":["这项活动很有意义","1 这项活动很有意义"]},"explanation":["伟明说活动是为了帮助有需要的儿童。小丽接着说“我们应该积极参加”，前面要先说她对活动的看法。","帮助别人是有意义的事，所以选 1：这项活动很有意义。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g3"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q28","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 28","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 9）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["我打算把家里一些新的文具捐出来","8 我打算把家里一些新的文具捐出来"]},"explanation":["小丽问“你会怎么帮助他们呢？”，伟明要回答他的做法。活动收集的是文具用品。","小丽接着称赞“这样既不会浪费资源，也能帮助别人”——家里没用的新文具捐出来，就不会浪费。","选 8：我打算把家里一些新的文具捐出来。（2 说的是旧课本，不是文具，而且前面没有人说过要捐，不能用“也”。）"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g3"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q29","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 29","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 9）","parts":[{"label":"","answer":{"type":"text","value":"5","accept":["如果大家都愿意献出一份爱心","5 如果大家都愿意献出一份爱心"]},"explanation":["空格后面是“就能帮助更多有需要的儿童”。“如果……就……”是一对关联词。","伟明希望更多同学参加，小丽同意，所以选 5：如果大家都愿意献出一份爱心。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g3"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q30","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 30","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"这则海报的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["标题是“武术班招生啦！”，第一句是“想让你的孩子更健康吗？欢迎参加武术班！”","“招生”就是请人来报名，海报是写给家长看的。","上课详情只是海报的一部分内容，不是主要目的。答案是（4）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g4","options":["通知所有的家长上课的详情。","教导学生更好的与他人合作。","请儿童和家长一起锻炼身体。","吸引家长替孩子报名武术班。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q31","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 31","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一项有关活动的内容是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看表格：初级班学费 640 元，高级班 720 元，初级班比较便宜，（1）对。","（2）只有前 10 位报名者有礼物；（3）招生人数有限，不一定能参加；（4）没学过武术的上初级班，是每周六上课。","答案是（1）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g4","options":["武术初级班的学费会比高级班便宜。","每个报名的学生都可以获得小礼物。","只要报名的学生一定能参加武术班。","没学过武术的学生得在星期天上课。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q32","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 32","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"如果家长有疑问，应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["找到海报最后一段：“如果你有疑问，可拨打 61234567 向办公室的李珍珍女士询问。”","“拨打”就是打电话。网站是用来报名的，不是用来问问题的。","答案是（4）。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g4","options":["仔细阅读海报上面的内容。","可上武术俱乐部网站查看。","到武术俱乐部课室问老师。","打电话向李珍珍女士询问。"]},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q33","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 33","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是丽文，看了这则海报后，从没学过武术的你希望学武术，想请妈妈帮你报名参加。请写一则短信给妈妈，告诉她武术班的详情和报名方式。\n\n短信的开头是：\n妈妈，我希望到武术俱乐部的武术班学习。我想报名参加……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"妈妈，我希望到武术俱乐部的武术班学习。我想报名参加初级班。课程从8月22日至10月25日，每周六上午10时至11时30分，在武术俱乐部七楼课室上课。学费是640元，共8节课。由于名额有限，请您尽早上网 www.wushujulebu.com.sg 替我报名。"},"explanation":["内容 2 分，表达 2 分，一共 4 分。","先选对班级：丽文从没学过武术，所以要报名参加“初级班”。","武术班的详情：在海报里找初级班的日期（8月22日至10月25日）、上课时间（每周六上午10点至11点30分）、地点（武术俱乐部七楼课室）和学费（640元，8节课）。","报名方式：在海报最后一段找——尽早上网 www.wushujulebu.com.sg 报名。","不要抄高级班的资料（每周日、720元）。","表达：接着“我想报名参加……”写下去，句子要通顺、完整，对妈妈要有礼貌（用“请您”），不要写错字。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g4"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q34","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 34","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“认真地做事，非常努力”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"勤奋"},"explanation":["要找一个意思是“做事认真、很努力”的词语。","第五段：“杰克勤奋地工作，表现很优秀”。","答案是“勤奋”。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q35","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 35","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“通过言语或行动让人充满信心”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"鼓励"},"explanation":["要找一个意思是“说话或做事让别人有信心”的词语。","第五段：“他非常感激母亲当年给他的鼓励”，后面还有“母亲鼓励我，让我重新找回信心”。","答案是“鼓励”。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q36","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 36","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"杰克在学校遇到了什么困难？","marks":2,"answer":{"type":"self","value":"杰克在课堂上总是无法回答老师的问题，成绩也一直不理想。","accept":["杰克在课堂上总是无法回答老师的问题，而且他的理解能力较差。"]},"explanation":["有两点，各 1 分，都要写。","答案在第一段第一句：“杰克在课堂上总是无法回答老师的问题，成绩也一直不理想”。","第二点也可以写第二段老师说的“理解能力较差”。"]},{"label":"b","prompt":"这困难对他有什么影响？","marks":1,"answer":{"type":"self","value":"他每天闷闷不乐，晚上还经常做恶梦。"},"explanation":["“因此”后面就是影响。第一段：“因此他每天闷闷不乐，晚上还经常做恶梦”。","两样都写出来：闷闷不乐，经常做恶梦。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q37","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 37","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":37,"topic":"comprehension-open","subtypes":["cause-and-effect","inference"],"format":"structured","marks":2,"difficulty":2,"stem":"母亲为什么决定亲自教导杰克？","parts":[{"label":"","answer":{"type":"self","value":"因为老师告诉母亲杰克的理解能力较差，母亲担心他无法取得好成绩，想亲自帮助他提高学习成绩。"},"explanation":["有两点，各 1 分。","第一点在第二段：老师告诉母亲“杰克的理解能力较差，恐怕无法取得好成绩”。","第二点要自己想一想：母亲听后很伤心，她担心杰克，所以想亲自帮助他提高成绩（第三段：“都无法提高学习成绩”说明母亲教他的目的）。","用“因为……”开头回答“为什么”。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q38","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 38","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":38,"topic":"comprehension-open","subtypes":["factual","inference"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"母亲是怎样帮助杰克实现梦想的？","marks":1,"answer":{"type":"self","value":"母亲发现杰克对设计有兴趣，一直想成为一名杰出的设计师，便让他去上设计课。"},"explanation":["答案在第三段最后一句：母亲发现杰克对设计有兴趣，“便让他去上设计课”。","要写出母亲做了什么：让他去上设计课。"]},{"label":"b","prompt":"从哪里可以看出杰克实现了梦想？","marks":3,"answer":{"type":"self","value":"很多人前去面试，但艺术品公司只请了杰克一位设计师。杰克勤奋地工作，表现很优秀。他还在多次塑像设计比赛中获得冠军。"},"explanation":["3 分要写三点，在第四段和第五段找。","第一点（第四段）：很多人去面试，公司只请了杰克一位设计师。","第二点（第五段）：杰克勤奋地工作，表现很优秀。","第三点（第五段）：他在多次塑像设计比赛中获得冠军。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q39","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 39","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":39,"topic":"comprehension-open","subtypes":["character-and-feelings","opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"你认为母亲是一个怎样的人？请举文中的例子加以说明。","parts":[{"label":"","answer":{"type":"self","value":"我认为母亲是一位关爱孩子、善于鼓励并懂得因材施教的人。杰克因成绩差而说自己太笨时，她没有否定他，反而鼓励他重拾信心；发现他喜欢设计后，她让他上设计课，帮助他发挥长处。"},"explanation":["判断 2 分，例子 2 分。","先说母亲是怎样的人，例如：关爱孩子、善于鼓励孩子、有耐心、懂得按孩子的长处来教（因材施教）。","再用短文里的事来证明。第三段：杰克说“我太笨了”，母亲说“孩子，你并不笨！”，鼓励他；后来发现他对设计有兴趣，就让他去上设计课。","只写“母亲是好人”太笼统；只写例子没有判断，也拿不到满分。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p2-q40","cite":"2026 Prelim CHIJ St Nicholas Paper 2 Question 40","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p2","number":40,"topic":"comprehension-open","subtypes":["main-idea","opinion"],"format":"structured","marks":5,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"你从这篇文章中明白了什么道理？","marks":2,"answer":{"type":"self","value":"我明白了每个人都有自己的长处和短处，不应只因一方面表现不好就否定自己。只要了解自己，找到适合自己的方向并坚持努力，就能取得成功。"},"explanation":["有两点，各 1 分。","道理在最后一段：“每个人都有自己的长处，只要了解自己，找到适合自己的方向，并坚持努力，就能取得成功。”","第一点：每个人都有长处，不要因为一方面做不好就否定自己。第二点：了解自己，找到适合的方向，坚持努力，就能成功。"]},{"label":"b","prompt":"试举一个例子说明你如何把这个道理应用在生活中。","marks":3,"answer":{"type":"self","value":"（开放式题目，没有固定答案。）示范：例如，我的数学成绩不理想，但我很喜欢画画。我不会因此否定自己，而会参加美术班、虚心请教老师并每天坚持练习，努力提升绘画技巧，争取在比赛中取得好成绩。"},"explanation":["例子 3 分，要包括三样：具体的情况、符合道理的行动、持续努力或希望得到的成果。","具体的情况：说清楚自己哪方面不好、哪方面是长处，例如“数学成绩不理想，但很喜欢画画”。","行动：怎样发挥长处，例如参加美术班、请教老师。","持续努力和成果：每天坚持练习，争取在比赛中取得好成绩。","例子要写自己的生活，不要再抄杰克的故事。"]}],"group":"chinese-2026-prelim-chij-st-nicholas-g5"},{"id":"chinese-2026-prelim-chij-st-nicholas-p1-q1","cite":"2026 Prelim CHIJ St Nicholas Paper 1 Question 1","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p1","number":1,"topic":"writing","subtypes":["topic-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第一题：我终于战胜了自己\n\n在作文时，你可以参考下面的提示：\n• 这是一件什么事\n• 这件事是怎么发生的\n• 你有什么感受\n• 你从这件事中学到了什么","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：重点是“战胜了自己”——要写自己克服了心里的一个弱点，例如害怕、紧张、懒惰、怕失败、想放弃。“终于”说明这件事不容易，中间要有挣扎。","开头：直接点出自己的弱点，例如“我从小就害怕上台说话”，或者从最紧张的那一刻写起。","经过：写清楚是什么事、怎么发生的。先写自己怎样害怕、想退缩，再写是谁或什么事让自己决定试一试，然后写自己怎样一步一步做到。要多写心理活动（心怦怦直跳、手心冒汗、对自己说“我可以的”）。","结尾：写做到以后的感受（松了一口气、心里像吃了蜜一样甜），再写学到的道理，例如只要勇敢面对，就没有克服不了的困难。","好词好句：忐忑不安、心惊胆战、鼓起勇气、咬紧牙关、坚持不懈、如释重负；“世上无难事，只怕有心人。”","检查：四个提示都写到了吗？字数在 100 以上吗？有没有错别字？"]}]},{"id":"chinese-2026-prelim-chij-st-nicholas-p1-q2","cite":"2026 Prelim CHIJ St Nicholas Paper 1 Question 2","year":2026,"exam":"Prelim","school":"CHIJ St Nicholas","section":"p1","number":2,"topic":"writing","subtypes":["picture-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题。\n\n第二题：仔细看下列的图，根据图意，完成一篇短文。字数需在 100 以上。在作文时，你可以参考所提供的词语。\n[[img1]]\n参考词语：背着书包　人行道　骑脚踏车　撞　受伤　逃走　阻止　惭愧","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：六幅图要全部写到。故事是：放学路上，两个男生看见骑脚踏车的人撞倒小女孩后想逃走，他们阻止了他并帮助小女孩。第六幅是问号，要自己想一个合理的结局。","开头（图一）：写时间、地点、人物，例如放学后，“我”和同学背着书包走出校门。可以给人物取名字。","经过（图二到图五）：一个男生在人行道上骑脚踏车骑得很快，撞倒了小女孩；他不但没有停下来，还想逃走；“我”冲上前张开双手阻止他；同学扶起受伤的小女孩，安慰她；我们告诉骑车的男生他做错了什么，他低下头，很惭愧。要写人物的动作、说的话和心情。","结尾（图六）：自己想结局，例如骑车的男生向小女孩道歉，我们一起送她回家或去看医生，她的父母感谢我们。最后写感想：做错事要勇敢承担，看到别人有困难要伸出援手，在人行道上骑车要小心。","好词好句：飞快、横冲直撞、说时迟那时快、二话不说、挺身而出、面红耳赤、惭愧地低下头、知错能改、助人为快乐之本。","检查：参考词语用上了吗？六幅图都写到了吗？字数在 100 以上吗？"]}],"images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-p1-q2-img1","alt":"六幅图。①两个男生背着书包走出校门。②人行道上，一个骑脚踏车的男生撞倒了一个小女孩，两个男生在旁边看见了。③小女孩倒在地上，骑车的男生想骑走，两个男生追上去。④一个男生张开双手拦住骑车的男生，另一个男生在后面。⑤一个男生蹲下来安慰坐在地上哭的小女孩，另一个男生叉着腰对低着头的骑车男生说话。⑥问号，要自己想结局。"}]},{"id":"chinese-2026-prelim-henry-park-p2-q1","cite":"2026 Prelim Henry Park Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n大家对他助人为乐的行为连声++称赞++。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“称”是后鼻音 chēng，不是前鼻音 chēn。","“赞”读第四声 zàn，不是第一声 zān。","“称赞”读 chēng zàn，答案是（3）。"]}],"options":["chēn zān","chēn zàn","chēng zàn","chēng zān"]},{"id":"chinese-2026-prelim-henry-park-p2-q2","cite":"2026 Prelim Henry Park Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n我们不应该++妒忌++别人的才能。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“妒”的声母是 d，读 dù，不是 tù。","“忌”读第四声 jì，不是第二声 jí。","“妒忌”读 dù jì，答案是（1）。"]}],"options":["dù jì","dù jí","tù jí","tù jì"]},{"id":"chinese-2026-prelim-henry-park-p2-q3","cite":"2026 Prelim Henry Park Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n马上要______业了，同学们都舍不得和朋友分开。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“毕业”的意思是在学校学习期满，完成学业。同学们要分开，是因为要毕业了。","“闭”是“关闭”的闭，“币”是“钱币”的币，“必”是“必须”的必，读音一样，但意思不对。","答案是（4）毕。"]}],"options":["闭","币","必","毕"]},{"id":"chinese-2026-prelim-henry-park-p2-q4","cite":"2026 Prelim Henry Park Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这本新书在上个月出______了。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“出版”的意思是把书印出来，让大家可以买到。","“板”是“木板、黑板”的板，样子和读音都很像，但是和书没有关系；“贩”是“小贩”的贩。","答案是（1）版。"]}],"options":["版","贩","板","饭"]},{"id":"chinese-2026-prelim-henry-park-p2-q5","cite":"2026 Prelim Henry Park Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n他画的小猫很______，就像要从画纸跳出来一样。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“生动”的意思是像活的一样，很有活力。“就像要从画纸跳出来一样”说明小猫画得像真的。","“清楚”只是说看得明白，不能表示“像活的一样”。","答案是（2）生动。"]}],"options":["整齐","生动","巧妙","清楚"]},{"id":"chinese-2026-prelim-henry-park-p2-q6","cite":"2026 Prelim Henry Park Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n食物都需要经过______，才能安全食用。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“检验”的意思是检查、化验，看看合不合格。食物检验合格了，才可以“安全食用”。","“搅拌”“保温”“调味”都是煮食物时做的事，和吃得安不安全没有关系。","答案是（1）检验。"]}],"options":["检验","搅拌","保温","调味"]},{"id":"chinese-2026-prelim-henry-park-p2-q7","cite":"2026 Prelim Henry Park Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n一到过年，购物中心就会举办各种++促销++活动。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“促”是促进、推动，“销”是销售。“促销”就是用打折、送礼物等方法，让商品卖得更多。","“售卖多种商品”只是说卖的东西种类多，没有“推动”的意思。","答案是（2）推动商品销售。"]}],"options":["售卖多种商品","推动商品销售","延长售卖时间","增加销售人员"]},{"id":"chinese-2026-prelim-henry-park-p2-q8","cite":"2026 Prelim Henry Park Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n如果你想成为读书会的会员，要先填写++申请++表格。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“申请”的意思是向有关的人或机构说明理由，提出请求。","“上网报名”只是申请的其中一种方法，句子里是“填写表格”，不一定是上网。","答案是（2）提出请求。"]}],"options":["上网报名","提出请求","找人查问","报告老师"]},{"id":"chinese-2026-prelim-henry-park-p2-q9","cite":"2026 Prelim Henry Park Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":9,"topic":"sentences","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n他不努力还想发财，______在做白日梦。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“简直”表示完全是这样，有强调、夸张的语气。“简直在做白日梦”是说他的想法完全不可能实现。","“竟然”表示没想到；“明明”后面通常要有转折（明明……却……）；“大约”表示估计。","答案是（3）简直。"]}],"options":["大约","明明","简直","竟然"]},{"id":"chinese-2026-prelim-henry-park-p2-q10","cite":"2026 Prelim Henry Park Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n他上课不专心，______在睡觉，______在讲话。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“不是……就是……”表示两种情况里一定有一种。他上课的时候，有时睡觉，有时讲话，总之不专心。","“一边……一边……”表示两件事同时做，可是一个人不能一边睡觉一边讲话。","答案是（4）不是……就是。"]}],"options":["首先……然后","即使……也要","一边……一边","不是……就是"]},{"id":"chinese-2026-prelim-henry-park-p2-q11","cite":"2026 Prelim Henry Park Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n我们原本要去野餐，____________。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“原本”的意思是本来打算这样做，后来情况改变了，所以后面要接一个转折。","“可是下雨不能去了”说出了改变的情况，和“原本”配合。","其他三个选项都没有说出计划改变了。答案是（2）。"]}],"options":["幸好公园景色宜人","可是下雨不能去了","全家人都开心极了","因为星期天不上学"]},{"id":"chinese-2026-prelim-henry-park-p2-q12","cite":"2026 Prelim Henry Park Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，看是否能想出办法。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“看是否能想出办法”是说试一试，看看能不能找到办法，所以前面要先说做一件什么事。","“我们可以一起开会”是一个完整的建议：先开会，再看能不能想出办法。","“只要……”要配“就”，“如果……”要配“就”，后面接“看是否能……”不通顺；已经“做出决定”就不必再想办法了。答案是（2）。"]}],"options":["只要大家一起努力","我们可以一起开会","如果每个人都思考","他们终于做出决定"]},{"id":"chinese-2026-prelim-henry-park-p2-q13","cite":"2026 Prelim Henry Park Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“促进”是动词，意思是推动事情向好的方向发展，如：促进健康、促进了解。","（1）好习惯推动身体变得更健康，用得对。","（2）应该用“催促”，（3）应该用“促销”，（4）应该用“进步”。","答案是（1）。"]}],"options":["良好的生活习惯可以++促进++身体健康。","妈妈每天早上都要++促进++我快点上学。","这间商店正举办一年一度的大++促进++。","小林这学期的成绩有了明显的++促进++。"]},{"id":"chinese-2026-prelim-henry-park-p2-q14","cite":"2026 Prelim Henry Park Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“独特”是形容词，意思是特别的、和别的不一样。","（2）说书法是一门和别的艺术不一样的艺术，用得对。","（1）应该用“独立”或“独自”，（3）应该用“特地”，（4）应该用“独立”。","答案是（2）。"]}],"options":["明文总是喜欢++独特++地完成作业。","汉字书法是一门很++独特++的艺术。","今天早上，她++独特++准备了早餐。","弟弟非常++独特++，可以自己煮饭。"]},{"id":"chinese-2026-prelim-henry-park-p2-q15","cite":"2026 Prelim Henry Park Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“热心”的意思是很愿意、很主动地去帮助别人或为大家做事。","（4）别人有需要，他主动帮忙，用得对。","（1）招呼客人应该用“热情”，（2）加油应该用“热烈”或“热情”，（3）教弟弟写字应该用“耐心”。","答案是（4）。"]}],"options":["周末，奶奶非常++热心++地招呼客人吃饭。","运动会上，同学++热心++地为运动员加油。","一有空，妈妈就会++热心++地教弟弟写字。","有需要帮助的事，他都会++热心++地帮忙。"]},{"id":"chinese-2026-prelim-henry-park-p2-q16","cite":"2026 Prelim Henry Park Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“了所有含糖饮料，改成用新鲜果汁代替”，意思是家里不准再喝含糖饮料了。","“禁止”是不准许做某件事。“阻拦”是拦住人不让他走或做事，“拒绝”是不接受别人的请求或东西，都不合适。","答案是（1）禁止。"]}],"group":"chinese-2026-prelim-henry-park-g1","options":["禁止","阻拦","拒绝","收拾"]},{"id":"chinese-2026-prelim-henry-park-p2-q17","cite":"2026 Prelim Henry Park Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["早上运动以后，上课时不会觉得累、想睡觉，这叫“有精神”。后面“做事情也更专心了”也说明他精神好。","“力量”是指力气，上课不需要很大的力气。","答案是（2）精神。"]}],"group":"chinese-2026-prelim-henry-park-g1","options":["力量","精神","意义","耐心"]},{"id":"chinese-2026-prelim-henry-park-p2-q18","cite":"2026 Prelim Henry Park Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":18,"topic":"cloze","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["前一段讲饮食和晨跑，这一段另外再讲一件事：参加羽毛球队。后面有“还”字。","“此外”的意思是除了上面说的以外，可以放在一段的开头，后面用逗号。“而且”后面一般不加逗号，也不放在新一段的开头。","答案是（2）此外。"]}],"group":"chinese-2026-prelim-henry-park-g1","options":["所以","此外","而且","然后"]},{"id":"chinese-2026-prelim-henry-park-p2-q19","cite":"2026 Prelim Henry Park Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":19,"topic":"cloze","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["后面有“也”：“______坚持运动，睡眠也同样重要”。“除了……也……”表示两样都重要。","“要是”要配“就”，“只有”要配“才”，都接不上“也同样重要”。","答案是（3）除了。"]}],"group":"chinese-2026-prelim-henry-park-g1","options":["要是","只有","除了","或者"]},{"id":"chinese-2026-prelim-henry-park-p2-q20","cite":"2026 Prelim Henry Park Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["空格后面是“了五公斤”，有数量。可以说“减少了五公斤”。","“消失”是完全不见了，体重不会消失；“控制了五公斤”“调节了五公斤”都说不通。","答案是（4）减少。"]}],"group":"chinese-2026-prelim-henry-park-g1","options":["调节","消失","控制","减少"]},{"id":"chinese-2026-prelim-henry-park-p2-q21","cite":"2026 Prelim Henry Park Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"从哪里可以看出大家对球球很“热情”？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["找到第一段：“后来，大家变得很‘热情’，都试着伸手进箱子里要摸它。”","“热情”后面紧接着说的就是大家的做法：都想伸手摸球球。","“小心地对待”是“起初”的事，是在变得“热情”以前。答案是（2）。"]}],"group":"chinese-2026-prelim-henry-park-g2","options":["大家都特别喜欢球球。","大家都很想摸摸球球。","大家小心地对待球球。","大家都想让自己快乐。"]},{"id":"chinese-2026-prelim-henry-park-p2-q22","cite":"2026 Prelim Henry Park Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"“我”为什么要打开箱子的盖？因为______","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看第三段“我”心里想的话：“它会不会觉得闷？出来外面跑会不会更开心？”","“我”是想让球球出来跑一跑，更开心，才打开盖子的。","“我”当时在打扫课室，但不是要扫箱子；“我”已经“不再急着摸它”了。答案是（3）。"]}],"group":"chinese-2026-prelim-henry-park-g2","options":["“我”想喂球球吃东西。","“我”想扫球球的箱子。","“我”想让球球更快乐。","“我”想抓球球出来摸。"]},{"id":"chinese-2026-prelim-henry-park-p2-q23","cite":"2026 Prelim Henry Park Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["inference","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"老师找到球球后，为什么没有骂“我”？因为______","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["看第五段老师说的话：“老师知道你不是故意的……”","“不是故意的”就是说“我”并不是想伤害球球，所以老师没有骂“我”。","那时候“我”还不知道自己错在哪里，是听了老师的话才明白的，所以（2）不对。答案是（4）。"]}],"group":"chinese-2026-prelim-henry-park-g2","options":["她认为“我”是在跟球球玩。","她看到“我”已经知道错了。","她已经把球球放回箱子里了。","她知道“我”没想伤害球球。"]},{"id":"chinese-2026-prelim-henry-park-p2-q24","cite":"2026 Prelim Henry Park Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["character-and-feelings","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"文中“我红着脸，默默地点了点头”表现出“我”怎样的心情？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["这句话在第六段。老师告诉“我”：“爱不是给它你想给的，而是给它它需要的。”","“我”明白自己做错了，吓到了球球，觉得不好意思，所以脸红、点头。这种心情是“羞愧”。","“害怕”是老师刚走进课室时的心情（吓得脸色苍白），不是这时候的。答案是（3）。"]}],"group":"chinese-2026-prelim-henry-park-g2","options":["悲伤","感动","羞愧","害怕"]},{"id":"chinese-2026-prelim-henry-park-p2-q25","cite":"2026 Prelim Henry Park Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["character-and-feelings","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"文中的老师是一个怎样的人？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["老师没有骂“我”，而是“温柔地问我”，说明她很温柔。","她用一块饼干就把球球引出来，又用“喜欢和占有是两回事”“爱是给它它需要的”这些话让学生自己明白道理，说明她有智慧。","老师没有骂人，所以不是“严厉”。答案是（2）。"]}],"group":"chinese-2026-prelim-henry-park-g2","options":["严厉、有勇气","温柔、有智慧","冷静、有信心","幽默、有创意"]},{"id":"chinese-2026-prelim-henry-park-p2-q26","cite":"2026 Prelim Henry Park Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["最近邻居们都互不来往","6 最近邻居们都互不来往"]},"explanation":["王阿姨说很少看到大家聚在一起聊天，小李回答“是啊”，表示同意，接着要说差不多的情况。","空格后面是“大家下班回来都关着门”，说的是邻居之间没有来往。","所以选 6：最近邻居们都互不来往。"]}],"group":"chinese-2026-prelim-henry-park-g3"},{"id":"chinese-2026-prelim-henry-park-p2-q27","cite":"2026 Prelim Henry Park Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["我们可以主动打招呼","4 我们可以主动打招呼"]},"explanation":["王阿姨问“我们该怎么改善呢？”，小李要说出一个办法。","后面是“慢慢地和邻居增进感情”，王阿姨还举例“在电梯里遇到邻居，可以微笑点头”，这是打招呼的例子。","所以选 4：我们可以主动打招呼。"]}],"group":"chinese-2026-prelim-henry-park-g3"},{"id":"chinese-2026-prelim-henry-park-p2-q28","cite":"2026 Prelim Henry Park Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["还能认识住在周围的邻居","8 还能认识住在周围的邻居"]},"explanation":["小李说多参加民众俱乐部的活动，可以“充实自己的生活”，空格是参加活动的另一个好处。","王阿姨接着说“就像我们俩一样，是因为一起参加义工活动而认识的”，说明空格讲的是“认识”邻居。","所以选 8：还能认识住在周围的邻居。"]}],"group":"chinese-2026-prelim-henry-park-g3"},{"id":"chinese-2026-prelim-henry-park-p2-q29","cite":"2026 Prelim Henry Park Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"5","accept":["并且积极地和邻居交流","5 并且积极地和邻居交流"]},"explanation":["前面是“我们应该多参加社区活动”，空格要接着说还应该做什么，“并且”正好用来连接两件该做的事。","后面是“让邻居之间的关系越来越好”，多和邻居交流，关系才会越来越好。","所以选 5：并且积极地和邻居交流。"]}],"group":"chinese-2026-prelim-henry-park-g3"},{"id":"chinese-2026-prelim-henry-park-p2-q30","cite":"2026 Prelim Henry Park Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience","main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"这则通告主要是要告诉大家______。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["通告的主要内容通常在开头。第一段说：爱心领养中心即将举办“给它一个家，给你一份爱”的领养活动。","礼包、时间、网站都只是活动里的一个小部分，不是“主要”要告诉大家的事。","答案是（3）。"]}],"group":"chinese-2026-prelim-henry-park-g4","options":["领养中心将赠送领养者新手礼包。","领养者可以领养流浪猫狗的时间。","领养中心将举办动物领养的活动。","领养者需上领养中心的网站查询。"]},{"id":"chinese-2026-prelim-henry-park-p2-q31","cite":"2026 Prelim Henry Park Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一项++不是++活动期间提供的优待？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看“贴心配套”：动物已经过健康检查、去虫并打了预防针；领养后有三个月的免费行为指导和兽医服务。","关于保险，通告写的是“购买终身宠物保险将享有八折的折扣”。八折是要付钱的，不是免费。","所以“终身免费宠物保险”不是通告里的优待。答案是（3）。"]}],"group":"chinese-2026-prelim-henry-park-g4","options":["健康检查与去虫。","已经打了预防针。","终身免费宠物保险。","三个月的兽医服务。"]},{"id":"chinese-2026-prelim-henry-park-p2-q32","cite":"2026 Prelim Henry Park Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":32,"topic":"functional-text","subtypes":["factual","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一句话是++不++正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["（1）（2）（3）都可以在通告里找到：三个月的免费宠物行为指导、上网站查看宠物的照片和基本信息、全岛共有 8 家分店。","看“注意”那一行：“活动结束之后领养动物不再享有优待。”这说明 7 月以后还是可以领养，只是没有优待。","所以“只能在2026年7月领养”是不正确的。答案是（4）。"]}],"group":"chinese-2026-prelim-henry-park-g4","options":["领养后可获得三个月免费行为指导。","可上网查看可领养动物的基本信息。","爱心领养中心在全岛共有八家分店。","领养者只能在2026年7月领养宠物。"]},{"id":"chinese-2026-prelim-henry-park-p2-q33","cite":"2026 Prelim Henry Park Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"如果你是李丽，你想鼓励家人一起参加爱心领养中心的领养活动。请你写一张便条告诉妈妈你想参加这个活动的原因，并说明要如何领养宠物。\n\n便条的开头是：\n亲爱的妈妈：\n我很喜欢小动物，一直想要领养一只。刚好爱心领养中心将举办“给它一个家，给你一份爱”领养活动，我想和你一起参加，因为……\n（请接着写下去。便条最后已经印好：李丽　6月21日　上午9点）","parts":[{"label":"","answer":{"type":"self","value":"亲爱的妈妈：\n我很喜欢小动物，一直想要领养一只。刚好爱心领养中心将举办“给它一个家，给你一份爱”领养活动，我想和你一起参加，因为我想给流浪的猫狗一个温暖的家。我们可以先上爱心领养中心的网站查看宠物的照片和基本信息，通过网站预约后，再前往中心完成领养手续。\n李丽\n6月21日\n上午9点"},"explanation":["一共 4 分，要写两个内容点，句子也要通顺、没有错字。（试卷上没有印出内容和语文各占几分，一般是内容 2 分、语文 2 分。）","内容第一点（想参加的原因）：从通告第一段找——活动是“为了给流浪的猫狗找个家”，所以可以写“我想给流浪的猫狗一个温暖的家”。也可以加上活动期间领养有优待（新手礼包、三个月免费行为指导和兽医服务）。","内容第二点（如何领养）：从通告最后一段找——先上中心的网站查看宠物的照片和基本信息，通过网站预约后，才前往中心完成领养手续。“网站预约”和“前往中心完成手续”都要写。","语文：接着“因为……”写下去，句子要完整；便条的称呼、署名和日期已经印好，不用再写。"]}],"group":"chinese-2026-prelim-henry-park-g4"},{"id":"chinese-2026-prelim-henry-park-p2-q34","cite":"2026 Prelim Henry Park Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“指出缺点和错误使其改正”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"批评"},"explanation":["要找一个意思是“说出别人的缺点和错误，要他改过来”的词语。","第三段山羊先生说：“他也总批评我，要我改正错误。”","答案是“批评”。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-henry-park-p2-q35","cite":"2026 Prelim Henry Park Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“心里不甘，觉得不公平”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"不服气"},"explanation":["要找一个意思是“心里不甘愿，觉得这样对自己不公平”的词语。","第一段：“欢欢心里不服气：我明明写得很认真，为什么老师总是不满意？”","答案是“不服气”。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-henry-park-p2-q36","cite":"2026 Prelim Henry Park Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":36,"topic":"comprehension-open","subtypes":["cause-and-effect","factual"],"format":"structured","marks":3,"difficulty":2,"stem":"欢欢为什么不喜欢山羊先生？","parts":[{"label":"","answer":{"type":"self","value":"因为山羊先生总在欢欢的作业本上画红圈圈，圈出错别字，还在旁边写着“重写”。欢欢认为自己明明写得很认真，老师却总是不满意，所以她心里不服气。"},"explanation":["答案在第一段，“因为”后面就是原因。","要写出老师做的事：总在作业本上画红圈圈、圈出错别字、还写“重写”。","还要写出欢欢的想法：她觉得自己明明写得很认真，老师却总是不满意，心里不服气。","只写“老师要她重写”是不完整的，拿不到满分。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-henry-park-p2-q37","cite":"2026 Prelim Henry Park Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":37,"topic":"comprehension-open","subtypes":["inference","factual"],"format":"structured","marks":3,"difficulty":2,"stem":"从哪里可以看出山羊先生的老师很有责任感？","parts":[{"label":"","answer":{"type":"self","value":"山羊先生小时候有一次生病了，好一段时间没去上课，他的老师冒着大雨到他家给他补课。"},"explanation":["注意题目问的是“山羊先生的老师”，不是山羊先生自己。","答案在第五段山羊先生说的话里：“有一次我生病了，好一段时间没去上课，他冒着大雨飞到我家给我补课。”","要写出三点：山羊先生生病很久没上课、老师冒着大雨、到他家给他补课。","回答时要把“我”改成“山羊先生”，把“他”改成“他的老师”。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-henry-park-p2-q39","cite":"2026 Prelim Henry Park Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":39,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"欢欢收到礼物后，山羊先生批改欢欢的作业有什么改变？","marks":2,"answer":{"type":"self","value":"山羊先生在欢欢作业本上画的红圈圈越来越少，有时还会画上一个小笑脸。"},"explanation":["答案在第七段第二句：“山羊先生的红圈圈越来越少，有时还会画上一个小笑脸。”","两点都要写：红圈圈越来越少；有时还画小笑脸。"]},{"label":"b","prompt":"为什么会有这样的变化？","marks":2,"answer":{"type":"self","value":"因为欢欢从那以后写作业更认真了，不会的字就查字典。"},"explanation":["原因在同一段的第一句：“从那以后，欢欢写作业更认真了，不会的字就查字典。”","欢欢更认真、会查字典，错别字少了，所以老师画的红圈圈也少了。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-henry-park-p2-q40","cite":"2026 Prelim Henry Park Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Henry Park","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"你同意“严格，才能让人真正成长”这句话吗？请在你的生活中举例说明。","parts":[{"label":"","answer":{"type":"self","value":"我同意。有一次我学习游泳，教练严格要求我反复练习换气和划水。开始时我觉得很辛苦，但在教练不断纠正和督促下，我改正了动作，最后学会了游泳，也变得更有毅力。因此，适当的严格能帮助人发现错误、不断进步，真正成长。"},"explanation":["这是看法题。先清楚地说“我同意”或“我不同意”。","题目要求“在你的生活中举例”，所以一定要写一件自己生活里的事（学游泳、学钢琴、练字、做功课等），不能只抄短文里欢欢的事。","例子要写清楚：谁对你严格、怎样严格、你后来有什么进步。","最后用一句话回到题目：所以严格能帮助人改正错误、真正成长。","只写“同意”而没有例子，或者例子和“严格”没有关系，都拿不到满分。"]}],"group":"chinese-2026-prelim-henry-park-g5"},{"id":"chinese-2026-prelim-nan-hua-p1-q1","cite":"2026 Prelim Nan Hua Paper 1 Question 1","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p1","number":1,"topic":"writing","subtypes":["topic-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"命题作文（字数在 100 以上）\n\n题目：**这件事让我长大了**\n\n在作文时，你可以参考下面的提示：\n• 这件事发生在什么时候\n• 事情的经过是怎样的\n• 经过这件事，你有什么改变\n• 这件事让你有什么感受","parts":[{"label":"","answer":{"type":"self","value":"这道题没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：重点是“长大”。这里的长大不是长高，而是变得懂事、独立、有责任感。要写一件事，并且写出自己前后的改变。","选材：可以写第一次独自照顾生病的家人、做错事后勇敢认错、比赛失败后学会坚持、帮忙做家务后体会到父母的辛苦等。","开头：交代时间、地点、人物，可以先写以前的自己（例如贪玩、依赖父母），为后面的改变做准备。","经过：按起因、经过、结果写清楚。多写当时的动作、对话和心里的想法，特别要写遇到困难时怎么想、怎么做。","结尾：写出这件事以后自己的改变和感受，点题——“这件事让我长大了”。","好词好句：懂事、体谅、独立、责任、恍然大悟、惭愧不已、从那以后；“经过这件事，我明白了……”"]}]},{"id":"chinese-2026-prelim-nan-hua-p1-q2","cite":"2026 Prelim Nan Hua Paper 1 Question 2","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p1","number":2,"topic":"writing","subtypes":["picture-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"看图作文（字数在 100 以上）\n\n仔细看下列的图，根据图意，完成一篇短文。在作文时，你可以参考所提供的词语。\n\n[[img1]]\n\n参考词语：促销、购物中心、零用钱、捡饮料瓶、拿去回收站、旧报纸、很晚回家、拿出礼物","parts":[{"label":"","answer":{"type":"self","value":"这道题没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：六幅图讲一个男孩想在母亲节送妈妈礼物，钱不够，就捡饮料瓶和旧报纸去回收站换钱，结果很晚回家被妈妈责备。第六幅图是问号，要自己写出合理的结局。","开头：交代时间（母亲节前）、地点（购物中心）、人物。写男孩看到促销的礼物要 10 元，可是零用钱只有 8 元，心里很着急。","经过：按图 2 到图 5 的顺序写。写他怎样想出办法，捡饮料瓶、收旧报纸，拿去回收站换钱；再写他很晚回家，妈妈又担心又生气；他拿出礼物。每幅图都要写到，加上人物的动作、对话和心情。","结尾（图 6）：例如妈妈知道原因后很感动，抱住他，也提醒他以后晚回家要先告诉家人；男孩明白了孝顺妈妈也不能让妈妈担心。","好词好句：灵机一动、满头大汗、心急如焚、又气又急、恍然大悟、热泪盈眶；“原来你是为了给我买礼物啊！”","记得用上参考词语：促销、购物中心、零用钱、捡饮料瓶、拿去回收站、旧报纸、很晚回家、拿出礼物。"]}],"images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-p1-q2-img1","alt":"六幅图。图1：男孩在购物中心看到母亲节促销（Mother's Day Promo），标价 $10.00 的礼物，他的储蓄罐里只有 $8。图2：男孩在垃圾桶旁捡饮料瓶和旧报纸。图3：男孩在回收站（Cash-for-Trash Station）把饮料瓶和旧报纸交给工作人员，换到了钱。图4：晚上男孩很晚才回家，妈妈站在门口，很生气。图5：男孩拿出包好的礼物送给妈妈，妈妈还在指着他责备。图6：一个问号，要自己想结局。"}]},{"id":"chinese-2026-prelim-nan-hua-p2-q1","cite":"2026 Prelim Nan Hua Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n我家楼下有一家店是++出租++漫画书的。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“出”是翘舌音 chū，不是平舌音 cū。","“租”是平舌音，读第一声 zū，不是 zhū，也不是第三声。","“出租”读 chū zū，答案是（3）。"]}],"options":["cū zǔ","cū zhū","chū zū","chū zhǔ"]},{"id":"chinese-2026-prelim-nan-hua-p2-q2","cite":"2026 Prelim Nan Hua Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n爸爸下班时遇到交通++堵塞++，很晚才回到家。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“堵”的声母是 d，读 dǔ。zǔ 是“阻”的读音。","“塞”是多音字：在“堵塞、阻塞”里读 sè；在“塞车、瓶塞”里读 sāi。","“堵塞”读 dǔ sè，答案是（1）。"]}],"options":["dǔ sè","dǔ sāi","zǔ sè","zǔ sāi"]},{"id":"chinese-2026-prelim-nan-hua-p2-q3","cite":"2026 Prelim Nan Hua Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n下雨了，妹妹______起了一把小伞。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“撑伞”是把伞张开、举起来。“撑”是提手旁，和手的动作有关。","“称”是称重量、称赞的称；“乘”是乘车的乘；“诚”是诚实的诚。它们读音相近，但意思不对。","答案是（2）撑。"]}],"options":["称","撑","乘","诚"]},{"id":"chinese-2026-prelim-nan-hua-p2-q4","cite":"2026 Prelim Nan Hua Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n表演结束时，礼堂里响起了热______的掌声。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“热烈”形容气氛、掌声很兴奋、很激动，“热烈的掌声”是固定搭配。","“烈”下面是四点底，和火有关。“列”是排列的列，“例”是例子的例，“裂”是裂开的裂。","答案是（1）烈。"]}],"options":["烈","列","例","裂"]},{"id":"chinese-2026-prelim-nan-hua-p2-q5","cite":"2026 Prelim Nan Hua Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n我对妈妈摇了摇头，______不想再吃东西了。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“我”没有说话，只是摇头。用动作或话语让别人明白自己的意思，叫“表示”。","“告诉”后面要有人（告诉妈妈）；“宣布”是正式地向大家说重要的事；“讲述”是把事情说出来。","答案是（3）表示。"]}],"options":["告诉","宣布","表示","讲述"]},{"id":"chinese-2026-prelim-nan-hua-p2-q6","cite":"2026 Prelim Nan Hua Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n看到桌上的奖杯，往事又在我的脑海里______。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["过去的事情又出现在脑子里，叫“浮现”。“在脑海里浮现”是固定搭配。","“回忆”是人去想过去的事，要说“我回忆起往事”，不能说“往事在脑海里回忆”。","答案是（1）浮现。"]}],"options":["浮现","回忆","露出","显示"]},{"id":"chinese-2026-prelim-nan-hua-p2-q7","cite":"2026 Prelim Nan Hua Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这件事很重要，我们必须++考虑++清楚。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“考虑”的意思是认真地想，想清楚了再决定。","“做出最后决定”是考虑以后才做的事，不是“考虑”本身。","答案是（2）仔细地想一想。"]}],"options":["了解详细情况","仔细地想一想","做出最后决定","顺利完成任务"]},{"id":"chinese-2026-prelim-nan-hua-p2-q8","cite":"2026 Prelim Nan Hua Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老师给的作业太多了，同学们纷纷++抱怨++。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“抱怨”的意思是心里不满意，把不满说出来。","作业太多，同学们不高兴，所以说出不满。“吵个不停”只是声音大，没有“不满”的意思。","答案是（3）说出心中不满。"]}],"options":["一直吵个不停","不客气地说出","说出心中不满","围在一起讨论"]},{"id":"chinese-2026-prelim-nan-hua-p2-q9","cite":"2026 Prelim Nan Hua Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______老板吩咐的工作，哥哥就会马上去做。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“凡是”的意思是“只要是……的，全部都……”，后面常接“就、都”。","句子说的是：所有老板吩咐的工作，哥哥都马上做。空格后面是“老板吩咐的工作”这个名词短语，要用“凡是”。","“只要、如果”后面要接一件事（只要老板吩咐，哥哥就……），不能直接接“……的工作”。","答案是（2）凡是。"]}],"options":["只要","凡是","由于","如果"]},{"id":"chinese-2026-prelim-nan-hua-p2-q10","cite":"2026 Prelim Nan Hua Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______想了很多办法，大家______无法帮他改掉坏习惯。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["想了很多办法，可是没有用，前后意思是转折，要用“尽管……还是……”。","“不管”后面要有“怎么、多少、什么”这类词（不管想了多少办法），这里没有，所以不能用。","答案是（4）尽管……还是。"]}],"options":["不但……而且","不管……仍然","因为……所以","尽管……还是"]},{"id":"chinese-2026-prelim-nan-hua-p2-q11","cite":"2026 Prelim Nan Hua Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，我们一家人都为他感到骄傲。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“为他感到骄傲”说明弟弟做了一件很了不起的事。","做错事、去公园都不值得骄傲；只是“捡到钱包”，没有说交还失主，也谈不上骄傲。","答案是（4）弟弟在比赛中得了奖。"]}],"options":["如果弟弟真的做错了","如果弟弟明天去公园","弟弟捡到了一个钱包","弟弟在比赛中得了奖"]},{"id":"chinese-2026-prelim-nan-hua-p2-q12","cite":"2026 Prelim Nan Hua Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n自从参加了学校的环保活动后，____________。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["前面说的是“环保活动”，后面的改变要和环保有关。","随手关灯可以节省用电，是环保的行为。买新衣服、读华文书、做运动都和环保没有关系。","答案是（3）弟弟每次都会随手关灯。"]}],"options":["姐姐每天都会买新衣服","哥哥每天都会读华文书","弟弟每次都会随手关灯","妹妹每次都会多做运动"]},{"id":"chinese-2026-prelim-nan-hua-p2-q13","cite":"2026 Prelim Nan Hua Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“促进”的意思是推动事情向好的方向发展，常说“促进和谐、促进交流、促进发展”。","（1）一起吃晚餐让家庭更和谐，用得对。","（2）应该用“增加”知识；（3）应该用“改进”的地方；（4）小明和同学之间的友情应该说“增进我们的友情”，“他们”指谁也不清楚。","答案是（1）。"]}],"options":["家人一起吃晚餐，可以++促进++家庭和谐。","老师常常提醒我们多读书，++促进++知识。","读了作文后，老师指出了需要++促进++的地方。","小明借故事书给同学看，++促进++他们的友情。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q14","cite":"2026 Prelim Nan Hua Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“五彩缤纷”形容颜色很多、很好看，只能用来形容看得见的、有许多颜色的东西。","（3）气球有各种颜色，用得对。","（1）歌声是听的，应该用“动听”；（2）红烧肉只有一种颜色；（4）心情没有颜色。","答案是（3）。"]}],"options":["姐姐的歌声++五彩缤纷++，大家都听得十分入迷。","妈妈做的红烧肉++五彩缤纷++，让人看了就想吃。","毕业典礼那天，礼堂挂满了++五彩缤纷++的气球。","听到这个消息后，小文的心情变得++五彩缤纷++。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q15","cite":"2026 Prelim Nan Hua Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“半途而废”的意思是事情做到一半就放弃，不能坚持到底。它用在人做的、需要坚持的事情上。","（2）做事不可以半途而废，用得对。","（4）笔是东西，不是人；（1）不想看电影、（3）吃饭吃到一半，都不是需要坚持去完成的事，不用这个成语。","答案是（2）。"]}],"options":["电影真没意思，我看了一会儿++半途而废++。","妈妈常常教育我，做事不可以++半途而废++。","小明吃饭++半途而废++，就和朋友下楼踢球。","这支笔真是++半途而废++，写到一半就断了。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q16","cite":"2026 Prelim Nan Hua Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["空格后面是“练习”。不怕辛苦、努力地练习，是“勤奋练习”。","“热心”是乐意帮助别人；“严格”是要求很高；“迅速”是很快，但学画画不是练得快就会成功。","答案是（3）勤奋。"]}],"group":"chinese-2026-prelim-nan-hua-g1","options":["热心","严格","勤奋","迅速"]},{"id":"chinese-2026-prelim-nan-hua-p2-q17","cite":"2026 Prelim Nan Hua Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["注意句式“没有……而是……”：兔妈妈没有做一件事，而是笑着安慰小兔。","小兔画得不好看，一般人可能会责备它，可是兔妈妈没有“批评”它。","“鼓励”正是兔妈妈后来做的事，不能说“没有鼓励”。","答案是（1）批评。"]}],"group":"chinese-2026-prelim-nan-hua-g1","options":["批评","担心","提醒","鼓励"]},{"id":"chinese-2026-prelim-nan-hua-p2-q18","cite":"2026 Prelim Nan Hua Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":18,"topic":"cloze","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["后面有“也”：“______是大画家，也是一点一点练出来的”。能和“也”搭配的是“就算……也……”。","“虽然”要配“但是”，“除了”要配“还、都”。","答案是（2）就算。"]}],"group":"chinese-2026-prelim-nan-hua-g1","options":["虽然","就算","而且","除了"]},{"id":"chinese-2026-prelim-nan-hua-p2-q19","cite":"2026 Prelim Nan Hua Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["小兔发现自己越画越好，心里有了很多希望。“心里充满了希望”是固定搭配。","“增加”用在数量上；“取得”后面常接成绩、进步。","答案是（3）充满。"]}],"group":"chinese-2026-prelim-nan-hua-g1","options":["留下","增加","充满","取得"]},{"id":"chinese-2026-prelim-nan-hua-p2-q20","cite":"2026 Prelim Nan Hua Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":20,"topic":"cloze","subtypes":["idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["小兔说“我居然成功了！”，“居然”表示没想到。遇到没想到的好事，非常高兴，叫“喜出望外”。","“激动人心”是形容事情让人激动，不是形容人的心情；“恍然大悟”是突然明白；“心满意足”是很满足，没有“意外”的意思。","答案是（4）喜出望外。"]}],"group":"chinese-2026-prelim-nan-hua-g1","options":["激动人心","恍然大悟","心满意足","喜出望外"]},{"id":"chinese-2026-prelim-nan-hua-p2-q21","cite":"2026 Prelim Nan Hua Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"林爷爷小时候为什么不能学钢琴？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看第一段第二句：“他小时候家里很穷，连饭都吃不饱，更别说学钢琴了。”","原因是家里穷，没有钱学钢琴。","“赚钱养家”是他长大以后的事，不是小时候。答案是（2）。"]}],"group":"chinese-2026-prelim-nan-hua-g2","options":["他年纪小，没有老师教他。","他家里很穷，付不起学费。","他太忙了，没有多余时间。","他吃不饱饭，要赚钱养家。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q22","cite":"2026 Prelim Nan Hua Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["factual","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"钢琴老师拒绝林爷爷的原因是什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["看第二段：很多老师说学钢琴的“黄金年龄”早已过去，也有老师觉得他太老了，手指太硬。","“黄金年龄”就是最好的时期。老师们觉得他年纪太大，错过了最好的学琴时间。","那时他还没开始学，所以不是“学得太慢”或“弹得不好听”。答案是（4）。"]}],"group":"chinese-2026-prelim-nan-hua-g2","options":["林爷爷学得太慢。","林爷爷很快就会放弃。","林爷爷弹的曲子不够好听。","林爷爷错过了学琴的最佳时期。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q23","cite":"2026 Prelim Nan Hua Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"林爷爷被拒绝后，他______","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看第二段后面：他“却不想就这样放弃。他用自己存的钱买了一架钢琴，每天在家慢慢练习。”","钱是以前已经存好的，不是被拒绝后才决定存钱；参加比赛是几年后的事。","答案是（3）。"]}],"group":"chinese-2026-prelim-nan-hua-g2","options":["难过地放弃学钢琴。","决定存钱学弹钢琴。","买了一架钢琴，每天练习。","站上舞台，参加钢琴比赛。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q24","cite":"2026 Prelim Nan Hua Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"钢琴家在公园见到林爷爷时，做了什么？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看第三段：男人“停下脚步，静静听完后，微笑着对他说：‘您弹得非常好听，请继续。’”","他停下来听，又说“请继续”，就是让林爷爷继续弹。","他虽然称赞了林爷爷，但短文没有说他“被琴声感动”，所以（2）不对。答案是（1）。"]}],"group":"chinese-2026-prelim-nan-hua-g2","options":["他停下来听，还让他继续弹。","他被琴声感动，称赞林爷爷。","他表示愿意收林爷爷为学生。","他马上邀请林爷爷参加比赛。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q25","cite":"2026 Prelim Nan Hua Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"这个故事告诉我们什么道理？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["道理常常在最后一句：“梦想从不会因为年龄而迟到。”","林爷爷六十岁才开始学琴，没有老师教，靠自己坚持练习也成功了。所以（1）和（3）都和故事相反。","答案是（4）。"]}],"group":"chinese-2026-prelim-nan-hua-g2","options":["学钢琴一定要从小开始。","有钱以后就能实现所有梦想。","只有得到名师指导，才可能成功。","不管年龄多大，都有可能实现梦想。"]},{"id":"chinese-2026-prelim-nan-hua-p2-q26","cite":"2026 Prelim Nan Hua Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["什么事令你这么激动","4 什么事令你这么激动"]},"explanation":["空格后面是问号，所以要选一个问句。问句有 2 和 4。","小华说发生了一件令他非常生气的事，哥哥接着说“快点告诉我”，可见哥哥是在问是什么事。","所以选 4：什么事令你这么激动。（2“是不是又发脾气了”和“快点告诉我”接不上。）"]}],"group":"chinese-2026-prelim-nan-hua-g3"},{"id":"chinese-2026-prelim-nan-hua-p2-q27","cite":"2026 Prelim Nan Hua Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["遇到了非常没有公德心的人","6 遇到了非常没有公德心的人"]},"explanation":["空格后面小华问“你知道他做了什么吗？”，这里的“他”要在前面先提到。","所以空格里要说小华遇到了一个人，但还没说这个人做了什么。","所以选 6：遇到了非常没有公德心的人。（5“在地铁里乱画”已经说出做了什么，而且和后面的“乱扔垃圾”不合。）"]}],"group":"chinese-2026-prelim-nan-hua-g3"},{"id":"chinese-2026-prelim-nan-hua-p2-q28","cite":"2026 Prelim Nan Hua Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"7","accept":["他把糖果的包装纸丢在地上","7 他把糖果的包装纸丢在地上"]},"explanation":["哥哥猜“难道他在地铁上乱扔垃圾？”，小华回答“就是啊”，说明猜对了。","空格要说出他怎样乱扔垃圾，后面接“然后想转头就走”。","所以选 7：他把糖果的包装纸丢在地上。"]}],"group":"chinese-2026-prelim-nan-hua-g3"},{"id":"chinese-2026-prelim-nan-hua-p2-q29","cite":"2026 Prelim Nan Hua Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["于是我便上前劝告他不要这样做","8 于是我便上前劝告他不要这样做"]},"explanation":["小华同意哥哥说的要保持地铁卫生，空格要说小华接着做了什么。","后面哥哥问“他有什么反应？”，小华说他把垃圾捡起来了，说明小华对那个人说了话。","所以选 8：于是我便上前劝告他不要这样做。"]}],"group":"chinese-2026-prelim-nan-hua-g3"},{"id":"chinese-2026-prelim-nan-hua-p2-q30","cite":"2026 Prelim Nan Hua Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"这个海报的主要目的是______。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看标题“屋顶农场等你来！”和这一句：“我们将要举办一个屋顶种菜的讲座活动，快来参加吧！”","海报写了讲座的日期、时间、地点和报名方法，目的是请居民来参加讲座。","种菜的好处只是用来吸引大家；做花盆和种植方法是讲座当天的内容，不是海报的主要目的。答案是（2）。"]}],"group":"chinese-2026-prelim-nan-hua-g4","options":["教导邻居们用旧瓶子制作花盆","邀请居民们参加屋顶农场讲座","说明屋顶农场可以带来的好处","告诉大家不同蔬菜的种植方法"]},{"id":"chinese-2026-prelim-nan-hua-p2-q31","cite":"2026 Prelim Nan Hua Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"如果你和家人想参加讲座，你们应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["看“如何报名参加讲座？”下面：“请在2026年10月10日前到欢乐民众俱乐部填写报名表格。”","电话 6789 1234 是“如有疑问”时才打的，不是用来报名的。王先生是主讲人。","答案是（4）。"]}],"group":"chinese-2026-prelim-nan-hua-g4","options":["打电话给王先生报名","在讲座当天直接去参加","拨打民众俱乐部电话报名","到民众俱乐部填写报名表格"]},{"id":"chinese-2026-prelim-nan-hua-p2-q32","cite":"2026 Prelim Nan Hua Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一项不是屋顶种菜的好处？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["注意题目问的是“不是”。先在第一段找出三个好处：阳光充足，适合植物生长；蔬菜吃得健康又安心；邻居们可以一起劳动、分享快乐。","（3）（4）（1）正好是这三个好处。","用旧瓶子做花盆是讲座后的手工活动，不是屋顶种菜的好处。答案是（2）。"]}],"group":"chinese-2026-prelim-nan-hua-g4","options":["能够加强邻居们之间的友好关系","可以用旧瓶子做成的花盆来种菜","屋顶充足的阳光更适合植物生长","居民们可以安心地吃健康的蔬菜"]},{"id":"chinese-2026-prelim-nan-hua-p2-q33","cite":"2026 Prelim Nan Hua Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"如果你是志文，看到这张海报后，想起喜欢种菜的奶奶，于是你写了一则短信邀请奶奶一起参加这个活动，告诉奶奶活动的详情，以及你觉得她应该参加这个活动的一个原因。\n\n短信的开头是：\n奶奶，我知道您很喜欢种菜，想……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"奶奶，我知道您很喜欢种菜，想邀请您一起参加一个屋顶种菜的讲座，这个讲座将于2026年11月1日，上午10点至11点30分，在欢乐民众俱乐部大讲堂举行。参加这个讲座您可以了解不同蔬菜的种植方法。希望您可以和我一起去。"},"explanation":["内容第一点（邀请和活动详情）：接着“想……”写“邀请您一起参加屋顶种菜的讲座”，再从海报中间的格子里找出日期（2026年11月1日）、时间（上午10点至11点30分）和地点（欢乐民众俱乐部大讲堂），三样都要写。","内容第二点（一个原因）：从海报里找一个适合奶奶的原因，例如可以了解不同蔬菜的种植方法。写用旧瓶子做花盆、可以得到免费小礼物也可以，但只需要写一个。","语文：对奶奶要用“您”；句子要通顺、完整，不要写错字。最后可以加一句“希望您可以和我一起去”。"]}],"group":"chinese-2026-prelim-nan-hua-g4"},{"id":"chinese-2026-prelim-nan-hua-p2-q34","cite":"2026 Prelim Nan Hua Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“立刻”的词语是______。","parts":[{"label":"","answer":{"type":"text","value":"马上"},"explanation":["要找一个意思是“很快、一点也不等”的词语。","第一段：外婆问要不要种花生，“我们马上答应了”。","答案是“马上”。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q35","cite":"2026 Prelim Nan Hua Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“值得珍惜”的词语是______。","parts":[{"label":"","answer":{"type":"text","value":"可贵"},"explanation":["要找一个意思是“很宝贵、值得看重”的词语。","第六段外婆说：“花生的好处很多，有一样最可贵”。","答案是“可贵”。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q36","cite":"2026 Prelim Nan Hua Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":36,"topic":"comprehension-open","subtypes":["inference","factual"],"format":"structured","marks":3,"difficulty":2,"stem":"“我们”喜不喜欢种花生？从哪里可以看出？","parts":[{"label":"","answer":{"type":"self","value":"“我们”喜欢种花生。外婆问我们要不要种花生时，“我们”马上答应，而且“我们”每天放学回家，第一件事就是跑去看花生发芽了没有。过了几天，泥土里终于冒出了绿色的小苗，看到那些小小的叶子时，“我们”高兴得手舞足蹈。从以上几点可以看出“我们”喜欢种花生。"},"explanation":["先回答问题：“我们”喜欢种花生。","再从第一、二段找出证据：外婆一问，“我们”马上答应；每天放学回家第一件事就是跑去看花生发芽了没有；看到小苗和叶子时高兴得手舞足蹈。","证据要写完整，只写“喜欢”没有证据是拿不到满分的。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q37","cite":"2026 Prelim Nan Hua Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":37,"topic":"comprehension-open","subtypes":["inference","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"为什么外婆说“种花生和学习一样，都需要耐心”？","parts":[{"label":"","answer":{"type":"self","value":"因为“我们”看到花生苗慢慢长大，有些着急，总是问外婆什么时候花生才能长出来。外婆想让“我们”知道种花生要等花生慢慢长大，就像学习也要慢慢积累知识。","accept":["因为“我们”看到花生苗慢慢长大，有些着急，总是问外婆什么时候花生才能长出来。外婆想让“我们”知道种花生要等花生慢慢长大，就像学习也要一天天努力。"]},"explanation":["先在第三段找外婆说这句话的原因：“我们”有些着急，总是问外婆什么时候花生才能长出来。","再解释这句话的意思：花生要慢慢长大，不能急；学习也一样，要慢慢积累知识（或一天天努力），不能一下子就学会。","两部分都要写：“我们”着急的表现，以及种花生和学习相同的地方。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q38","cite":"2026 Prelim Nan Hua Paper 2 Question 38","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":38,"topic":"comprehension-open","subtypes":["character-and-feelings","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"看到自己种出的花生时，“我们”有什么感受？","marks":1,"answer":{"type":"self","value":"看到从土里拔出的花生时，“我们”都很吃惊。","accept":["“我们”都很吃惊。","“我们”感到很吃惊。","“我们”感到很惊讶。"]},"explanation":["看第四段：“我们”看见根下面挂着一串串花生时，“都瞪大了眼睛”。","瞪大眼睛表示很吃惊（惊讶）。"]},{"label":"b","prompt":"为什么会有这样的感受？","marks":2,"answer":{"type":"self","value":"因为“我们”以为花生是长在树上的，现在我们才知道花生是藏在土里的。"},"explanation":["接着看同一句：“原来花生不是长在树上的，而是藏在土里的。”","“原来”说明“我们”以前想错了。要写出两点：以前以为花生长在树上；现在才知道花生藏在土里。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q39","cite":"2026 Prelim Nan Hua Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":39,"topic":"comprehension-open","subtypes":["inference","main-idea"],"format":"structured","marks":4,"difficulty":2,"stem":"外婆为什么要让“我们”向花生学习？","parts":[{"label":"","answer":{"type":"self","value":"因为外婆要让“我们”明白花生的果实埋在地里，虽然不容易被看到，却对人很有好处。外婆要让我们像花生一样，默默付出，做一个对别人有帮助的人，所以外婆要让“我们”向花生学习。"},"explanation":["答案在第六段外婆说的话里。","第一点：花生的特点——果实埋在地里，虽然不容易被看到，却对人很有好处。","第二点：外婆的希望——“我们”也像花生一样，默默付出，做一个对别人有帮助的人。","花生的特点和外婆的希望都要写。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nan-hua-p2-q40","cite":"2026 Prelim Nan Hua Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Nan Hua","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"你认为外婆教导“我们”的方法好吗？试加以说明。","parts":[{"label":"","answer":{"type":"self","value":"我认为外婆教导“我们”的方法很好，因为外婆通过带我们种花生，让我们明白花生虽然不容易被看到，却对人很有好处，并希望我们默默付出，做一个对别人有帮助的人，这让我们印象深刻。"},"explanation":["这是看法题。先说清楚自己的看法：“我认为外婆教导‘我们’的方法很好。”","再说外婆用的是什么方法：她不是只讲道理，而是带“我们”亲手种花生，再借花生来说道理。","然后说这个方法的好处：让“我们”明白要像花生一样默默付出，做对别人有帮助的人，而且印象深刻（最后一段说“外婆的话深深地印在我的心上”）。","只写“好”，没有用短文里的事来说明，是拿不到分数的。"]}],"group":"chinese-2026-prelim-nan-hua-g5"},{"id":"chinese-2026-prelim-nanyang-p1-q1","cite":"2026 Prelim Nanyang Paper 1 Question 1","year":2026,"exam":"Prelim","school":"Nanyang","section":"p1","number":1,"topic":"writing","subtypes":["topic-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第一题：这件事让我学会了原谅\n\n在作文时，你可以参考下面的提示：\n• 你原谅了谁？\n• 这件事情的经过是怎样的？\n• 你为什么选择原谅？\n• 原谅后让你有什么感受？","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：题目的重点是“学会了原谅”。要写一件别人做错事、让你生气或难过的事，最后你选择原谅他。四个提示都要写到。","开头：可以从一件东西或一个情景想起这件事，也可以直接交代时间、地点、人物，说明你原谅的是谁。","经过：写清楚对方做了什么（例如弄坏了你心爱的东西、误会了你），你当时多么生气；再写对方怎样道歉或你发现了什么，让你的想法改变。要写出心情的变化：生气 → 犹豫 → 心软 → 原谅。","原因：一定要写“为什么选择原谅”，例如对方不是故意的、他真心认错、你想起自己也犯过错、友情比东西重要。","结尾：写原谅之后的感受（心里轻松了、友情更深了），并点题：这件事让我学会了原谅，明白了宽容待人的道理。","好词好句：火冒三丈、怒气冲冲、低声下气、诚恳、惭愧、后悔莫及、心软、如释重负、和好如初；“退一步海阔天空。”“原谅别人，也是放过自己。”"]}]},{"id":"chinese-2026-prelim-nanyang-p1-q2","cite":"2026 Prelim Nanyang Paper 1 Question 2","year":2026,"exam":"Prelim","school":"Nanyang","section":"p1","number":2,"topic":"writing","subtypes":["picture-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第二题：仔细看下列的图，根据图意，完成一篇短文。在作文时，你可以参考所提供的词语。\n\n[[img1]]\n\n参考词语：小组活动、平板电脑、讨论、无聊、偷偷看书、惊讶、争抢、撕破","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：六幅图都要写到，重点放在图四、图五（争抢、撕破书）和图六（自己想的结局）。先给三个同学取名字。","开头：交代时间、地点、人物和事情——课堂上老师让大家进行小组活动，用平板电脑讨论。","经过：组员认真讨论，戴眼镜的同学觉得无聊，偷偷看故事书；女同学发现了，大家很惊讶；另一个组员很生气，伸手去抢书，两人争抢起来，“嘶”的一声，书被撕破了。要写出人物的动作、语言和心情。","图六的结局要合理：例如老师走过来了解情况，看书的同学承认自己不该在小组活动时看书，抢书的同学也为撕破书道歉，两人一起把书粘好，然后认真完成讨论。","结尾：写出明白的道理——小组活动要尽自己的责任；遇到问题要好好说，不能动手争抢。","好词好句：聚精会神、七嘴八舌、心不在焉、目瞪口呆、怒气冲冲、互不相让、不知所措、面红耳赤、惭愧地低下头、齐心协力。"]}],"images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-p1-q2-img1","alt":"六幅图。图一：课室里同学们分成小组，用平板电脑讨论，老师在旁边看。图二：一个男同学和一个女同学在讨论，旁边戴眼镜的男同学却在偷偷看书。图三：女同学指着看书的男同学，男同学和戴眼镜的同学都很惊讶。图四：男同学生气地抓住那本书，要戴眼镜的同学参加讨论，两人拉扯起来。图五：书被撕破了，三个人都吓了一跳。图六：一个问号，结局要自己想。图下面是参考词语：小组活动、平板电脑、讨论、无聊、偷偷看书、惊讶、争抢、撕破。"}]},{"id":"chinese-2026-prelim-nanyang-p2-q1","cite":"2026 Prelim Nanyang Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n在这个团队中，我们++彼此++学习，共同进步。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“彼”的声母是 b，读第三声 bǐ，不是 pí。","“此”是平舌音 cǐ，不是翘舌音 chǐ。","“彼此”读 bǐ cǐ，答案是（1）。"]}],"options":["bǐ cǐ","pí cǐ","bǐ chǐ","pí chǐ"]},{"id":"chinese-2026-prelim-nanyang-p2-q2","cite":"2026 Prelim Nanyang Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n小明知道他错了后，立刻++诚恳++地道歉。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“诚”是后鼻音 chéng，不是前鼻音 chén。","“恳”的声母是 k，读 kěn，不是 gěn。","“诚恳”读 chéng kěn，答案是（3）。"]}],"options":["chén kěn","chén gěn","chéng kěn","chéng gěn"]},{"id":"chinese-2026-prelim-nanyang-p2-q3","cite":"2026 Prelim Nanyang Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n红头巾们为社会的发展______献自己的力量。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“贡献”的意思是把自己的力量、本领拿出来，为大家做有益的事。","“供、功、宫”读音和“贡”相近，但是没有“供献、功献、宫献”这些词语。","答案是（2）贡。"]}],"options":["供","贡","功","宫"]},{"id":"chinese-2026-prelim-nanyang-p2-q5","cite":"2026 Prelim Nanyang Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这张实木桌子很______，用了十年还是完好如初。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“坚固”形容东西很结实，不容易坏。桌子用了十年还完好，就是坚固。","“坚强”和“坚定”是形容人的，“坚持”是动词（坚持到底），都不能形容桌子。","答案是（2）坚固。"]}],"options":["坚持","坚固","坚强","坚定"]},{"id":"chinese-2026-prelim-nanyang-p2-q6","cite":"2026 Prelim Nanyang Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n战场上，所有的战士都顽强地与敌人______。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“与敌人对抗”是正确的搭配，意思是和敌人对着打，不退让。","“克服”后面接困难；“攻打”要说“攻打敌人”，不说“与敌人攻打”；“挣扎”是用力想摆脱。","答案是（2）对抗。"]}],"options":["克服","对抗","攻打","挣扎"]},{"id":"chinese-2026-prelim-nanyang-p2-q7","cite":"2026 Prelim Nanyang Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n医生说如果吃太多糖会++损害++牙齿。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“损害”的意思是使东西受到破坏，变坏了，不能像原来那样好用。","吃太多糖会蛀牙，牙齿坏了就不能好好咬东西，不只是“变得难看”。","答案是（4）使物品残破失去原来的功效。"]}],"options":["使物品的外表变得十分难看","使物品的总共数量突然变少","使物品受到各种巨大的压力","使物品残破失去原来的功效"]},{"id":"chinese-2026-prelim-nanyang-p2-q8","cite":"2026 Prelim Nanyang Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n出门前，妈妈再三++吩咐++我要带雨伞。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“吩咐”是长辈或上级口头叫人去做某件事。","妈妈叫“我”带雨伞，是叫我做事，不是讲道理（2），也不是提意见（4）。","答案是（1）用言语指派或命令。"]}],"options":["用言语指派或命令","把解释或道理讲出来","劝别人对某事表示同意","提出自己的意见或者想法"]},{"id":"chinese-2026-prelim-nanyang-p2-q9","cite":"2026 Prelim Nanyang Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______前面的路很难走，你______要勇往直前。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["句子的意思是：就算路难走，还是要向前走。这是让步关系，用“即使……也……”。","“无论……都……”后面要有“多么、怎样”等词（无论路多么难走）；“只有……才……”表示必须有的条件。","答案是（2）即使……也。"]}],"options":["凡是……都","即使……也","只有……才","无论……都"]},{"id":"chinese-2026-prelim-nanyang-p2-q10","cite":"2026 Prelim Nanyang Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______明天是公共假日，______今晚我们多聊一会吧。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“反正”表示情况已经确定（明天放假，不必早起），“不如”用来提出一个建议（多聊一会）。","“尽管……还是……”表示转折，可是放假和多聊天并不矛盾；“除非……不然……”表示条件，也不合适。","答案是（3）反正……不如。"]}],"options":["尽管……还是","不仅……而且","反正……不如","除非……不然"]},{"id":"chinese-2026-prelim-nanyang-p2-q11","cite":"2026 Prelim Nanyang Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n弟弟津津有味地看着故事书，____________。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“津津有味”形容看得很有兴趣、很入迷。","看书看得入迷，所以连妈妈喊他吃饭都没听见，前后意思连得上。","他在看故事书，不是做作业，所以（4）不对。答案是（2）。"]}],"options":["大家都很想教训他一顿","妈妈喊他吃饭都没听见","常常使家人感到难为情","不一会儿就做完作业了"]},{"id":"chinese-2026-prelim-nanyang-p2-q12","cite":"2026 Prelim Nanyang Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，我们总算解决了这个难题。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“总算解决了”说明事情已经做成了，前面要说是靠什么做成的。","“在……下”表示条件：在所有人的努力付出下，难题解决了。","（2）“如果”是假设，事情还没发生，和“总算解决了”不配；（3）“自从”后面要接“以后”。答案是（4）。"]}],"options":["由于大家都想明天再试","如果大家都能齐心协力","自从所有人都在想办法","在所有人的努力付出下"]},{"id":"chinese-2026-prelim-nanyang-p2-q13","cite":"2026 Prelim Nanyang Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“争夺”是互相抢着要得到一样东西，常说“争夺冠军、争夺第一名”。","（4）两支球队争夺冠军，用得对。","（1）应该用“争吵”，（2）应该用“为国争光”，（3）应该用“争取”。","答案是（4）。"]}],"options":["由于对这件事的意见不同，小恩和小明发生了++争夺++。","通过刻苦的训练，明华终于在国际舞台上为国++争夺++。","为了++争夺++更多的准备时间，他把游戏活动都取消了。","为了++争夺++冠军，两支球队在球场上展开激烈的对抗。"]},{"id":"chinese-2026-prelim-nanyang-p2-q14","cite":"2026 Prelim Nanyang Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“困难”指事情不容易做，或者遇到的难题，常说“克服困难”。它不是一种心情。","（3）“克服种种困难”，用得对。","（1）应该用“难忘”，（2）应该用“难过”，（4）应该用“为难”。","答案是（3）。"]}],"options":["那个假期的美好时光，至今让明美十分++困难++。","听到这个不幸的消息，小乐心里感到很++困难++。","她努力克服种种++困难++，终于完成了大学学业。","这事让安安很++困难++，她不知该如何处理才好。"]},{"id":"chinese-2026-prelim-nanyang-p2-q15","cite":"2026 Prelim Nanyang Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“妒忌”是看到别人比自己好，心里不高兴、不服气，是不好的心理。","（4）伟明因为佳佳更受欢迎而“心里十分不满”，正是妒忌。","（3）希望像她一样优秀是好的想法，应该用“羡慕”；（1）应该用“高兴”；（2）应该用“责怪”。","答案是（4）。"]}],"options":["看到小明登上领奖台，大家++妒忌++得鼓起了掌。","哥哥主动承认了错误，因此妈妈不再++妒忌++他。","我++妒忌++她的成功，希望自己能像她一样优秀。","伟明++妒忌++佳佳比他更受欢迎，心里十分不满。"]},{"id":"chinese-2026-prelim-nanyang-p2-q16","cite":"2026 Prelim Nanyang Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“态度恶劣”是固定搭配，意思是对人的态度很坏。后面说老板“对人爱理不理，讲话总是冷冰冰的”。","“凶狠”是又凶又狠，会伤害人；老板只是冷淡，没有那么可怕。“强硬”是不肯让步。","答案是（2）恶劣。"]}],"group":"chinese-2026-prelim-nanyang-g1","options":["凶狠","恶劣","强硬","粗心"]},{"id":"chinese-2026-prelim-nanyang-p2-q17","cite":"2026 Prelim Nanyang Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“愤怒”。“心中充满愤怒”是说心里全是怒气，“充满”是动词，后面可以接感情。","“充足”用在阳光、时间、理由；“充实”用在生活、内容；“充分”用在准备、理由，都不能接“愤怒”。","答案是（1）充满。"]}],"group":"chinese-2026-prelim-nanyang-g1","options":["充满","充足","充实","充分"]},{"id":"chinese-2026-prelim-nanyang-p2-q18","cite":"2026 Prelim Nanyang Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["老板冷漠地回答，“我”以为中学生会不高兴，没想到他还是像原来一样保持笑容。“仍然”就是“还是、依旧”。","“果然”是事情和预料的一样，可是前面说“让我意想不到”，所以不对。","答案是（4）仍然。"]}],"group":"chinese-2026-prelim-nanyang-g1","options":["果然","突然","既然","仍然"]},{"id":"chinese-2026-prelim-nanyang-p2-q19","cite":"2026 Prelim Nanyang Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“我”问他“你不生气吗？”，中学生回答：他怎么对待我，我没必要去“抱怨他”。“抱怨”是心里不满，责怪别人。","空格后面有“他”，要用可以接人的动词。“苦恼、悲伤”是自己的心情，后面不能接“他”。","答案是（3）抱怨。"]}],"group":"chinese-2026-prelim-nanyang-g1","options":["苦恼","悲伤","抱怨","担忧"]},{"id":"chinese-2026-prelim-nanyang-p2-q20","cite":"2026 Prelim Nanyang Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“影响心情”是常用的搭配。中学生的意思是：不要让别人的态度改变自己的心情。","态度不能“选择”心情，“打败心情”也说不通。","答案是（2）影响。"]}],"group":"chinese-2026-prelim-nanyang-g1","options":["选择","影响","麻烦","打败"]},{"id":"chinese-2026-prelim-nanyang-p2-q21","cite":"2026 Prelim Nanyang Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"一开始，杰西对隔壁邻居家的生活有什么看法？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看第一段最后一句：“杰西想他们家的生活一定很清苦。”","她这样想，是因为两个男孩总是穿着不合身、有破洞的旧衣服。","男孩们笑声不断是事实，但题目问的是杰西的“看法”。答案是（2）。"]}],"group":"chinese-2026-prelim-nanyang-g2","options":["他们过得很快乐。","他们过得很清苦。","他们的生活很自由。","他们的生活很孤独。"]},{"id":"chinese-2026-prelim-nanyang-p2-q22","cite":"2026 Prelim Nanyang Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"停电时，杰西有什么反应？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看第二段：“杰西吓了一跳，她下意识地抓起手机，打开手电筒功能”。","“吓了一跳”就是害怕，“打开手电筒功能”就是用手机照明。","她没有等邻居，也没有去找男孩。答案是（1）。"]}],"group":"chinese-2026-prelim-nanyang-g2","options":["害怕地抓起手机照明。","担心地等待邻居来帮忙。","吃惊地到处寻找男孩们。","紧张地走去房间查看情况。"]},{"id":"chinese-2026-prelim-nanyang-p2-q23","cite":"2026 Prelim Nanyang Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["cause-and-effect","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"为什么杰西告诉男孩们她家没有手电筒？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看第四段杰西心里的念头：“以后他们一定会因为家里缺少东西而常常来找她帮忙。”","想到这里她才皱起眉，故作冷淡地说“没有”。其实她刚找到两个备用手电筒，不是不够用。","答案是（1）。"]}],"group":"chinese-2026-prelim-nanyang-g2","options":["因为她担心他们以后会常来借东西。","因为她以为邻居家里有两个手电筒。","因为她有一个手机可以长时间照明。","因为她家里的手电筒根本就不够用。"]},{"id":"chinese-2026-prelim-nanyang-p2-q24","cite":"2026 Prelim Nanyang Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"接过男孩的手电筒后，杰西心情有什么变化？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["开始时杰西怀疑男孩是来借东西的，以后还会常常来麻烦她。","知道男孩是来送手电筒以后，“她感到又羞愧又感动。原来她误会了邻居的好意。”","所以是从怀疑变成感动、羞愧。答案是（4）。"]}],"group":"chinese-2026-prelim-nanyang-g2","options":["从安心变得紧张不安。","从好奇变得轻松放心。","从焦急变得惊讶欣慰。","从怀疑变得感动羞愧。"]},{"id":"chinese-2026-prelim-nanyang-p2-q25","cite":"2026 Prelim Nanyang Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"这篇短文主要告诉我们什么道理？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["故事的重点是：杰西看邻居穿得破旧，就认定他们是来借东西的，结果人家是好心来送手电筒。","短文里直接写了“原来她误会了邻居的好意”，这就是要我们明白的道理。","（4）邻居和谐相处也是好事，但故事主要写的是“误会”。答案是（3）。"]}],"group":"chinese-2026-prelim-nanyang-g2","options":["停电前要准备好照明工具。","人越陌生就越要保持距离。","不要轻易误会别人的好意。","邻居之间应该要和谐相处。"]},{"id":"chinese-2026-prelim-nanyang-p2-q26","cite":"2026 Prelim Nanyang Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["这座组屋已经三十年了","4 这座组屋已经三十年了"]},"explanation":["美如说“太好了！______，设备都很老旧了。”空格要说明为什么设备老旧。","组屋已经建了三十年，所以设备才会老旧，也才需要翻新。","所以选 4：这座组屋已经三十年了。"]}],"group":"chinese-2026-prelim-nanyang-g3"},{"id":"chinese-2026-prelim-nanyang-p2-q27","cite":"2026 Prelim Nanyang Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"2","accept":["而且不是每层楼都停","2 而且不是每层楼都停"]},"explanation":["志光在说电梯的缺点：“又慢又窄小，______，大家都觉得很麻烦。”空格是电梯的另一个缺点。","下一句美如说“对啊！电梯不能到达每一层楼”，正好是在同意志光刚说的话。","所以选 2：而且不是每层楼都停。"]}],"group":"chinese-2026-prelim-nanyang-g3"},{"id":"chinese-2026-prelim-nanyang-p2-q28","cite":"2026 Prelim Nanyang Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"5","accept":["对我那行动不便的爷爷来说","5 对我那行动不便的爷爷来说"]},"explanation":["美如说“电梯不能到达每一层楼，______，太不方便了。”空格要说对谁来说不方便。","电梯不到每一层，就要走楼梯，行动不便的老人最辛苦。“对……来说”后面接“太不方便了”，句子才完整。","所以选 5：对我那行动不便的爷爷来说。（3 说的是“很便利”，意思相反。）"]}],"group":"chinese-2026-prelim-nanyang-g3"},{"id":"chinese-2026-prelim-nanyang-p2-q29","cite":"2026 Prelim Nanyang Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["因为现在买车的人越来越多","6 因为现在买车的人越来越多"]},"explanation":["志光说“停车场也会扩建，______。”空格要说明停车场为什么要扩建。","买车的人多了，停车位不够，所以要扩建。","所以选 6：因为现在买车的人越来越多。"]}],"group":"chinese-2026-prelim-nanyang-g3"},{"id":"chinese-2026-prelim-nanyang-p2-q30","cite":"2026 Prelim Nanyang Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"这则通告的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["要分清楚：题目问的是“这则通告”的目的，不是“举办展览”的目的。","通告介绍了展览的日期、时间、地点、票价和活动，最后还说“欢迎有兴趣的公众前来参观”，目的是吸引大家来参观。","（2）“激发公众对机器人的兴趣”是协会举办展览的目的，是最容易选错的。答案是（3）。"]}],"group":"chinese-2026-prelim-nanyang-g4","options":["鼓励爱好机器人的公众来分享。","激发公众对机器人科技的兴趣。","吸引公众前来参观机器人展览。","邀请公众一起前来庆祝儿童节。"]},{"id":"chinese-2026-prelim-nanyang-p2-q31","cite":"2026 Prelim Nanyang Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一项++不是++展览现场的体验活动？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["看“现场机器人体验活动”的四个格子：机器人对战、机器人推盒子、机器人抓小球、动手组装机器人。","活动一是“机器人对战”，图里是两个机器人在对打，不是人和机器人对战。","答案是（4）。"]}],"group":"chinese-2026-prelim-nanyang-g4","options":["机器人抓小球。","机器人推盒子。","动手组装机器人。","人与机器人对战。"]},{"id":"chinese-2026-prelim-nanyang-p2-q32","cite":"2026 Prelim Nanyang Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":32,"topic":"functional-text","subtypes":["factual","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["（2）对：通告最后说“凡在 10 月 2 日来参观的小学生都会获得一份神秘礼物”。","（1）错：票价那里写“学生免费入场”，中学生也免费，不是只有小学生。","（3）错：是协会为参观者介绍和演示机器人；（4）错：是“在展览会当天购票”，不必上网报名。","答案是（2）。"]}],"group":"chinese-2026-prelim-nanyang-g4","options":["只有小学生们可以免费参观这个机器人展览。","10 月 2 日参展的小学生们都能获得一份礼物。","参观者们将有机会在现场演示不同的机器人。","想参观展览的人们需上网报名并购买入门票。"]},{"id":"chinese-2026-prelim-nanyang-p2-q33","cite":"2026 Prelim Nanyang Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"看了这则通告后，你想起上中学的表哥一直很喜欢组装机器人。请写一则短信给表哥，向他介绍这个展览中一个他感兴趣的活动，以及这个活动的详情和一个好处。\n\n短信的开头是：\n收件人：表哥\n表哥，我知道你对组装机器人非常感兴趣，……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"表哥，我知道你对组装机器人非常感兴趣，创意机器人协会将举办“机器人欢乐展”活动，展览中有个“动手组装机器人”的活动很适合你。这个活动的日期是10月3日，时间是上午10点至下午4点半，地点是创意机器人协会一楼展览厅。若组装成功，可免费将机器人带回家。"},"explanation":["这一题一共 4 分，内容和语文都要顾到。","内容第一点（活动）：表哥喜欢组装机器人，又是中学生，所以要介绍活动四“动手组装机器人”（这个活动仅限中学生参加）。","内容第二点（详情）：日期是 10 月 3 日（体验活动只在 10 月 3 号举行，不要写成 10 月 2 日），时间是上午 10 点至下午 4 点半，地点是创意机器人协会一楼展览厅。","内容第三点（一个好处）：若组装成功，可免费将机器人带回家。","语文：接着“表哥，我知道你对组装机器人非常感兴趣，”写下去，句子要通顺、完整，不要写错字。"]}],"group":"chinese-2026-prelim-nanyang-g4"},{"id":"chinese-2026-prelim-nanyang-p2-q34","cite":"2026 Prelim Nanyang Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“一遍又一遍”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"反复"},"explanation":["要找一个意思是“一次又一次、重复很多次”的词语。","第一段：张老师站在我旁边，“反复提醒我要拿出华文课本”。","答案是“反复”。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q35","cite":"2026 Prelim Nanyang Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“费心思考虑”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"操心"},"explanation":["要找一个意思是“为一件事花很多心思、担心”的词语。","第二段爸爸说：“唉，我正为这件事操心……”","答案是“操心”。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q36","cite":"2026 Prelim Nanyang Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual"],"format":"structured","marks":3,"difficulty":2,"stem":"上课时，张老师提醒作者要做什么？","parts":[{"label":"","answer":{"type":"self","value":"上课时，张老师提醒作者拿出华文课本，认真听课，让作者把讲的重点都写下来。"},"explanation":["答案在第一段第二句。","一共三点，每点 1 分：拿出华文课本、认真听课、把老师讲的重点都写下来。","三件事都要写，少写一件就少 1 分。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q37","cite":"2026 Prelim Nanyang Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":37,"topic":"comprehension-open","subtypes":["factual","character-and-feelings"],"format":"structured","marks":3,"difficulty":2,"stem":"听到爸爸说要移民美国，作者有什么反应？","parts":[{"label":"","answer":{"type":"self","value":"听到爸爸说要移民美国，作者心里不由得一紧，惊讶地问爸爸以后他还有没有机会学华文。"},"explanation":["答案在第二段：“听到这个消息，我心里不由得一紧，惊讶地问：‘爸爸，那以后我还有机会学华文吗？’”","要写出三点：心里不由得一紧、很惊讶、问爸爸以后还有没有机会学华文。","把“我”改成“作者”，把问话改成自己的话来写。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q38","cite":"2026 Prelim Nanyang Paper 2 Question 38","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":38,"topic":"comprehension-open","subtypes":["inference","character-and-feelings"],"format":"structured","marks":4,"difficulty":2,"stem":"知道以后没机会学华文后，作者对待华文的态度是怎样的？","parts":[{"label":"","answer":{"type":"self","value":"知道以后没机会学华文后，作者认真、努力学华文，希望能把整本书一下子全学会。他每天放学后都会温习当天学过的课文，还拿出纸，一笔一画地复习新学的生字。"},"explanation":["先写态度：作者变得喜欢学华文／认真学华文／努力学华文。","再用短文里的事来说明。第三段：他“真希望能把整本书一下子全学会”。","第四段：他“每天放学后都会温习当天学过的课文，还拿出纸，一笔一画地复习新学的生字”。","只写“他很认真”不够，要把他怎样做写出来，才能拿满 4 分。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q39","cite":"2026 Prelim Nanyang Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":39,"topic":"comprehension-open","subtypes":["inference","character-and-feelings"],"format":"structured","marks":4,"difficulty":2,"stem":"文中“既高兴又有点酸酸的”指的是什么？","parts":[{"label":"","answer":{"type":"self","value":"这句话指的是作者听写有进步，老师表扬他，同学们投来敬佩的目光，这让他很开心。但是作者想到自己快要离开，以后再没机会学华文了，心里感到难过。"},"explanation":["这句话有两种心情，要分开说明，各 2 分。","“高兴”：他的听写得了满分，张老师表扬他是大家学习的好榜样，同学们都向他投来敬佩的目光。","“酸酸的”就是难过：看第五段他心里的话——在他深深喜欢上华文课的时候，却快要离开（移民美国）了，以后再也没有机会学华文。","回答时用“……让他很开心，但是……让他感到难过”把两种心情和原因都写出来。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-nanyang-p2-q40","cite":"2026 Prelim Nanyang Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Nanyang","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"如果你是文中的作者，到了美国后，你会用什么方法来继续学习华文？请写出两种方法并分别加以说明。","parts":[{"label":"","answer":{"type":"self","value":"我会好好利用老师给我的那套中学的华文课本来学习。虽然我在美国没法上华文课，但老师给的课本能让我继续学习。我还可以上网去找一些华文相关的视频。这些华文视频资料，能够让我继续接触华文，不会忘记自己的母语。","accept":["我会好好利用老师给我的那套中学的华文课本来学习，有不懂的地方就写信问张老师。这样我在美国没法上华文课，也能继续学习。我还会在家里多和爸爸妈妈讲华语、多读华文故事书。这样我可以常常接触华文，不会忘记自己的母语。"]},"explanation":["这是开放式题目，没有固定答案，但是一定要写“两种”方法，每种方法都要“加以说明”（为什么这个方法有用）。每种方法 2 分。","方法可以来自短文：用张老师送的那套中学华文课本自学；有不懂的地方写信问张老师。","也可以自己想：上网看华文视频、读华文故事书、在家和爸爸妈妈讲华语、和新加坡的同学用华文通信。","回答时用“我会……。这样……。我还可以……。这样……”来写，方法和说明都要有。只写方法、没有说明，会被扣分。"]}],"group":"chinese-2026-prelim-nanyang-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q1","cite":"2026 Prelim PLMGS Paper 2 Question 1","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n这件上衣穿起来真好看，很++适合++你。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“适”是翘舌音 shì，读第四声，不是平舌音 sì。","“合”读第二声 hé，不是第四声 hè。","“适合”读 shì hé，答案是（4）。"]}],"options":["sì hè","sī hè","shī hé","shì hé"]},{"id":"chinese-2026-prelim-plmgs-p2-q2","cite":"2026 Prelim PLMGS Paper 2 Question 2","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n我会++加倍++珍惜妈妈亲手给我做的被子。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“加”读第一声 jiā，不是第二声 jiá。","“倍”的声母是 b，读 bèi；“陪 péi”“配 pèi”的声母才是 p。","“加倍”读 jiā bèi，答案是（2）。"]}],"options":["jiá bèi","jiā bèi","jiá péi","jiā pèi"]},{"id":"chinese-2026-prelim-plmgs-p2-q3","cite":"2026 Prelim PLMGS Paper 2 Question 3","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n哥哥学会如何______隐形眼镜后，高兴不已。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["把东西放在头上、脸上、手上，用“戴”：戴眼镜、戴帽子、戴手表。","“载”是“载客”的载，“截”是“截止”的截，“栽”是“栽树”的栽，这几个字样子很像，但意思不对。","答案是（4）戴。"]}],"options":["载","截","栽","戴"]},{"id":"chinese-2026-prelim-plmgs-p2-q4","cite":"2026 Prelim PLMGS Paper 2 Question 4","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这个牌子的行李箱______量很好，只是价格比较贵。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“质量”的意思是东西好不好、耐不耐用。","“智”是“智慧”的智，“至”是“至少”的至，“制”是“制造”的制，读音一样，但不能和“量”组成这个词。","答案是（4）质。"]}],"options":["智","至","制","质"]},{"id":"chinese-2026-prelim-plmgs-p2-q5","cite":"2026 Prelim PLMGS Paper 2 Question 5","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n买食品时，我们要______包装袋上的日期。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“检查”的意思是仔细地看，找出有没有问题。买食品要看日期，知道有没有过期，所以是“检查日期”。","“记录”是把事情写下来，买东西时不需要把日期写下来。","答案是（1）检查。"]}],"options":["检查","见证","记录","申请"]},{"id":"chinese-2026-prelim-plmgs-p2-q6","cite":"2026 Prelim PLMGS Paper 2 Question 6","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这件事不能再______了，你一定要在这个星期把事情办好。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“拖延”的意思是把时间往后推，不马上做。后面说“一定要在这个星期把事情办好”，说明不能再拖了。","“考虑”是想一想，“不能再考虑了”也说得通，但是后面强调的是办事的时间，所以“拖延”更合适。","答案是（3）拖延。"]}],"options":["促进","考虑","拖延","怀疑"]},{"id":"chinese-2026-prelim-plmgs-p2-q7","cite":"2026 Prelim PLMGS Paper 2 Question 7","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n由于缺少人手，这次的活动只好++临时++取消了。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“临时”的意思是事情快要发生的时候才突然决定，不是早就计划好的。","活动还没有举行就取消了，所以不是“刚刚结束的时候”，也不是“过了很久”。","答案是（4）事情在短时间内发生。"]}],"options":["事情已经过了很久","事情已经被人忘记","事情刚刚结束的时候","事情在短时间内发生"]},{"id":"chinese-2026-prelim-plmgs-p2-q8","cite":"2026 Prelim PLMGS Paper 2 Question 8","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n小明没有因为同学表现优秀而++妒忌++他，反而向对方学习。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“妒忌”的意思是看到别人比自己好，心里不高兴，甚至讨厌他。","句子里有“没有……反而……”，“向对方学习”是好的做法，所以“妒忌”是不好的想法，和“佩服”意思相反。","答案是（1）讨厌比自己强的人。"]}],"options":["讨厌比自己强的人","嘲笑比自己差的人","佩服比自己棒的人","熟悉比自己弱的人"]},{"id":"chinese-2026-prelim-plmgs-p2-q9","cite":"2026 Prelim PLMGS Paper 2 Question 9","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______外头下着大雨，他______还要出门跑步。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["下大雨一般不会出门跑步，可是他还是要去，前后意思相反，是转折关系，用“虽然……却……”。","“如果……就……”表示假设，可是“下着大雨”是真的在下雨，不是假设。","答案是（3）虽然……却。"]}],"options":["除了……还","如果……就","虽然……却","只有……才"]},{"id":"chinese-2026-prelim-plmgs-p2-q10","cite":"2026 Prelim PLMGS Paper 2 Question 10","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______你心情不好，______不应该对别人乱发脾气。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["句子的意思是：即使心情不好，还是不应该乱发脾气。用“就算……也……”。","“不管……都……”后面要有“怎么、多么、好不好”等词，例如“不管你心情好不好，都……”。","答案是（2）就算……也。"]}],"options":["只要……就","就算……也","不管……都","凡是……都"]},{"id":"chinese-2026-prelim-plmgs-p2-q11","cite":"2026 Prelim PLMGS Paper 2 Question 11","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n请大家齐心协力，____________。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“齐心协力”的意思是大家一条心，一起努力。它用在需要大家合作才能做好的事情上。","唱歌、回家、看比赛都不需要大家一起努力才做得到。","答案是（4）准时完成这项工作。"]}],"options":["常聚在一起唱唱歌","吃饱后就赶快回家","看完这场舞蹈比赛","准时完成这项工作"]},{"id":"chinese-2026-prelim-plmgs-p2-q12","cite":"2026 Prelim PLMGS Paper 2 Question 12","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，老师为他们取得的成绩感到自豪。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["后面说老师为他们“取得的成绩”感到“自豪”，所以前面要说同学们取得了什么好成绩。","“上课时非常专心”是好的表现，但不是“取得的成绩”。","答案是（4）同学们比赛时得了冠军。"]}],"options":["同学们七嘴八舌地讨论","同学们没按时完成作业","同学们上课时非常专心","同学们比赛时得了冠军"]},{"id":"chinese-2026-prelim-plmgs-p2-q13","cite":"2026 Prelim PLMGS Paper 2 Question 13","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“九牛二虎之力”比喻用了非常大的力气，常用在很难做的事情上。","（3）石头很沉重，要用很大的力气才搬得走，用得对。","（1）考试“很简单”、（2）“轻松地”获得冠军、（4）“很聪明”，都说明事情不难，和“费了很大的力气”互相矛盾。","答案是（3）。"]}],"options":["这次的考试很简单，他费了++九牛二虎之力++才完成。","他在比赛中费了++九牛二虎之力++，轻松地获得冠军。","他费了++九牛二虎之力++，才把那块沉重的石头搬走。","他很聪明，费了++九牛二虎之力++就能把谜题解开了。"]},{"id":"chinese-2026-prelim-plmgs-p2-q14","cite":"2026 Prelim PLMGS Paper 2 Question 14","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“争先恐后”的意思是很多人抢着向前，怕落在别人后面。","（1）大家抢着挤上巴士，用得对。","（2）“排队”是有秩序的，和争先恐后矛盾；（3）“争先恐后”要用在很多人身上，不能只说小明一个人；（4）去游玩不需要抢着去。","答案是（1）。"]}],"options":["巴士一到站，大家就++争先恐后++地挤上巴士。","放学了，同学们++争先恐后++地排队走出校园。","比赛一开始，小明++争先恐后++地跑到最前面。","放假了，我们应该++争先恐后++地到处去游玩。"]},{"id":"chinese-2026-prelim-plmgs-p2-q15","cite":"2026 Prelim PLMGS Paper 2 Question 15","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“气氛”是在一个地方、一个场合里，人们感觉到的情绪，例如“节日的气氛”“热闹的气氛”。","（1）“充满了节日的气氛”用得对。","（2）应该用“清新的空气”；（3）“优美”形容的是“环境”；（4）“五彩缤纷”形容颜色，不能形容气氛，可以说“气氛很热闹”。","答案是（1）。"]}],"options":["在农历新年期间，到处充满了节日的++气氛++。","我常到公园运动，因为那里有清新的++气氛++。","校园里的++气氛++很优美，能让同学们好好读书。","生日会的++气氛++五彩缤纷，大家都玩得很开心。"]},{"id":"chinese-2026-prelim-plmgs-p2-q16","cite":"2026 Prelim PLMGS Paper 2 Question 16","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“不知该怎么办才好”，说明妈妈心里很烦，想不出办法，这就是“苦恼”。","“唠叨”是说个不停，“为此事唠叨，不知该怎么办才好”接不上。","答案是（1）苦恼。"]}],"group":"chinese-2026-prelim-plmgs-g1","options":["苦恼","唠叨","批评","关心"]},{"id":"chinese-2026-prelim-plmgs-p2-q17","cite":"2026 Prelim PLMGS Paper 2 Question 17","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["志明答应了，“可是”还是像原来那样坐在沙发上玩手机。“依然”的意思是和原来一样，没有改变。","“忽然”是突然，他不是突然才坐下玩手机的；“果然”是和想的一样。","答案是（1）依然。"]}],"group":"chinese-2026-prelim-plmgs-g1","options":["依然","忽然","虽然","果然"]},{"id":"chinese-2026-prelim-plmgs-p2-q18","cite":"2026 Prelim PLMGS Paper 2 Question 18","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["妈妈叫志明去书店领取练习本，长辈叫晚辈做事是“吩咐”。“妈妈吩咐的事情”是正确的说法。","“指令”是名词（下指令），不能说“妈妈指令的事情”。","答案是（2）吩咐。"]}],"group":"chinese-2026-prelim-plmgs-g1","options":["指令","吩咐","联系","介绍"]},{"id":"chinese-2026-prelim-plmgs-p2-q19","cite":"2026 Prelim PLMGS Paper 2 Question 19","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["志明拿错练习本，又忘了付钱，店员还要打电话问妈妈，大家多花了很多时间，所以是“浪费了大家不少时间”。","“节省”的意思刚好相反，是用得少了。","答案是（1）浪费。"]}],"group":"chinese-2026-prelim-plmgs-g1","options":["浪费","减少","增添","节省"]},{"id":"chinese-2026-prelim-plmgs-p2-q20","cite":"2026 Prelim PLMGS Paper 2 Question 20","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["这次志明粗心大意，让妈妈和店员多做了很多事，这些都是“不必要的麻烦”。","“伤害”太严重了，文中没有人受到伤害；“表扬”是好事，粗心不会带来表扬。","答案是（1）麻烦。"]}],"group":"chinese-2026-prelim-plmgs-g1","options":["麻烦","伤害","责任","表扬"]},{"id":"chinese-2026-prelim-plmgs-p2-q21","cite":"2026 Prelim PLMGS Paper 2 Question 21","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"那只狗有什么本领？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看第一、二段：“这只狗从小陪着孩子一起长大”，夫妇俩外出时，“那只狗便会一直守在孩子身边”。","所以这只狗的本领是陪伴、守护孩子。","狗只是“好像听懂了似的”，不是真的能说话。答案是（3）。"]}],"group":"chinese-2026-prelim-plmgs-g2","options":["它能和人类说话。","它能自己找食物。","它能帮忙陪伴孩子。","它能帮男主人工作。"]},{"id":"chinese-2026-prelim-plmgs-p2-q22","cite":"2026 Prelim PLMGS Paper 2 Question 22","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["cause-and-effect","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"男主人要赶走那只狗，是因为______","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["看第四、五段：屋里到处是血迹，孩子不见了，狗的嘴边有鲜血。","男主人看到这一幕，大喊“我的孩子呢？”，又急又怒地把狗打出家门，说明他以为是狗咬伤了孩子。","（1）只是他看到的情形，不是他生气的真正原因。答案是（4）。"]}],"group":"chinese-2026-prelim-plmgs-g2","options":["那只狗的嘴边一直流着血。","那只狗没有好好照顾孩子。","他气那只狗把外人带进屋里。","他以为那只狗伤了他的孩子。"]},{"id":"chinese-2026-prelim-plmgs-p2-q23","cite":"2026 Prelim PLMGS Paper 2 Question 23","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"“男主人终于明白了事情的真相”指的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["这句话后面就说出了真相：“原来，刚才有小偷闯进家里，是狗奋不顾身地保护了孩子。”","狗没有伤害孩子，反而救了孩子，所以男主人知道自己错怪了狗。","答案是（3）。"]}],"group":"chinese-2026-prelim-plmgs-g2","options":["男主人知道孩子去了什么地方。","男主人觉得自己这样做是对的。","男主人发现自己错怪了那只狗。","男主人明白狗要咬孩子的原因。"]},{"id":"chinese-2026-prelim-plmgs-p2-q24","cite":"2026 Prelim PLMGS Paper 2 Question 24","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"你认为男主人是个怎样的人？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["男主人一看到血迹和狗嘴边的血，没有先弄清楚事情，就拿起木棍把狗打出家门。","没有想清楚就马上动手，这就是“冲动”。","答案是（1）。"]}],"group":"chinese-2026-prelim-plmgs-g2","options":["他是个冲动的人。","他是个勇敢的人。","他是个好奇的人。","他是个胆小的人。"]},{"id":"chinese-2026-prelim-plmgs-p2-q25","cite":"2026 Prelim PLMGS Paper 2 Question 25","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["inference","character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一句话是++正确++的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["最后男主人找到受伤的狗，抱住它，流着眼泪说“对不起”，说明他很后悔打了狗。","（1）狗一直守在孩子身边；（3）夫妇俩“不久”就赶回家了；（4）狗咬的是小偷，它被赶走是因为男主人误会了它。","答案是（2）。"]}],"group":"chinese-2026-prelim-plmgs-g2","options":["那只狗不知道怎么陪伴孩子。","男主人为自己的行为感到后悔。","男主人忙于工作，几天无法回家。","那只狗咬人，所以被男主人赶走。"]},{"id":"chinese-2026-prelim-plmgs-p2-q26","cite":"2026 Prelim PLMGS Paper 2 Question 26","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"3","accept":["发生了什么事","3 发生了什么事"]},"explanation":["空格后面是问号，所以要选一个问句。","小乐想找欢欢说话，欢欢答应了，接着会问他有什么事。下一句小乐回答“有件事，我烦恼了很久”，正好回答这个问题。","所以选 3：发生了什么事。（1“你现在有空吗”是小乐问过的，欢欢不会反过来问。）"]}],"group":"chinese-2026-prelim-plmgs-g3"},{"id":"chinese-2026-prelim-plmgs-p2-q27","cite":"2026 Prelim PLMGS Paper 2 Question 27","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"4","accept":["看我能不能帮忙","4 看我能不能帮忙"]},"explanation":["欢欢说“好，你说出来吧”，接着会说她听了以后想做什么。","朋友有烦恼，听了以后是想帮他。","所以选 4：看我能不能帮忙。"]}],"group":"chinese-2026-prelim-plmgs-g3"},{"id":"chinese-2026-prelim-plmgs-p2-q28","cite":"2026 Prelim PLMGS Paper 2 Question 28","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["实在很难做出决定","6 实在很难做出决定"]},"explanation":["小乐说“我舍不得父母，但我也很喜欢新加坡的环境”，两边他都想要。","两边都舍不得，所以很难选择。","所以选 6：实在很难做出决定。"]}],"group":"chinese-2026-prelim-plmgs-g3"},{"id":"chinese-2026-prelim-plmgs-p2-q29","cite":"2026 Prelim PLMGS Paper 2 Question 29","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["让他们知道你的想法","8 让他们知道你的想法"]},"explanation":["欢欢建议小乐“和父母谈谈，______，再决定”。","和父母谈，就是把自己心里想的告诉父母。","所以选 8：让他们知道你的想法。（5“不要听别人的意见”和欢欢正在给意见互相矛盾。）"]}],"group":"chinese-2026-prelim-plmgs-g3"},{"id":"chinese-2026-prelim-plmgs-p2-q30","cite":"2026 Prelim PLMGS Paper 2 Question 30","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"这个广告的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["广告介绍了“防止沉迷网络”活动的地点、时间、费用和报名方法，最后说“欢迎大家积极报名参加”。","所以广告的目的是请大家来参加这个活动。","（1）教导正确使用网络是活动的目的，不是广告的目的；（4）知识竞赛只是活动的一部分。答案是（3）。"]}],"group":"chinese-2026-prelim-plmgs-g4","options":["教导家长和孩子正确使用网络的习惯。","建议家长和孩子参加俱乐部举办的活动。","鼓励家长和孩子参加“防止沉迷网络”活动。","通知家长和孩子“防止沉迷网络”的知识竞赛。"]},{"id":"chinese-2026-prelim-plmgs-p2-q31","cite":"2026 Prelim PLMGS Paper 2 Question 31","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"今年的“防止沉迷网络”活动有什么不同的地方？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["找第二段：“与往年不同的是，除了讲座外，今年也会举办一场与‘防止沉迷网络’有关的知识竞赛。”","“今年也会举办”说明知识竞赛是今年新加的。","（4）奖品只有 10 份，要在竞赛中赢取，不是参加的人都有。答案是（3）。"]}],"group":"chinese-2026-prelim-plmgs-g4","options":["讲座时间比去年的长。","报名的时间比去年早。","增加了一个知识竞赛。","参加活动的人有奖品。"]},{"id":"chinese-2026-prelim-plmgs-p2-q32","cite":"2026 Prelim PLMGS Paper 2 Question 32","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"想了解活动详情的人应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["找最后一段：“如果想了解更多活动详情，请到我们的网站 www.ankang.com 查看。”","办公室是报名的地方，不是了解详情的地方。","答案是（4）。"]}],"group":"chinese-2026-prelim-plmgs-g4","options":["到办公室问工作人员。","找工作人员领取广告。","活动当天去现场询问。","上俱乐部的网站查看。"]},{"id":"chinese-2026-prelim-plmgs-p2-q33","cite":"2026 Prelim PLMGS Paper 2 Question 33","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是小文，你和妈妈看了“防止沉迷网络”的广告后，决定报名参加。请写一张便条给妈妈，提醒她报名时要注意的地方。\n\n便条的开头是：\n妈妈：\n记得我们说过要一起参加安康民众俱乐部举办的“防止沉迷网络”活动，我想提醒您……\n（请接着写下去。）\n\n便条的结尾是：\n小文\n10月2日\n早上9点","parts":[{"label":"","answer":{"type":"self","value":"妈妈：\n记得我们说过要一起参加安康民众俱乐部举办的“防止沉迷网络”活动，我想提醒您报名日期是10月15日至20日，您必须到安康民众俱乐部办公室报名。活动费用是每个人10元，但不必在报名时缴付，活动当天才付款。\n小文\n10月2日\n早上9点"},"explanation":["内容 2 分，表达 2 分，一共 4 分。","题目问的是“报名时要注意的地方”，所以要在广告的格子里找和报名有关的资料。","第一点（报名日期）：10月15日到10月20日。","第二点（报名方式）：要到安康民众俱乐部办公室报名。","第三点（费用）：每人10元，是活动当天才付的，报名时不用付。","活动的地点和时间不是“报名时”要注意的，可以不写。","表达：接着“我想提醒您……”写下去，对妈妈要用“您”，句子要通顺、完整，不要写错字。"]}],"group":"chinese-2026-prelim-plmgs-g4"},{"id":"chinese-2026-prelim-plmgs-p2-q34","cite":"2026 Prelim PLMGS Paper 2 Question 34","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“主动、努力地去做事情”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"积极"},"explanation":["要找一个意思是“自己主动、很努力地去做”的词语。","第一段：美华“平时积极参加学校的各种表演活动”。","答案是“积极”。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q35","cite":"2026 Prelim PLMGS Paper 2 Question 35","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“得到别人关注，使人有兴趣”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"吸引"},"explanation":["要找一个意思是“让别人都注意、都想看”的词语。","第三段：女孩唱得很好听，“深深吸引了台下的观众”。","答案是“吸引”。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q36","cite":"2026 Prelim PLMGS Paper 2 Question 36","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"为什么老师会选美华做戏剧表演的主要演员？","parts":[{"label":"","answer":{"type":"self","value":"老师会选美华做戏剧表演的主要演员，因为美华会唱歌又会跳舞，平时积极参加学校各种表演活动。美华也每天吃完晚饭，就在房间里练习舞蹈。","accept":["老师会选美华做戏剧表演的主要演员，因为美华会唱歌又会跳舞，平时积极参加学校的各种表演活动。"]},"explanation":["答案在第一段：“美华会唱歌又会跳舞，平时积极参加学校的各种表演活动。老师最后选了美华……”","要写出两点：她会唱歌又会跳舞（有本领）；她平时积极参加学校的各种表演活动（有经验、很主动）。","学校的答案还加上第二段的“每天吃完晚饭，就在房间里练习舞蹈”，说明她很努力。把这一点也写上会更完整。","回答“为什么”的问题，要用“因为……”来写。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q37","cite":"2026 Prelim PLMGS Paper 2 Question 37","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":37,"topic":"comprehension-open","subtypes":["inference","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"美华本来想对妈妈说什么？","marks":1,"answer":{"type":"self","value":"美华本来想告诉妈妈她不是主要演员，她演的是小白兔。"},"explanation":["第二段说妈妈以为美华是主要演员，称赞她，“美华似乎想说什么，但还是把话吞了回去”。","看到后面才知道：美华把主要演员的机会让给了小丽，自己演小白兔。所以她本来想说的是这件事。"]},{"label":"b","prompt":"她后来为什么又没说？","marks":2,"answer":{"type":"self","value":"她后来没说，是因为不想让妈妈失望，也想给妈妈一个惊喜。"},"explanation":["答案在第五段美华最后说的话里：“我没告诉您是不想让您失望，也想给您一个惊喜。”","两个原因各 1 分：不想让妈妈失望；想给妈妈一个惊喜。两点都要写。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q38","cite":"2026 Prelim PLMGS Paper 2 Question 38","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":38,"topic":"comprehension-open","subtypes":["character-and-feelings","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"美华的妈妈看表演时心情有什么变化？她为什么会有这样的变化？","parts":[{"label":"","answer":{"type":"self","value":"妈妈的心情先是惊讶和疑惑，后来变得开心，最后感动和骄傲。她看到上台唱歌的主要演员不是美华，所以目瞪口呆。后来听到其他家长称赞美华把“小白兔”演得很好，心里像吃了蜜糖一样甜。表演后她知道美华为了帮助缺乏自信的小丽，主动把主要演员的机会让给她，因此被美华的善良和体贴感动，并为她感到骄傲。"},"explanation":["题目有两问：心情的“变化”和变化的“原因”。要按时间顺序，用“先是……后来……最后……”来写。","先是惊讶：第三段“妈妈看了却目瞪口呆”，因为她发现主要演员不是美华。","后来开心：第四段“心里像吃了蜜糖一样甜”，因为她听到别的家长称赞美华把小白兔演得很好。","最后感动和骄傲：最后一段“妈妈既感动又骄傲”，因为她知道美华是为了帮助没有自信的小丽，才把机会让给她。","每一种心情都要配上原因，不能只写心情。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q39","cite":"2026 Prelim PLMGS Paper 2 Question 39","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":39,"topic":"comprehension-open","subtypes":["character-and-feelings","inference"],"format":"structured","marks":4,"difficulty":2,"stem":"美华是一个怎样的人？从哪些事情上可以看出来？","parts":[{"label":"","answer":{"type":"self","value":"美华是一个善良的人。老师本来选中了美华做主要演员，但美华想到小丽也表演得很好，只是没什么自信，就把机会让给小丽，希望她变得更自信。从这件事可以看出美华是一个善良的人。","accept":["美华是一个善良的人。从“本来老师要在美华和小丽之间做一个选择，最后老师选中了美华。但美华想到小丽也表演得很好，只是没什么自信。”可以看出美华是一个善良的人。"]},"explanation":["先用一个词语说出美华的性格：善良（也可以说她体贴、会为别人着想）。","再用短文里的事情来证明。第五段：老师选中了美华，但她想到小丽表演得好却没有自信，就把主要演员的机会让给小丽。","她没告诉妈妈，是不想让妈妈失望，这也说明她很体贴。","回答的格式：美华是一个……的人。从……可以看出来。只写性格，没有写事情，拿不到全部分数。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-plmgs-p2-q40","cite":"2026 Prelim PLMGS Paper 2 Question 40","year":2026,"exam":"Prelim","school":"PLMGS","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion"],"format":"structured","marks":4,"difficulty":2,"stem":"你同意美华的做法吗？试加以说明。","parts":[{"label":"","answer":{"type":"self","value":"我同意美华的做法。同学们之间应该互相鼓励。小丽也表演得很好，只是缺少自信，上台表演可以让她更有自信。美华这么做也是为了不让妈妈失望，也是给她一个惊喜。","accept":["我不同意美华的做法。老师选中美华，是因为她最适合做主要演员，她应该先和老师、妈妈商量，不应该自己决定把机会让给别人，还瞒着妈妈，让妈妈在看表演时又惊讶又担心。"]},"explanation":["这是看法题。一定要先清楚地写“我同意”或“我不同意”，再说理由。","选“同意”，理由可以用短文里的事：小丽表演得很好，只是没有自信，把机会让给她，她会变得更自信；同学之间应该互相帮助、互相鼓励。","选“不同意”，也要有合理的理由，例如：她没有先告诉妈妈，让妈妈目瞪口呆；这是老师的决定，应该先和老师商量。","只写“同意”或“不同意”，没有理由，是拿不到分数的。"]}],"group":"chinese-2026-prelim-plmgs-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q1","cite":"2026 Prelim Raffles Girls Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n表哥在大学时，上了很多++翻译++课程。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“翻”是前鼻音，读第一声 fān，不是后鼻音 fang。","“译”读第四声 yì，不是第二声 yí。","“翻译”读 fān yì，答案是（1）。"]}],"options":["fān yì","fán yí","fǎng yi","fàng yí"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q2","cite":"2026 Prelim Raffles Girls Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n上中学的丽丽下课后去做服务员，帮忙++赚钱++养家。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“赚”是翘舌音，声母是 zh，读第四声 zhuàn，不是平舌音 zuan。","“钱”读第二声 qián，不是第三声 qiǎn。","“赚钱”读 zhuàn qián，答案是（4）。"]}],"options":["zuān qiǎn","zuàn qiǎn","zhuān qián","zhuàn qián"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q3","cite":"2026 Prelim Raffles Girls Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n上个星期五，我们全家一起参加了姐姐的______业典礼。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“毕业”的意思是在学校学完了课程，“毕”有“完成、结束”的意思。","“闭”是“关闭”的闭，“币”是“钱币”的币，“必”是“必须”的必，读音一样，但意思不对。","答案是（1）毕。"]}],"options":["毕","闭","币","必"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q4","cite":"2026 Prelim Raffles Girls Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这所新加坡北部的体育学校，______养了很多人才。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“培养”的意思是长期地教育和训练，使人成长。“培”是土字旁，本来是给植物加土的意思。","“赔”是“赔钱”的赔，“陪”是“陪伴”的陪，“倍”是“加倍”的倍，这几个字样子很像，但意思不对。","答案是（3）培。"]}],"options":["赔","陪","培","倍"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q5","cite":"2026 Prelim Raffles Girls Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这份小组作业的______方式不限，可以画画也可以表演。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“呈现”的意思是把东西显示出来给人看。“呈现方式”就是用什么方法把作业的内容展示出来。","“展览”是把东西摆出来让很多人参观，表演不能说是“展览”；“表示”是说出想法或态度，不能说“表示方式不限”。","答案是（4）呈现。"]}],"options":["展览","说明","表示","呈现"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q6","cite":"2026 Prelim Raffles Girls Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n由于明天有考试，国强还在______是否出席今晚的聚会。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“是否”的意思是“要不要、去不去”，说明国强还没有决定，正在想。“考虑”就是仔细地想了再做决定。","“回想”是想过去的事；“盼望”是很希望，后面不能接“是否”。","答案是（2）考虑。"]}],"options":["回想","考虑","比较","盼望"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q7","cite":"2026 Prelim Raffles Girls Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n警察在森林里++搜索++了几个小时，终于救出了迷路的人。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“搜索”的意思是到处仔细地找。警察在森林里是要找迷路的人。","“详细检查”是查看东西有没有问题，不是找人。","答案是（2）仔细寻找。"]}],"options":["认真观看","仔细寻找","详细检查","小心安排"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q8","cite":"2026 Prelim Raffles Girls Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这件衣服看起来++普通++，可是穿起来很舒服。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“普通”的意思是平常、一般，和别的没有什么不同，也就是“不特别”。","“普通”不等于不好看，也不是说价钱便宜；“杰出”是用来形容人的才能的，不用来形容衣服。","答案是（4）不特别。"]}],"options":["不值钱","不杰出","不美丽","不特别"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q9","cite":"2026 Prelim Raffles Girls Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______你是组长，______也应该问一问组员的想法。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["前面说“你是组长”（可以自己做决定），后面说“也应该问组员的想法”，意思转了一个弯，要用表示转折的“虽然……但是……”。","“只要……就能……”表示条件；“不但……反而……”表示出现相反的结果，放进句子里都说不通。","答案是（3）虽然……但是。"]}],"options":["只要……就能","反正……不如","虽然……但是","不但……反而"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q10","cite":"2026 Prelim Raffles Girls Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______心情不好，姐姐______不会乱发脾气。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["句子的意思是：即使心情不好，姐姐还是不会乱发脾气。要用“就算……也……”。","“如果……就……”放进去变成“心情不好就不会发脾气”，不合道理；“尽管”要和“还是、也”搭配，不能说“尽管……还不会”。","答案是（2）就算……也。"]}],"options":["除了……还","就算……也","如果……就","尽管……还"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q11","cite":"2026 Prelim Raffles Girls Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，妈妈催我赶快去机场。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“催我赶快去”说明时间很紧，前面要说出时间紧的原因。","（1）飞机快要起飞了，所以妈妈才催。（2）“时间还早”就不用催了，意思相反。","答案是（1）。"]}],"options":["飞机还有两个小时就起飞了","现在离出发的时间还早着呢","我向叔叔学如何上网订机票","我昨天早上已经抵达了终点"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q12","cite":"2026 Prelim Raffles Girls Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n学校外面今早交通堵塞，____________。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“交通堵塞”就是路上的车太多，走不动。后面要接堵车带来的结果。","（3）车子只能慢慢地走，正是堵车的结果。（1）（2）说的是发生意外，句子里没有提到意外。","答案是（3）。"]}],"options":["救护人员能把受伤的司机送去医院","大家不管三七二十一拼命地喊救命","路上的车子只能慢慢地往前方行驶","巴士司机经常提醒大家要遵守规则"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q13","cite":"2026 Prelim Raffles Girls Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“坚固”形容东西（桥、房子、城墙）很结实，不容易坏。它不能用来形容人。","（4）形容桥，用得对。","（1）应该用“坚持”，（2）力气应该说“大”，（3）应该用“固执”。","答案是（4）。"]}],"options":["每天早上和傍晚，爸爸都++坚固++去公园跑步。","妹妹的个子矮小，但力气却比任何人++坚固++。","弟弟从小到大都很++坚固++，不听别人的劝告。","这座桥建造得十分++坚固++，可以使用很多年。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q14","cite":"2026 Prelim Raffles Girls Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“防止”是事先想办法，不让不好的事情发生。","（1）不在食堂奔跑，是为了不让意外发生，用得对。","（2）应该用“禁止”；（3）事情已经在发生了，应该用“阻止”；（4）应该用“停止”。","答案是（1）。"]}],"options":["为了++防止++意外的发生，我们不能在食堂奔跑。","地铁上++防止++大声说话，乘客们都小声地谈天。","看到他用石头丢小猫，我们立刻上前++防止++他。","突然下起了倾盆大雨，这场比赛只好先++防止++。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q15","cite":"2026 Prelim Raffles Girls Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“巧妙”形容方法或做法很聪明、很灵巧。","（4）小月把动作和乐曲结合得很好，是做法高明，用得对。","（1）是刚好遇到，应该用“碰巧”；（3）应该用“奇妙”；（2）唱好歌靠的是练习，不是“巧妙”。","答案是（4）。"]}],"options":["今天爷爷下楼散步时，++巧妙++地遇到了邻居王伯伯。","姐姐参加了合唱团之后，十分++巧妙++地把歌曲唱好。","昨晚我做了一个++巧妙++的梦，梦见自己去月球旅行。","小月++巧妙++地结合动作和乐曲，跳出了优美的舞蹈。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q16","cite":"2026 Prelim Raffles Girls Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["后面说同学们“觉得浪费时间”，说明他们不明白这个活动有什么用处、有什么价值，也就是不了解活动的“意义”。","“流程”是活动的步骤；不知道步骤，不会觉得“浪费时间”。","答案是（4）意义。"]}],"group":"chinese-2026-prelim-raffles-girls-g1","options":["道理","结果","流程","意义"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q17","cite":"2026 Prelim Raffles Girls Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“学习表现”。课前做好准备，上课的表现会更好。“提高……表现”是正确的搭配。","“影响”可好可坏，前面有“有效地”，说明是变得更好，所以用“提高”更合适。","答案是（1）提高。"]}],"group":"chinese-2026-prelim-raffles-girls-g1","options":["提高","影响","代替","控制"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q18","cite":"2026 Prelim Raffles Girls Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["同学们更专心了，任务就能没有阻碍地做完，这叫“顺利地完成”。","“能干”是形容人有本领的，不能说“能干地完成”。","答案是（2）顺利。"]}],"group":"chinese-2026-prelim-raffles-girls-g1","options":["勇敢","顺利","丰富","能干"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q19","cite":"2026 Prelim Raffles Girls Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["空格说的是“学习态度”。大家会主动想“可以如何做得更好”，这是态度“积极”。“态度积极”是固定搭配。","“优秀”常用来形容成绩或人，不常用来形容态度。","答案是（3）积极。"]}],"group":"chinese-2026-prelim-raffles-girls-g1","options":["优秀","美好","积极","珍贵"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q20","cite":"2026 Prelim Raffles Girls Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“小小的改变”和后面的进步是相对的：改变虽小，进步却很大。“巨大的进步”是正确的搭配。","“宽阔”形容地方（马路、操场）很宽，不能形容进步。","答案是（2）巨大。"]}],"group":"chinese-2026-prelim-raffles-girls-g1","options":["清楚","巨大","暂时","宽阔"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q21","cite":"2026 Prelim Raffles Girls Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"“每天店门前总是排着长长的人龙”，这句话说明了什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“人龙”就是排得很长的队。很多人愿意排队买，说明这家店的粥很受欢迎。","第一段说“店里卖的粥味道十分鲜美”，这就是大家来排队的原因。","短文说“每天”都排长龙，不是只有假期才多人；外公是“忙得团团转”，不是动作慢。答案是（4）。"]}],"group":"chinese-2026-prelim-raffles-girls-g2","options":["每天清晨，附近的居民聚在一起喝粥。","假期一到，来喝瘦肉粥的顾客就很多。","外公的动作非常慢，顾客们要等很久。","瘦肉粥的味道很鲜美，受到顾客欢迎。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q22","cite":"2026 Prelim Raffles Girls Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["factual","character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"当立明发现顾客多给了五十元时，他有什么想法？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["第二段说他“心里偷偷一乐，正想把钱收起来”。","第四段他说：“就不能当作我忙了一整天的奖励吗？”可见他想把这笔钱当作奖励。","他知道顾客是“不小心”多给的，不是慷慨。答案是（4）。"]}],"group":"chinese-2026-prelim-raffles-girls-g2","options":["担心外公发现这笔钱。","认为顾客对他十分慷慨。","决定等顾客自己回来拿钱。","觉得应该把这笔钱当作奖励。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q23","cite":"2026 Prelim Raffles Girls Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"外公看到立明想把钱收起来时，有什么感受？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["第二段：外公“向他投去不满的目光”。","第三段：外公“怒气冲冲地说”。“怒气冲冲”就是很生气的样子。","答案是（1）。"]}],"group":"chinese-2026-prelim-raffles-girls-g2","options":["他感到生气。","他感到为难。","他感到伤心。","他感到不安。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q24","cite":"2026 Prelim Raffles Girls Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["main-idea","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"你可以从外公身上学到什么？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["外公说：“这钱不是我们的，不应该拿！”又说：“做人要诚实。”","第二天他把多收的五十元还给了顾客。不是自己的钱不拿，就是不贪财。","短文的重点不是外公工作勤奋，也不是有礼貌。答案是（2）。"]}],"group":"chinese-2026-prelim-raffles-girls-g2","options":["做事不马虎。","不应该贪财。","要勤奋工作。","待人要有礼。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q25","cite":"2026 Prelim Raffles Girls Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["inference","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"为什么立明觉得顾客的感谢比得到五十元更可贵？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["看最后一段：外公把钱还给顾客，顾客“连声道谢”。","立明看到，做一个诚实的人能得到别人真心的感谢，这种快乐比五十元更宝贵。","短文讲的道理是“做人要诚实”，不是保管好钱，也不是不要抱怨。答案是（3）。"]}],"group":"chinese-2026-prelim-raffles-girls-g2","options":["因为他学到了应该把钱保管好。","因为他明白了不应该经常抱怨。","因为他感受到诚实带来的幸福。","因为他觉得没办法赚到更多钱。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q26","cite":"2026 Prelim Raffles Girls Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"1","accept":["心里感到有点慌"]},"explanation":["丁月说“我点不着火，______”，空格要说点不着火时他的感受或结果。","妈妈接着说“哎呀，那怎么办？”，说明丁月遇到了麻烦，还没解决。","所以选 1：心里感到有点慌。（5“只好请级任老师来帮忙”不对，因为后来是小光教他的。）"]}],"group":"chinese-2026-prelim-raffles-girls-g3"},{"id":"chinese-2026-prelim-raffles-girls-p2-q27","cite":"2026 Prelim Raffles Girls Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["一步一步地教我和队友们煎蛋呢"]},"explanation":["“他还______”，“还”说明小光除了教点火，又做了另一件帮忙的事。","妈妈说“团结就是力量，他真是个好队友”，后面丁月吃的是“蛋炒饭”，所以和煎蛋有关。","所以选 8：一步一步地教我和队友们煎蛋呢。（4“便替我把晚饭做完”不对，因为蛋炒饭是丁月“亲手做的”。）"]}],"group":"chinese-2026-prelim-raffles-girls-g3"},{"id":"chinese-2026-prelim-raffles-girls-p2-q28","cite":"2026 Prelim Raffles Girls Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["那你们最后做出晚饭了吗"]},"explanation":["空格是妈妈问的问题。看丁月的回答：“当然！”","“当然”是用来回答“……了吗？”这种问题的，不能回答“做出了什么晚饭”。","所以选 6：那你们最后做出晚饭了吗。（7 问的是“什么晚饭”，回答应该是饭菜的名字。）"]}],"group":"chinese-2026-prelim-raffles-girls-g3"},{"id":"chinese-2026-prelim-raffles-girls-p2-q29","cite":"2026 Prelim Raffles Girls Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"2","accept":["遇到困难不能退缩","2 遇到困难不能退缩"]},"explanation":["“这次露营让我明白，______”，空格是丁月学到的道理。","妈妈刚说“知道你没有半途而废”，丁月说“是的”，所以道理是遇到困难也不放弃。","所以选 2：遇到困难不能退缩。"]}],"group":"chinese-2026-prelim-raffles-girls-g3"},{"id":"chinese-2026-prelim-raffles-girls-p2-q30","cite":"2026 Prelim Raffles Girls Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"欢乐民众俱乐部举办这场书展的目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["目的通常写在开头。广告第一段：“为了鼓励孩子们在假期时能养成阅读的好习惯，欢乐民众俱乐部特别举办这场书展。”","“为了”后面就是举办的目的。","小礼包只是给前 50 名买书的读者的礼物，不是举办书展的目的。答案是（2）。"]}],"group":"chinese-2026-prelim-raffles-girls-g4","options":["邀请著名的诗人来教孩子们如何写诗歌。","鼓励孩子们在假期里养成阅读的好习惯。","为了让孩子们都有机会获得免费的小礼包。","让父母能够在书展期间多买些书籍给孩子。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q31","cite":"2026 Prelim Raffles Girls Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"要怎样才能免费获得“惊喜小礼包”？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["找到这句话：“现场购买书本的前 50 名读者，将免费获得一份惊喜小礼包。”","条件有两个：要在现场“购买书本”，而且是“前 50 名”。","只是最早进去参观、没有买书的人拿不到。答案是（3）。"]}],"group":"chinese-2026-prelim-raffles-girls-g4","options":["最早进入书展参观的 50 人。","活动期间获取签名的 50 人。","最先在书展购买书的 50 人。","带着孩子参加书展的 50 人。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q32","cite":"2026 Prelim Raffles Girls Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"想要获取胡田的签名，应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看“签名会”那一项：“6 月 16 日下午三点，最受欢迎漫画家胡田将来到现场。赶紧带上胡田的书，来获取签名吧！”","所以要在 6 月 16 日到书展去。","林美是诗人，她来的是 5 月 30 日的讲座；要带的是胡田的书，不是林美的书。答案是（2）。"]}],"group":"chinese-2026-prelim-raffles-girls-g4","options":["带林美的书去书展现场。","6 月 16 日到中文书展去。","5 月份去欢乐民众俱乐部。","在现场购买 50 元的中文书。"]},{"id":"chinese-2026-prelim-raffles-girls-p2-q33","cite":"2026 Prelim Raffles Girls Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是小安，看到这则广告后，想起好朋友小乐很喜欢诗歌。请写一个手机短信给小乐，告诉她可以参加哪一个活动，以及活动在什么时候举行。\n\n短信的开头是：\n小乐，我看到了“书香伴我行”的广告。我想和你一起去书展……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"小乐，我看到了“书香伴我行”的广告。我想和你一起去书展，参加林美的讲座。讲座会在5月30日下午两点举行。我知道你很喜欢诗歌，所以我希望你能和我参加！"},"explanation":["一共 4 分，内容和语文都要顾到。","内容第一点（参加哪一个活动）：小乐喜欢诗歌，所以要找和诗歌有关的活动——著名诗人林美的讲座。“签名会”是漫画家胡田的，不合适。","内容第二点（什么时候举行）：5月30日下午两点。日期和时间都要写。","可以加一句说明原因：我知道你很喜欢诗歌，希望你能和我一起参加。","语文：接着“我想和你一起去书展……”写下去，句子要通顺、完整，不要写错字。"]}],"group":"chinese-2026-prelim-raffles-girls-g4"},{"id":"chinese-2026-prelim-raffles-girls-p2-q34","cite":"2026 Prelim Raffles Girls Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“因为常做而了解、有经验”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"熟练"},"explanation":["要找一个意思是“做得多了，所以做得很好、很有经验”的词语。","第一段：“当家人在熟练地使用手机时”。家人天天用手机，所以用得很熟。","答案是“熟练”。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q35","cite":"2026 Prelim Raffles Girls Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中表示“最主要的，不能少的”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"基本"},"explanation":["要找一个意思是“最重要、最起码、一定要有”的词语。","第六段：“直到他学会了手机的基本用法”。基本用法就是最主要、一定要会的用法。","答案是“基本”。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q36","cite":"2026 Prelim Raffles Girls Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"爷爷看到家人使用手机时，他有什么反应？","marks":1,"answer":{"type":"self","value":"爷爷看到家人使用手机时，总是盯着他们的手机屏幕。"},"explanation":["答案在第一段最后一句：“当家人在熟练地使用手机时，爷爷总是盯着他们的手机屏幕。”","“反应”就是他做了什么：盯着手机屏幕看。"]},{"label":"b","prompt":"他为什么有这样的反应？","marks":2,"answer":{"type":"self","value":"因为越来越多的人使用手机，爷爷十分好奇，想知道手机里到底藏着什么有趣的新事物。"},"explanation":["原因在第一段前两句，“因此”前面的话就是原因。","要写出两点：越来越多的人使用手机；爷爷十分好奇，想知道手机里到底藏着什么有趣的新事物。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q37","cite":"2026 Prelim Raffles Girls Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":37,"topic":"comprehension-open","subtypes":["cause-and-effect","inference"],"format":"structured","marks":3,"difficulty":2,"stem":"为什么爷爷一开始拒绝学用手机？","parts":[{"label":"","answer":{"type":"self","value":"因为爷爷说自己年纪大了，眼睛也看不清了。爷爷其实想学用手机，但又担心自己学不会，所以他一开始拒绝学用手机。"},"explanation":["答案在第二段。","先写爷爷自己说的理由：“我年纪大了，眼睛也看不清！”（年纪大、眼睛看不清两点都要写。）","再写明文看出来的真正原因：爷爷其实想学用手机，但又担心学不会。","只写爷爷嘴上说的理由是不够的，“担心学不会”一定要写。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q38","cite":"2026 Prelim Raffles Girls Paper 2 Question 38","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":38,"topic":"comprehension-open","subtypes":["factual"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"爷爷学用手机时遇到哪些困难？","marks":2,"answer":{"type":"self","value":"爷爷学开手机时，总是记不住刚学的步骤。学发短信时，他想打字，但找字找了半天才打出一句话。"},"explanation":["题目问“哪些”，说明困难不止一个。有两个，各 1 分。","第一个在第三段：学开手机时，“总是记不住刚学的步骤”。","第二个在第五段：学发短信时，“找字找了半天才打出一句话”。"]},{"label":"b","prompt":"他怎么克服那些困难？","marks":2,"answer":{"type":"self","value":"明文安慰爷爷，再三教爷爷怎样开手机，爷爷终于学会了。爸爸鼓励爷爷，还教他用“说话”的方式打字。"},"explanation":["每一个困难都要写出是怎么解决的，各 1 分。","记不住步骤：第四段，明文安慰他，再三教他怎样开手机，他终于学会了。","打字很慢：第五段，爸爸鼓励他，还教他用“说话”的方式打字，爷爷觉得这个方法方便多了。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q39","cite":"2026 Prelim Raffles Girls Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":39,"topic":"comprehension-open","subtypes":["inference"],"format":"structured","marks":4,"difficulty":2,"stem":"“我才能打开新世界的大门”，这句话说明了什么？","parts":[{"label":"","answer":{"type":"self","value":"这句话说明，爷爷学会了手机的基本用法，会用手机跟朋友聊天，会阅读新闻了解天下事，还会上网购物。手机里什么都有，这让爷爷的生活变得更加丰富多彩。爷爷感谢明文家人的帮助，让他的生活方便。"},"explanation":["先弄清楚“新世界的大门”指什么：爷爷学会用手机以后，接触到很多以前不知道的新事物。","第一点：爷爷学会了手机的基本用法。","第二点：他会用手机跟朋友聊天、阅读新闻了解天下事、上网购物（第六段）。","第三点：手机里什么都有，让他的生活变得更加丰富多彩（最后一段）。","第四点：注意“才能”两个字——有了家人的耐心帮助，他才学得会，所以爷爷很感谢家人。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p2-q40","cite":"2026 Prelim Raffles Girls Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p2","number":40,"topic":"comprehension-open","subtypes":["character-and-feelings","inference"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"文中的明文是个怎样的人？","marks":2,"answer":{"type":"self","value":"文中的明文是个有耐心的人。","accept":["明文是个有耐心的人。","明文是个有耐心的人","文中的明文是个有耐心的人"]},"explanation":["从明文做的事情来想他的性格：爷爷学了又忘，明文没有生气，也没有放弃，一遍又一遍地教。","这说明他是个有耐心的人。"]},{"label":"b","prompt":"你是怎么知道的？","marks":2,"answer":{"type":"self","value":"明文教爷爷打开手机时，爷爷总是记不住刚学的步骤，好几次都想放弃。明文安慰他，告诉他自己小时候也常写错字，让爷爷慢慢学，多学几遍就会了。明文再三教爷爷怎样开手机。最终，爷爷在明文耐心的教导下学会了开手机。"},"explanation":["要用短文里的事情来证明明文有耐心。","第三、四段：爷爷总是记不住步骤，想放弃；明文安慰他“别怕，慢慢学，多学几遍就会了”，再三地教，直到爷爷学会。","也可以写第六段：明文“又不断重复地教爷爷”，直到他学会了手机的基本用法。","“再三”“不断重复”这些词语最能说明他有耐心。"]}],"group":"chinese-2026-prelim-raffles-girls-g5"},{"id":"chinese-2026-prelim-raffles-girls-p1-q1","cite":"2026 Prelim Raffles Girls Paper 1 Question 1","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p1","number":1,"topic":"writing","subtypes":["topic-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第一题：这件事让我看到了人与人之间的温情\n\n在作文时，你可以参考下面的提示：\n• 这是一件什么事\n• 这件事跟什么人有关\n• 事情是怎么发生的\n• 你对这件事有什么感受","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：关键词是“温情”和“人与人之间”。“温情”是人对人的关心和爱护。要写一件你亲眼看到或亲身经历的事，事情里要有人帮助、关心别人。","选材：可以写陌生人之间（路人扶起跌倒的老人、乘客让座、好心人送迷路的小孩回家），也可以写邻居、同学之间互相帮助的事。","开头：交代时间、地点、人物，简单说出是什么事。也可以先写当时的天气或环境，例如下着大雨的傍晚。","经过：这是最重要的部分。先写有人遇到了困难，再写别人是怎么帮助他的。要写出人物的动作、语言和表情，让读的人感受到温暖。","结尾：回到题目，写出你的感受，例如“这件事让我看到了人与人之间的温情，我也要做一个乐于助人的人”。","好词好句：热心、主动、二话不说、伸出援手、雪中送炭、心里暖洋洋的、感激不尽、助人为快乐之本。"]}]},{"id":"chinese-2026-prelim-raffles-girls-p1-q2","cite":"2026 Prelim Raffles Girls Paper 1 Question 2","year":2026,"exam":"Prelim","school":"Raffles Girls","section":"p1","number":2,"topic":"writing","subtypes":["picture-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第二题：仔细看下列的图，根据图意，完成一篇短文。\n在作文时，你可以参考所提供的词语。\n\n[[img1]]\n\n参考词语：有事出门、帮忙照顾、养的猫、水枪、射小猫、痛得叫了一声、欺负、阻止","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：六幅图都要写，前五幅按顺序写清楚，第六幅是问号，要自己想一个合理的结局。","开头（图 1）：邻居阿姨有事出门，把小弟弟带来，请“我”帮忙照顾。交代时间、地点和人物。","经过（图 2 到图 5）：“我”走开了一会儿，小弟弟看到“我”家养的猫睡在篮子里，就拿水枪射小猫。小猫痛得叫了一声，吓得跳出篮子逃走。“我”听到声音赶过来，马上阻止他。要写出人物的动作、语言和心情，也可以写小猫可怜的样子。","结尾（图 6）：可以写“我”耐心地告诉小弟弟，小猫也会痛，不可以欺负小动物；小弟弟知道错了，向小猫道歉，以后还和小猫成了好朋友。阿姨回来后的反应也可以写。","最后写出道理或感受：我们要爱护小动物；照顾小孩要有耐心，要好好教导。","好词好句：把提供的词语用上（有事出门、帮忙照顾、养的猫、水枪、射小猫、痛得叫了一声、欺负、阻止）。还可以用：调皮捣蛋、吓了一跳、连忙、语重心长、低下了头、知错能改。"]}],"images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-p1-q2-img1","alt":"六幅图。图 1：男孩打开家门，一位阿姨带着一个小男孩站在门口。图 2：男孩走开了，小男孩拿着水枪走向睡在篮子里的小猫。图 3：小男孩用水枪对着篮子里的小猫。图 4：小男孩用水枪射小猫，小猫跳出篮子逃走，男孩在门边看到了，很吃惊。图 5：小猫痛得大叫着跑开，男孩伸手阻止小男孩。图 6：一个问号，结局要自己想。"}]},{"id":"chinese-2026-prelim-red-swastika-p1-q1","cite":"2026 Prelim Red Swastika Paper 1 Question 1","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p1","number":1,"topic":"writing","subtypes":["topic-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第一题：**这件事让我知道家人的爱一直都在**\n\n在作文时，你可以参考下面的提示：\n• 你和哪一位家人之间有了误会\n• 后来发生了什么事情\n• 这位家人或者周围的人为你做了什么\n• 这件事让你有什么感受","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：题目的重点是“这件事”和“家人的爱一直都在”。要写一件具体的事：先有误会，后来才发现家人其实一直爱着自己。","开头：交代时间、人物和误会是怎么来的。例如：妈妈最近总是很晚回家，也忘了我的生日，我以为她不关心我了。","经过：这是最重要的部分。写后来发生了什么事（例如我生病了、遇到困难了），家人或周围的人为我做了什么。要写出人物的动作、语言和自己的心理变化：从生气、难过，到惊讶，再到感动、惭愧。","结尾：回到题目，写出感受和明白的道理。例如：原来家人的爱一直都在，只是我没有发现；以后我要多体谅家人，有误会要好好沟通。","好词好句：闷闷不乐、一言不发、恍然大悟、无微不至、热泪盈眶、惭愧不已；“我的眼泪像断了线的珠子一样掉下来。”“一股暖流涌上我的心头。”","评分：内容 20 分，表达 20 分，一共 40 分。"]}]},{"id":"chinese-2026-prelim-red-swastika-p1-q2","cite":"2026 Prelim Red Swastika Paper 1 Question 2","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p1","number":2,"topic":"writing","subtypes":["picture-composition"],"format":"structured","marks":40,"difficulty":2,"stem":"下列两题，只需选做一题，字数在 100 以上。\n\n第二题：仔细看下列的图，根据图意，完成一篇短文。在作文时，你可以参考所提供的词语。\n\n[[img1]]","parts":[{"label":"","answer":{"type":"self","value":"作文没有固定答案。请对照下面的要点检查自己的作文。"},"explanation":["审题：仔细看每一幅图，弄清楚人物（哥哥、妹妹、哥哥的同学、同学的小弟弟）、地点（家里的客厅）和事情的起因、经过、结果。五幅图的内容都要写到。","开头：写图一。交代时间、人物：哥哥的同学带着弟弟来家里做功课，哥哥和妹妹热情地欢迎他们。","经过：写图二到图五。哥哥和同学讨论作业，妹妹在茶几上画画，小弟弟在一旁玩。妹妹去拿彩色笔的时候，小弟弟想要帮忙，就在画上涂了起来。妹妹回来一看，画被涂坏了，伤心地哭了。小弟弟不知所措，哥哥和同学连忙转头。重点写人物的动作、表情、对话和心里的想法。","结尾：图六是问号，要自己想一个合理的结局。例如：哥哥了解了事情的经过，安慰妹妹说弟弟只是想帮忙；小弟弟向姐姐道歉，妹妹原谅了他，还教他一起画画。最后写出明白的道理：遇到事情要先弄清楚原因，要学会体谅和原谅别人。","好词好句：尽量用上参考词语（欢迎、讨论作业、画画、拿彩色笔、想要帮忙、伤心地哭、连忙转头、不知所措）。还可以用：聚精会神、兴致勃勃、目瞪口呆、泪如雨下、破涕为笑、好心办坏事。","评分：内容 20 分，表达 20 分，一共 40 分。"]}],"images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-p1-q2-img1","alt":"六幅图。图一：哥哥的同学带着小弟弟来家里，哥哥和妹妹在门口欢迎他们。图二：哥哥和同学在饭桌旁讨论作业，妹妹在茶几上画画，小弟弟坐在地上玩玩具车。图三：妹妹想到彩色笔，起身去拿，小弟弟转头看着茶几上的画。图四：小弟弟想着要帮姐姐，拿起笔在妹妹的画上涂画，妹妹正拿着彩色笔走回来。图五：妹妹看到自己的画，伤心地哭了，小弟弟不知所措，哥哥和同学连忙转头看。图六：一个问号。参考词语：欢迎、讨论作业、画画、拿彩色笔、想要帮忙、伤心地哭、连忙转头、不知所措。"}]},{"id":"chinese-2026-prelim-red-swastika-p2-q1","cite":"2026 Prelim Red Swastika Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n虽然时间已经很晚，同学们++仍然++留下来讨论问题。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“仍”读第二声 réng，不是第一声 rēng（rēng 是“扔”）。","“然”的声母是 r，读 rán，不是 nán 或 lán。","“仍然”读 réng rán，答案是（3）。"]}],"options":["rēng nán","rēng rán","réng rán","réng lán"]},{"id":"chinese-2026-prelim-red-swastika-p2-q2","cite":"2026 Prelim Red Swastika Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n我慢慢地++恢复++了自信，回答老师的次数也越来越多了。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“恢”读第一声 huī，不是 huí 或 huì。","“复”读 fù，韵母是 u，不是 ei。","“恢复”读 huī fù，答案是（1）。"]}],"options":["huī fù","huí fú","huì fèi","huī fēi"]},{"id":"chinese-2026-prelim-red-swastika-p2-q4","cite":"2026 Prelim Red Swastika Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n那位表演者很棒，他都可以模______别人做的动作。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“模仿”的意思是照着别人的样子去做。表演者能学别人的动作，就是“模仿”。","这四个字都是单人旁，容易看错：“亿”是数字，“促”是促进的促，“依”是依靠的依。","答案是（2）仿。"]}],"options":["亿","仿","促","依"]},{"id":"chinese-2026-prelim-red-swastika-p2-q5","cite":"2026 Prelim Red Swastika Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老师对学生的作业要求很______，每一个错别字都不放过。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“要求很严格”是固定搭配，意思是标准很高，一点也不马虎。后面说“每一个错别字都不放过”，正是严格的表现。","“细心”和“认真”是形容人做事的态度，可以说“老师很认真”，但不说“要求很认真”。","答案是（1）严格。"]}],"options":["严格","细心","认真","自豪"]},{"id":"chinese-2026-prelim-red-swastika-p2-q6","cite":"2026 Prelim Red Swastika Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老板和员工们正在开会，我们别进去______他们。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“打扰”的意思是影响别人做事。别人在开会，我们进去就会打扰他们。","“吵闹”后面不能接人，不能说“吵闹他们”。","答案是（2）打扰。"]}],"options":["欢迎","打扰","吵闹","帮助"]},{"id":"chinese-2026-prelim-red-swastika-p2-q7","cite":"2026 Prelim Red Swastika Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n这些建筑工人为国家的早期建设做出了巨大的++贡献++。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“贡献”的意思是为国家、为大家出力，做有益的事。","建筑工人盖房子、建设国家，就是为国家和人民尽一份力。","“使国家和人民得到关怀”说的是关心，不是出力。答案是（3）。"]}],"options":["让人民明白建筑的重要","使国家和人民得到关怀","为国家和人民尽一份力","让人民有建设国家的机会"]},{"id":"chinese-2026-prelim-red-swastika-p2-q8","cite":"2026 Prelim Red Swastika Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n打雷了，妈妈++暂时++不让我们出去外面玩。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“暂时”的意思是在短时间里，过一会儿情况就会改变。","妈妈只是在打雷的这段时间不让我们出去，雷停了就可以去。","“一眨眼”是形容时间过得非常快，意思不一样。答案是（4）短时间。"]}],"options":["永远","立刻","一眨眼","短时间"]},{"id":"chinese-2026-prelim-red-swastika-p2-q9","cite":"2026 Prelim Red Swastika Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______天气很热，小明还是坚持每天跑步锻炼身体。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["后面有“还是”，要找能和它搭配的关联词：“尽管……还是……”，意思和“虽然……但是……”差不多。","“由于”要配“所以”，“如果”要配“就”，“只有”要配“才”。","天气热，可是小明照样跑步，意思有转折。答案是（1）尽管。"]}],"options":["尽管","由于","如果","只有"]},{"id":"chinese-2026-prelim-red-swastika-p2-q10","cite":"2026 Prelim Red Swastika Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n大明______勤奋好学，______喜欢帮助别人。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“勤奋好学”和“喜欢帮助别人”都是大明的优点，后一个比前一个更进一步，要用“不仅……而且……”。","“一边……一边……”用在同时做的两个动作上（一边走一边唱）。两个都是优点，没有转折，不能用“虽然……但是……”。","答案是（4）不仅……而且。"]}],"options":["一边……一边","因为……所以","虽然……但是","不仅……而且"]},{"id":"chinese-2026-prelim-red-swastika-p2-q11","cite":"2026 Prelim Red Swastika Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n也许你用小华的方法，____________。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“也许”表示不肯定，只是有可能。","（1）“一定会”太肯定，和“也许”有冲突。（2）（4）和“用小华的方法”接不上。","“也许……就可以……了”表示有可能做到，句子通顺。答案是（3）。"]}],"options":["一定会成功完成任务的","不可以准备更多的工具","就可以查出大象的重量了","应该去问问老师的意见吧"]},{"id":"chinese-2026-prelim-red-swastika-p2-q12","cite":"2026 Prelim Red Swastika Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，小明用了有趣的方法来呈现。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“呈现”的意思是把内容表现出来给别人看。“用有趣的方法来呈现”是为了吸引观众和评判。","讲故事比赛要讲得有趣才能赢，所以（4）最合适。","有趣的方法不一定节省时间；准备运动会不需要“呈现”。答案是（4）。"]}],"options":["为了节省时间","为了准备运动会","为了完成科学作业","为了赢得讲故事比赛"]},{"id":"chinese-2026-prelim-red-swastika-p2-q13","cite":"2026 Prelim Red Swastika Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“胸有成竹”的意思是做事以前心里已经有了主意，很有把握。","（1）小明知道答案，很有把握地举手，用得对。","（4）小华不会做题，没有把握，意思正好相反；（2）（3）煮面、看电视不需要“有把握”。","答案是（1）。"]}],"options":["老师提出一个难题，小明++胸有成竹++地举手回答。","弟弟肚子饿，妈妈++胸有成竹++地煮了一碗面给他。","爸爸工作累了，++胸有成竹++地躺在沙发上看电视。","小华不会做这道题，就++胸有成竹++地坐在那里发呆。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q14","cite":"2026 Prelim Red Swastika Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“充足”的意思是数量很多，足够用。常说“充足的阳光、充足的时间、充足的睡眠”。","（3）形容阳光，用得对。","（1）应该用“重重”，（2）应该用“仔细、认真”，（4）应该用“充实”。","答案是（3）。"]}],"options":["弟弟跑得太快了，结果++充足++地摔在地上。","这道数学题很难，红要++充足++地想一想。","没有++充足++的阳光，植物无法好好地生长。","表哥每天都很++充足++，因为他喜欢学新东西。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q15","cite":"2026 Prelim Red Swastika Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“避免”的意思是想办法不让不好的事情发生，后面常接不好的事：避免发生意外、避免犯错。","（4）小心过马路，不让交通意外发生，用得对。","（3）应该用“避开”了这条路；（2）应该用“躲”在走廊里；（1）“避免”不能加“地”来形容动作。","答案是（4）。"]}],"options":["那个明星不想回答问题，便++避免++地低下了头。","天空突然下起大雨，小华++避免++在走廊里等待。","前方的路发生了交通意外，司机++避免++了这条路。","妈妈提醒我要小心过马路，++避免++发生交通意外。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q16","cite":"2026 Prelim Red Swastika Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["空格后面是“了很多食物”。“准备食物”是正确的搭配。","“选择食物”是挑选，但有钱人是要把食物带去分给村民，所以是先“准备”好。“参加、走向”不能接“食物”。","答案是（1）准备。"]}],"group":"chinese-2026-prelim-red-swastika-g1","options":["准备","选择","参加","走向"]},{"id":"chinese-2026-prelim-red-swastika-p2-q19","cite":"2026 Prelim Red Swastika Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“考虑”的意思是在心里好好想一想。村民要有钱人先想清楚“自己为什么要做这件事情”。","“询问”是问别人，不是问自己；“检查”是查看有没有错。","答案是（4）考虑。"]}],"group":"chinese-2026-prelim-red-swastika-g1","options":["询问","改变","检查","考虑"]},{"id":"chinese-2026-prelim-red-swastika-p2-q21","cite":"2026 Prelim Red Swastika Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual","character-and-feelings"],"format":"mcq","marks":2,"difficulty":1,"stem":"康康一开始来到店门口时，心情是怎样的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看第一段：“他拿着辛苦存的五十元，很兴奋地来到商店门口。”","“着急”是后来挤不到柜台前的心情，不是“一开始来到店门口时”的心情。","答案是（2）兴奋。"]}],"group":"chinese-2026-prelim-red-swastika-g2","options":["难过。","兴奋。","着急。","生气。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q22","cite":"2026 Prelim Red Swastika Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"小女孩为什么拒绝那位妇女的十元？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["看第二段：女孩轻轻摇头说“不用了”，然后“转身回到门口的卖报纸的摊子”。","她不拿别人的奖励，回去继续卖报纸，说明她想靠自己的努力赚钱。","她没有嫌钱少；衣服破旧不是拒绝的原因。答案是（1）。"]}],"group":"chinese-2026-prelim-red-swastika-g2","options":["因为她想要自己赚钱。","因为她自己的衣服破旧。","因为她觉得妇女给的钱少。","因为她听见妇女说谢谢她。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q23","cite":"2026 Prelim Red Swastika Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"康康想起自己小时候家里困难的日子，是因为他____________。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看第三段：“看到这一幕，康康想起自己小时候，家里也曾经非常辛苦。”注意“也”字。","女孩衣服破旧，要卖报纸，生活困难，让康康想到自己家以前“也”很辛苦。","歌声是后来才听到的。答案是（2）。"]}],"group":"chinese-2026-prelim-red-swastika-g2","options":["看见很多人在店里。","看见女孩生活困难。","听见一阵熟悉的歌声。","看见女孩和妇女说话。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q24","cite":"2026 Prelim Red Swastika Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"康康听着，“突然好像明白了什么”，指的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["康康听到的歌词是：“请让我关心你，这世界会变得更美丽”。","他本来不知道要不要帮助小女孩，听了歌以后，明白了应该关心有需要的人，所以握紧五十元向小女孩走去。","答案是（4）。"]}],"group":"chinese-2026-prelim-red-swastika-g2","options":["他应该继续在店里排队。","他应该早点到商店去排队。","他要努力存钱买电子游戏。","他应该关心需要帮助的人。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q25","cite":"2026 Prelim Red Swastika Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"你认为康康最后会做什么？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["最后一句：“他握紧那五十元，望着那个小女孩，慢慢走了过去……”","他明白了要关心别人，又拿着钱走向卖报纸的女孩，所以他会用钱帮助她。女孩不收别人白给的钱，买她的报纸是最好的帮助方法。","他没有走回店里，也没有回家。答案是（3）。"]}],"group":"chinese-2026-prelim-red-swastika-g2","options":["他会把五十元收好转身回家。","他会买喜欢的游戏送给女孩。","他会用钱买下报纸帮助女孩。","他会回去店里继续排队等待。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q26","cite":"2026 Prelim Red Swastika Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"5","accept":["为什么还要和您去跑步","5 为什么还要和您去跑步"]},"explanation":["空格后面是问号，所以要选一个问句。","庆文说“学校已经有体育课了”，意思是他觉得运动已经够了。爸爸回答“当然是要你多运动”，是在回答“为什么”。","所以选 5：为什么还要和您去跑步。"]}],"group":"chinese-2026-prelim-red-swastika-g3"},{"id":"chinese-2026-prelim-red-swastika-p2-q27","cite":"2026 Prelim Red Swastika Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"1","accept":["我身体很好","1 我身体很好"]},"explanation":["爸爸刚说要“保持身体健康”，庆文接着问“还需要去跑步吗？”","他是想说自己已经很健康了，不必跑步。","所以选 1：我身体很好。"]}],"group":"chinese-2026-prelim-red-swastika-g3"},{"id":"chinese-2026-prelim-red-swastika-p2-q28","cite":"2026 Prelim Red Swastika Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"3","accept":["去跑步有许多好处","3 去跑步有许多好处"]},"explanation":["爸爸说“当然需要！”，后面要说出需要的理由。","庆文接着说“我知道。我们不但可以晒晒太阳、呼吸新鲜空气，还可以看看大自然”，这些都是跑步的好处。","所以选 3：去跑步有许多好处。"]}],"group":"chinese-2026-prelim-red-swastika-g3"},{"id":"chinese-2026-prelim-red-swastika-p2-q29","cite":"2026 Prelim Red Swastika Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["跑步后我们还可以一起去吃个早餐","8 跑步后我们还可以一起去吃个早餐"]},"explanation":["庆文刚说了跑步的几个好处（“不但可以……还可以……”），爸爸说“没错”，再接着补充一个好处，也用“还可以”。","6“因为让眼睛休息一会儿”只是半句话，有“因为”却没有结果，放进去句子不完整。","所以选 8：跑步后我们还可以一起去吃个早餐。庆文听了就说“好吧！”"]}],"group":"chinese-2026-prelim-red-swastika-g3"},{"id":"chinese-2026-prelim-red-swastika-p2-q30","cite":"2026 Prelim Red Swastika Paper 2 Question 30","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":30,"topic":"functional-text","subtypes":["purpose-and-audience"],"format":"mcq","marks":2,"difficulty":1,"stem":"举办“智能学习班”的主要目的是什么？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["目的写在广告的第一段：“为了帮助您学会使用智能手机，让生活更便利……帮助您不再害怕使用智能手机。”","（1）和（2）只是其中一个课程的内容，不是整个学习班的主要目的。","答案是（4）。"]}],"group":"chinese-2026-prelim-red-swastika-g4","options":["让老年人常常与亲友保持联系。","让老年人上网看新闻和电视剧。","让老年人向工作人员了解详情。","让老年人不害怕使用智能手机。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q31","cite":"2026 Prelim Red Swastika Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":31,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"想报名参加课程的人应该怎么做？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["广告说：“您可以到康康民众俱乐部的办公室报名”，还说“我们的工作人员将在 5 月 1 日上午为大家现场讲解并填写报名表格”。","所以 5 月 1 日当天到民众俱乐部去，就可以报名。","打电话给王先生只能“了解详情”，不是报名；报名截止日期是 5 月 5 日，5 月 8 日以后已经太迟了。答案是（2）。"]}],"group":"chinese-2026-prelim-red-swastika-g4","options":["在 5 月 1 日之前打电话找王先生。","在 5 月 1 日当天到民众俱乐部去。","在 5 月 8 日之前找家人了解详情。","在 5 月 8 日到 16 日之间报名上课。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q32","cite":"2026 Prelim Red Swastika Paper 2 Question 32","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":32,"topic":"functional-text","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一点是广告的内容？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["课程 3“手机让生活更便利”的内容是“学会网上购物”，就是上网买东西。（3）是对的。","（1）5 月 5 日下午 4 点以前都可以到办公室报名。（2）只有 60 岁或以上的居民可以参加。","（4）一个课程 $25，四个课程是 $100，但是报名所有课程学费打八折，只要 $80。答案是（3）。"]}],"group":"chinese-2026-prelim-red-swastika-g4","options":["5 月 1 日当天才能报名。","欢迎全部居民报名参加。","学会上网买东西的便利。","全部课程学费是一百元。"]},{"id":"chinese-2026-prelim-red-swastika-p2-q33","cite":"2026 Prelim Red Swastika Paper 2 Question 33","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":33,"topic":"functional-text","subtypes":["message-writing"],"format":"structured","marks":4,"difficulty":2,"stem":"假如你是文乐，看到这则广告，想到了外婆也可以学习用自能手机，以后能主动和在国外工作的阿姨上网通话。请写一个短信给外婆，告诉她哪一个课程适合她，以及尽早报名的原因。\n\n短信的开头是：\n外婆，康康民众俱乐部将举办一些智能手机学习课程。为了能让您随时和在国外的阿姨通话，您可以……\n（请接着写下去。）","parts":[{"label":"","answer":{"type":"self","value":"外婆，康康民众俱乐部将举办一些智能手机学习课程。为了能让您随时和在国外的阿姨通话，您可以报名课程 2“通过网络与亲友见面”，因为这个课程能让您学习使用智能手机跟在国外的阿姨上网通话。请尽早报名，因为首 20 名报名者可获一个精美的手机支架。"},"explanation":["一共 4 分，内容和语文都要顾到。","内容第一点（哪一个课程适合外婆）：外婆想和在国外的阿姨上网通话。看四个课程，课程 2“通过网络与亲友见面”是学会上网、和亲友保持联系，最适合。课程的号码或名称要写清楚。","内容第二点（尽早报名的原因）：在广告下面找——“首 20 位报名者可得到一个精美的手机支架”。","“学费打八折”不用写，因为那是报名所有课程才有的，和“尽早”没有关系。","语文：接着“您可以……”写下去，对外婆要用“您”，句子要通顺、完整，不要写错字。"]}],"group":"chinese-2026-prelim-red-swastika-g4"},{"id":"chinese-2026-prelim-red-swastika-p2-q34","cite":"2026 Prelim Red Swastika Paper 2 Question 34","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":34,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中形容“对一件事情突然明白过来”的词语是：______。","parts":[{"label":"","answer":{"type":"text","value":"恍然大悟"},"explanation":["要找一个意思是“一下子明白了”的词语。","第二段：林老师解释王乐弄伤了脚以后，“大家听了恍然大悟”。","答案是“恍然大悟”。"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-red-swastika-p2-q36","cite":"2026 Prelim Red Swastika Paper 2 Question 36","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":36,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"比赛当天，什么事让队员们感到不高兴？","parts":[{"label":"","answer":{"type":"self","value":"比赛当天是决赛，可是最厉害的队员王乐没来参加比赛，队员们担心没有他就打不败对手，会输掉比赛。","accept":["王乐身体不舒服，不能参加比赛，队员们担心少了他会输给强劲的对手。"]},"explanation":["答案在第一段和第二段。","要写出三点：（一）最厉害的队员王乐没有来；（二）当天是决赛；（三）大家担心没有他会输（“看来是输定了”）。","大华“皱着眉头”、队友“开始抱怨”，都说明大家不高兴。"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-red-swastika-p2-q37","cite":"2026 Prelim Red Swastika Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":37,"topic":"comprehension-open","subtypes":["vocabulary-in-context","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"林老师说“今天这个机会，我想让他试一试”。","parts":[{"label":"a","prompt":"这句话里的“机会”指的是什么？","marks":1,"answer":{"type":"self","value":"“机会”指让小杰代替王乐上场比赛。"},"explanation":["王乐受伤不能来，球队需要一个人代替他。","林老师说“让他试一试”，“他”是小杰，所以“机会”就是代替王乐上场参加决赛的机会。"]},{"label":"b","prompt":"为什么林老师要这样做？","marks":3,"answer":{"type":"self","value":"因为小杰平时训练最认真，每天最早到球场练习投篮，却很少有比赛机会，所以林老师想让他试一试。"},"explanation":["答案在第三段和第四段。","要写出三点：（一）小杰平时训练最认真／一直很努力；（二）他每天最早到球场练习投篮；（三）但是他比赛的机会很少。","林老师自己也说了：“小杰一直很努力”。"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-red-swastika-p2-q38","cite":"2026 Prelim Red Swastika Paper 2 Question 38","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":38,"topic":"comprehension-open","subtypes":["character-and-feelings","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"听了子文说的话，大华的看法有什么改变？什么原因使大华改变？","parts":[{"label":"","answer":{"type":"self","value":"大华起初反对小杰上场，后来同意让他上场，还鼓励他。因为大华想起自己刚加入篮球队时，情况也和小杰一样。","accept":["大华起初反对小杰上场，后来同意让他上场；因为他想起自己刚加入篮球队时，也是从代替别人比赛开始的。"]},"explanation":["题目有两问，都要回答。","改变：第四段大华说“他从来没有和我们一起比赛，怎么能打得好？”，是反对；第五段他拍拍小杰的肩膀说“今天看你的了！”，是支持。要写出“从反对到同意（支持）”。","原因：第五段第一句——“大华想起自己刚加入篮球队时，情况也和小杰一样。”"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-red-swastika-p2-q39","cite":"2026 Prelim Red Swastika Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":39,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":4,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"以前，大家没有让小杰上场比赛的原因是什么？","marks":2,"answer":{"type":"self","value":"因为大家认为小杰个子不高，而且他从来没有和他们一起比赛，担心他打不好。"},"explanation":["第三段：小杰“比赛机会很少，因为他个子不高”。","第四段大华的话：“他从来没有和我们一起比赛，怎么能打得好？”","两个原因都要写。"]},{"label":"b","prompt":"小杰怎么样在这场比赛中改变大家对他的印象？","marks":2,"answer":{"type":"self","value":"比赛中，小杰很努力。对方投篮不中时，他高高跳起，抢到了球还传给队员，为队伍取得几次得分的机会。","accept":["比赛中，小杰努力抢球、把球传给队友，为球队创造得分机会，因而改变了大家对他的印象。"]},"explanation":["答案在第六段。","要写出小杰做了什么：高高跳起抢到球、把球传给队员、为队伍取得得分的机会。","大华最后抱住他说“你抢球的动作太帅了！”，说明大家对他的印象改变了。"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-red-swastika-p2-q40","cite":"2026 Prelim Red Swastika Paper 2 Question 40","year":2026,"exam":"Prelim","school":"Red Swastika","section":"p2","number":40,"topic":"comprehension-open","subtypes":["opinion","character-and-feelings"],"format":"structured","marks":4,"difficulty":2,"stem":"你觉得子文是一个怎样的队长？请举例说明。","parts":[{"label":"","answer":{"type":"self","value":"我觉得子文是一个细心、有主见，并且信任和鼓励队友的队长。他注意到小杰平时训练认真，主动向林老师推荐小杰代替王乐；面对大华的反对时，他仍说明小杰的努力，并劝大家相信小杰。"},"explanation":["先说看法，再举例子。用“我觉得子文是一个……的队长。”开头。","看法可以是：细心、公平、有主见、信任队友、懂得鼓励队友、重视团队精神。","例子要从短文里找：（一）他留意到小杰平时训练最认真，就向林老师提出建议（第三段）；（二）大华反对时，他说“队友之间要互相支持……我们应该相信他”（第四段）。","只写“子文是好队长”，没有例子，是拿不到满分的。"]}],"group":"chinese-2026-prelim-red-swastika-g5"},{"id":"chinese-2026-prelim-tao-nan-p2-q1","cite":"2026 Prelim Tao Nan Paper 2 Question 1","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":1,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n兔子看见老虎，++迅速++地跑进树林里。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“迅”的声母是 x，读 xùn，不是翘舌音 shùn。","“速”是平舌音 sù，不是翘舌音 shù。","“迅速”读 xùn sù，答案是（1）。"]}],"options":["xùn sù","xùn shù","shùn sù","shùn shù"]},{"id":"chinese-2026-prelim-tao-nan-p2-q2","cite":"2026 Prelim Tao Nan Paper 2 Question 2","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":2,"topic":"pinyin","subtypes":["pinyin"],"format":"mcq","marks":2,"difficulty":1,"stem":"请选出画线词语的汉语拼音。\n小云的舞蹈表演非常++精彩++，同学们看了都拍手叫好。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“精”是后鼻音 jīng，不是前鼻音 jīn。","“彩”是平舌音，读第三声 cǎi，不是翘舌音 chǎi。","“精彩”读 jīng cǎi，答案是（3）。"]}],"options":["jīn cái","jīn chái","jīng cǎi","jīng chǎi"]},{"id":"chinese-2026-prelim-tao-nan-p2-q3","cite":"2026 Prelim Tao Nan Paper 2 Question 3","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":3,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n昨晚发生的地______，并没有对村民造成严重伤害。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“地震”是地面突然震动的自然灾害，可能会让人受伤，所以句子说“并没有造成严重伤害”。","“雷、雾、露”都是雨字头，样子很像，但是“地雷、地雾、地露”放在句子里都说不通。","答案是（1）震。"]}],"options":["震","雷","雾","露"]},{"id":"chinese-2026-prelim-tao-nan-p2-q4","cite":"2026 Prelim Tao Nan Paper 2 Question 4","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":4,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n老师看到同学们争先恐后地上校车，便上前维持______序。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“秩序”的意思是有条理、不混乱的情况。“维持秩序”是固定搭配。","“智、质、志”读音和“秩”一样，但是不能和“序”组成词语。","答案是（4）秩。"]}],"options":["智","质","志","秩"]},{"id":"chinese-2026-prelim-tao-nan-p2-q5","cite":"2026 Prelim Tao Nan Paper 2 Question 5","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":5,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n听了外婆______的那段往事，我不禁流下了眼泪。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“讲述”的意思是把事情或道理讲出来。“讲述往事”是正确的搭配。","“介绍”用在人或事物上（介绍朋友、介绍新书），不说“介绍往事”；“吩咐”是叫别人做事；“讨论”要几个人一起谈。","答案是（2）讲述。"]}],"options":["介绍","讲述","吩咐","讨论"]},{"id":"chinese-2026-prelim-tao-nan-p2-q6","cite":"2026 Prelim Tao Nan Paper 2 Question 6","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":6,"topic":"vocabulary","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n丽美在科学课上______虫子的特点，并把自己的发现写下来。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“观察”的意思是仔细地看。要知道虫子的特点，就要仔细地看它，然后才有“发现”。","“检查”是为了找出问题或毛病（检查作业、检查身体），不是为了找特点。","答案是（4）观察。"]}],"options":["测试","检查","考虑","观察"]},{"id":"chinese-2026-prelim-tao-nan-p2-q7","cite":"2026 Prelim Tao Nan Paper 2 Question 7","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":7,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n看到家伟获得第一名，我心里有些++妒忌++。","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“妒忌”的意思是看到别人比自己好，心里不舒服，甚至怨恨他。","家伟获得第一名，是他比“我”好，不是他表现差，也不是他犯错，所以（2）（3）不对。","（1）只是自己难过，没有对别人不满的意思。答案是（4）。"]}],"options":["因自己不如别人而难过","因别人表现差而讨厌他","因他人犯错而感到不满","因对方比自己好而恨他"]},{"id":"chinese-2026-prelim-tao-nan-p2-q8","cite":"2026 Prelim Tao Nan Paper 2 Question 8","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":8,"topic":"vocabulary","subtypes":["word-meaning"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n奶奶总是++唠叨++，要我尽快完成作业。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“唠叨”的意思是说话啰唆，同样的话说个不停。","句子里有“总是”，说明奶奶一次又一次地说，就是“没完没了地说”。","“吞吞吐吐”是有话不敢直说，意思不对。答案是（3）。"]}],"options":["不慌不忙地说","认认真真地说","没完没了地说","吞吞吐吐地说"]},{"id":"chinese-2026-prelim-tao-nan-p2-q9","cite":"2026 Prelim Tao Nan Paper 2 Question 9","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":9,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n运动______能锻炼身体，______能放松心情。","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["句子说运动有两个好处：锻炼身体和放松心情。第二个好处是加上去的，用“除了……也……”。","“只有……才……”表示条件，“不管……都……”表示什么情况都一样，“要是……就……”表示假设，放进去都说不通。","答案是（1）除了……也。"]}],"options":["除了……也","只有……才","不管……都","要是……就"]},{"id":"chinese-2026-prelim-tao-nan-p2-q10","cite":"2026 Prelim Tao Nan Paper 2 Question 10","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":10,"topic":"sentences","subtypes":["connectors"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n______大家互相合作，______活动进行得很顺利。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["“大家互相合作”是原因，“活动进行得很顺利”是结果，要用表示因果的“因为……所以……”。","“尽管……还是……”表示转折，可是合作和顺利并不相反。","答案是（3）因为……所以。"]}],"options":["不仅……而且","一边……一边","因为……所以","尽管……还是"]},{"id":"chinese-2026-prelim-tao-nan-p2-q11","cite":"2026 Prelim Tao Nan Paper 2 Question 11","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":11,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n小文听到这个坏消息，____________。","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["听到“坏消息”，人会马上变得不开心，所以“脸上的笑容消失了”最合理。","（1）（3）（4）和听到坏消息没有直接的关系，句子里也没有提到食堂、童年或“那些同学”。","答案是（2）。"]}],"options":["立刻冲去食堂","脸上的笑容消失了","想起了自己难忘的童年","希望那些同学会被老师批评"]},{"id":"chinese-2026-prelim-tao-nan-p2-q12","cite":"2026 Prelim Tao Nan Paper 2 Question 12","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":12,"topic":"sentences","subtypes":["sentence-completion"],"format":"mcq","marks":2,"difficulty":1,"stem":"从所提供的选项中选出正确的答案。\n____________，今天感到十分疲倦。","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["后半句是结果：今天十分疲倦。前半句要说出疲倦的原因。","“连续几晚没有睡好”，所以今天很累，前后意思连得上。","（1）是以后的打算，不是今天疲倦的原因；睡前喝牛奶会睡得更好。答案是（3）。"]}],"options":["乐乐打算以后早睡早起","乐乐睡醒后去公园跑步","乐乐连续几晚没有睡好","乐乐睡前喝了一杯牛奶"]},{"id":"chinese-2026-prelim-tao-nan-p2-q13","cite":"2026 Prelim Tao Nan Paper 2 Question 13","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":13,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["“促进”的意思是推动事情向好的方面发展，常说“促进感情、促进交流、促进发展”。","（4）“促进同学之间的感情”用得对。","（1）应该用“为了”或“关心”，（2）应该用“促销”，（3）应该用“引进”或“推荐”。","答案是（4）。"]}],"options":["妈妈++促进++我的健康，要我每天早睡早起。","超市在++促进++期间，所有的物品都打八折。","图书馆++促进++的儿童故事书，小朋友们都很喜欢。","为了++促进++同学之间的感情，老师鼓励大家多交流。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q14","cite":"2026 Prelim Tao Nan Paper 2 Question 14","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":14,"topic":"sentences","subtypes":["sentence-usage"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["“丰富”的意思是种类多、数量大，常说“营养丰富、内容丰富、经验丰富”。","（1）“营养丰富”用得对。","（2）（3）应该用“充足”（充足的睡眠、光线充足），（4）应该用“充实”（日子过得很充实）。","答案是（1）。"]}],"options":["这道汤营养++丰富++，我们全家人都爱喝。","孩子们要有++丰富++的睡眠，才有精神上课。","爸爸劝告哥哥，一定要在光线++丰富++的地方看书。","陈伯伯每个周末都会去做义工，日子过得很++丰富++。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q15","cite":"2026 Prelim Tao Nan Paper 2 Question 15","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":15,"topic":"sentences","subtypes":["sentence-usage","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是正确的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["“恍然大悟”的意思是一下子明白过来。前面要有让人明白的原因。","（2）听了解释以后一下子明白了，用得对。","（1）应该用“踊跃”或“纷纷”，（3）应该用“来不及”，（4）应该用“兴高采烈”或“异口同声”。","答案是（2）。"]}],"options":["小组活动时，同学们++恍然大悟++地提出自己的意见。","听了林阿姨的解释后，明华和欢欢顿时++恍然大悟++。","事情都已经发生了，你现在才后悔已经++恍然大悟++了。","姐姐提议去海边野餐，我和妹妹++恍然大悟++地表示赞同。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q16","cite":"2026 Prelim Tao Nan Paper 2 Question 16","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":16,"topic":"cloze","subtypes":["word-choice","idioms"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q16 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["康康怎么折都不成功，“不耐烦地把纸弄成一团”，说明他心情不好。","“闷闷不乐”的意思是心里不高兴。他不高兴地坐在一旁。","“胸有成竹”是做事以前已经很有把握，和他不成功的情况相反。答案是（1）闷闷不乐。"]}],"group":"chinese-2026-prelim-tao-nan-g1","options":["闷闷不乐","津津有味","左思右想","胸有成竹"]},{"id":"chinese-2026-prelim-tao-nan-p2-q17","cite":"2026 Prelim Tao Nan Paper 2 Question 17","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":17,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q17 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["老师说“你再试一次吧？”，康康“摇了摇头”。摇头表示不要、不肯。","“拒绝”的意思是不接受别人的要求或建议。","“失望”是心情，但摇头是对老师的建议作出回答，所以用“拒绝”。答案是（2）拒绝。"]}],"group":"chinese-2026-prelim-tao-nan-g1","options":["失望","拒绝","怀疑","担心"]},{"id":"chinese-2026-prelim-tao-nan-p2-q18","cite":"2026 Prelim Tao Nan Paper 2 Question 18","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":18,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q18 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["空格后面是“老师的方法，一步一步地折”。“按照……的方法”是固定搭配，意思是跟着这个方法去做。","“遵守”用在规则、纪律上（遵守校规），不说“遵守方法”。","答案是（3）按照。"]}],"group":"chinese-2026-prelim-tao-nan-g1","options":["请求","计划","按照","遵守"]},{"id":"chinese-2026-prelim-tao-nan-p2-q19","cite":"2026 Prelim Tao Nan Paper 2 Question 19","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":19,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q19 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["后面说“一次、两次……渐渐地”，说明他试了很多很多次，没有停下来。","“不断”的意思是一直不停。“开始不断尝试”说得通。","“继续”是接着做原来的事，前面已经有“开始”，“开始继续”说不通。答案是（4）不断。"]}],"group":"chinese-2026-prelim-tao-nan-g1","options":["继续","接着","连忙","不断"]},{"id":"chinese-2026-prelim-tao-nan-p2-q20","cite":"2026 Prelim Tao Nan Paper 2 Question 20","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":20,"topic":"cloze","subtypes":["word-choice"],"format":"mcq","marks":2,"difficulty":1,"stem":"Q20 的答案是：","parts":[{"label":"","answer":{"type":"mcq","value":1},"explanation":["后面一句说：每当遇到困难，他都会对自己说“再试一次”。这就是不放弃。","“不再轻易放弃”的意思是不会很容易就停下来不做。","“解决、改变”后面要有东西（解决问题、改变方法），不能单独放在这里。答案是（1）放弃。"]}],"group":"chinese-2026-prelim-tao-nan-g1","options":["放弃","对抗","解决","改变"]},{"id":"chinese-2026-prelim-tao-nan-p2-q21","cite":"2026 Prelim Tao Nan Paper 2 Question 21","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":21,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"作者在什么情况下会更积极地打篮球？","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["找到第一段第二句：“每当听到从观众席上传来掌声和欢呼声，我就会特别兴奋，便更积极地传球、投篮。”","“每当……就……”告诉我们是在听到掌声和欢呼声的时候。","在球场上奔跑是他喜欢的感觉，不是让他更积极的原因。答案是（4）。"]}],"group":"chinese-2026-prelim-tao-nan-g2","options":["他传球成功时。","他在赛场上奔跑时。","他看到队友投篮得分时。","他听到观众的掌声和欢呼声时。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q22","cite":"2026 Prelim Tao Nan Paper 2 Question 22","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":22,"topic":"comprehension-mcq","subtypes":["inference","cause-and-effect"],"format":"mcq","marks":2,"difficulty":1,"stem":"作者的球队进场时，观众席上为什么静悄悄的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["第二段说：观众“没有人起身欢迎我们”，“看着我们，却好像什么也没看见似的”。","可是另一支球队入场时，所有观众都站起来鼓掌。两种态度一比，就知道观众支持的是另一队，不欢迎作者的球队。","差点迟到的是另一支球队；观众是“看着我们”的，不是没看到。答案是（2）。"]}],"group":"chinese-2026-prelim-tao-nan-g2","options":["因为作者和队员迟到了。","因为观众不欢迎这一支球队。","因为观众觉得比赛还没有开始。","因为大家没看到作者的球队入场。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q23","cite":"2026 Prelim Tao Nan Paper 2 Question 23","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":23,"topic":"comprehension-mcq","subtypes":["factual"],"format":"mcq","marks":2,"difficulty":1,"stem":"从哪里可以看出观众的反应影响了作者的表现？","parts":[{"label":"","answer":{"type":"mcq","value":3},"explanation":["第三段说：“连我平时最厉害的投篮也一次又一次地失败。”这就是投篮一直没有进球。","作者是“没接住”队友传来的球，不是不愿意传球；“沉默”是中场休息时回答教练以前的事。","他只是上半场打得不好，下半场打得很好，所以不是“整场”。答案是（3）。"]}],"group":"chinese-2026-prelim-tao-nan-g2","options":["作者在比赛中特别沉默。","作者不愿意传球给队友。","作者投篮一直没有进球。","作者整场比赛都没打好。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q24","cite":"2026 Prelim Tao Nan Paper 2 Question 24","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":24,"topic":"comprehension-mcq","subtypes":["factual","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"以下哪一个句子是**不正确**的？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["注意题目问的是“不正确”的句子。","教练说：“观众可以不支持你，但是他们不能阻止你获得冠军！”所以（2）和短文的意思相反。","（1）投篮是作者“平时最厉害的”；（3）第三段第一句；（4）教练说“能得到观众的掌声是一件好事”。这三句都是对的。答案是（2）。"]}],"group":"chinese-2026-prelim-tao-nan-g2","options":["作者平时投篮常常进球。","观众能阻止球员获得冠军。","观众对两支球队的态度完全不同。","教练认为能得到观众的掌声是好事。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q25","cite":"2026 Prelim Tao Nan Paper 2 Question 25","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":25,"topic":"comprehension-mcq","subtypes":["main-idea"],"format":"mcq","marks":2,"difficulty":1,"stem":"通过这次比赛，作者明白了______","parts":[{"label":"","answer":{"type":"mcq","value":4},"explanation":["教练告诉作者：没有掌声也不应该受到影响，观众不能阻止你获得冠军。","下半场作者“只想着打好篮球，完全不管周围发生了什么事”，结果赢了比赛。","所以他明白的道理是：要专心做好自己的事，不受别人影响。“神奇的魔力”只是形容教练的话很有用。答案是（4）。"]}],"group":"chinese-2026-prelim-tao-nan-g2","options":["与他人合作最重要。","打篮球需要一位好教练。","篮球教练需要有神奇的魔力。","要获得冠军就不能受他人影响。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q26","cite":"2026 Prelim Tao Nan Paper 2 Question 26","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":26,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q26 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"6","accept":["我的手机必须交给父母保管","6 我的手机必须交给父母保管"]},"explanation":["美芳说回家后不能发短信，空格要说出原因；后面是“只有晚餐后才能使用一个小时”。","后来文丽问“你的父母什么时候才会让你自己保管手机呢？”，说明美芳说过手机是由父母保管的。","所以选 6：我的手机必须交给父母保管。（5 的意思也接近，但 5 要留给 Q27。）"]}],"group":"chinese-2026-prelim-tao-nan-g3"},{"id":"chinese-2026-prelim-tao-nan-p2-q27","cite":"2026 Prelim Tao Nan Paper 2 Question 27","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":27,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q27 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"5","accept":["在家不能随时使用手机","5 在家不能随时使用手机"]},"explanation":["这句是文丽说的。她听了美芳的话，觉得“这样也太不方便了”。","“这样”指的是美芳的情况：在家不能想用手机就用手机。","所以选 5：在家不能随时使用手机。（6“我的手机必须交给父母保管”不是文丽的情况，她的父母从来不管。）"]}],"group":"chinese-2026-prelim-tao-nan-g3"},{"id":"chinese-2026-prelim-tao-nan-p2-q28","cite":"2026 Prelim Tao Nan Paper 2 Question 28","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":28,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q28 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"2","accept":["我在家过得很充实","2 我在家过得很充实"]},"explanation":["文丽问“不能用手机的时候不会很闷吗？”，美芳回答“怎么会呢？”，意思是不会闷。","空格后面说她常常阅读故事书、弹钢琴，还和妹妹一起玩，说明她在家有很多事情做。","所以选 2：我在家过得很充实。"]}],"group":"chinese-2026-prelim-tao-nan-g3"},{"id":"chinese-2026-prelim-tao-nan-p2-q29","cite":"2026 Prelim Tao Nan Paper 2 Question 29","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":29,"topic":"dialogue","subtypes":["dialogue-completion"],"format":"short","marks":2,"difficulty":2,"stem":"Q29 的答案是：（填写数字 1 到 8）","parts":[{"label":"","answer":{"type":"text","value":"8","accept":["花太多时间在手机上不但容易分心","8 花太多时间在手机上不但容易分心"]},"explanation":["空格后面是“而且会影响视力”。“而且”前面要有“不但”。","八个选项里只有 8 有“不但”，说的也是用手机太久的坏处。","所以选 8：花太多时间在手机上不但容易分心。"]}],"group":"chinese-2026-prelim-tao-nan-g3"},{"id":"chinese-2026-prelim-tao-nan-p2-q31","cite":"2026 Prelim Tao Nan Paper 2 Question 31","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":31,"topic":"functional-text","subtypes":["factual","inference"],"format":"mcq","marks":2,"difficulty":1,"stem":"居民应该怎么做才能得到马年娃娃？","parts":[{"label":"","answer":{"type":"mcq","value":2},"explanation":["看通告里星形图案里的字：“每日前 50 名到场的民众可免费领取马年娃娃！”","只有最早到的 50 个人才有，所以要提早到欢乐民众俱乐部广场。","上网和拨电给林小姐是为了知道更多详情；张大伟老师是写春联的。答案是（2）。"]}],"group":"chinese-2026-prelim-tao-nan-g4","options":["上网报名。","提早到达广场。","拨电给林小姐。","去现场找张大伟老师。"]},{"id":"chinese-2026-prelim-tao-nan-p2-q35","cite":"2026 Prelim Tao Nan Paper 2 Question 35","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":35,"topic":"comprehension-open","subtypes":["vocabulary-in-context"],"format":"short","marks":2,"difficulty":2,"stem":"文中形容“用言语表示感谢”的词语是______。","parts":[{"label":"","answer":{"type":"text","value":"道谢"},"explanation":["要找一个意思是“说谢谢”的词语。","第四段：她“连声向林爷爷道谢”。","答案是“道谢”。"]}],"group":"chinese-2026-prelim-tao-nan-g5"},{"id":"chinese-2026-prelim-tao-nan-p2-q37","cite":"2026 Prelim Tao Nan Paper 2 Question 37","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":37,"topic":"comprehension-open","subtypes":["factual","cause-and-effect"],"format":"structured","marks":3,"difficulty":2,"stem":"","parts":[{"label":"a","prompt":"家乐一开始对林爷爷的工作有什么看法？","marks":1,"answer":{"type":"self","value":"家乐觉得林爷爷在做一件没意义的事。"},"explanation":["答案在第二段：“家乐总觉得他在做一件没意义的事。”","回答时要把“他”换成“林爷爷”，说清楚是谁。指代不清楚会被扣分。"]},{"label":"b","prompt":"他会这么认为的原因是什么？","marks":2,"answer":{"type":"self","value":"家乐认为林爷爷花那么多时间修旧雨伞，赚得又不多，是不值得的。"},"explanation":["原因在家乐问林爷爷的话里：“您花这么多时间修这些旧雨伞，赚得又不多，值得吗？”","要写出两点：花很多时间修旧雨伞；赚得又不多。所以他认为不值得。","不能照抄家乐说的话，要用自己的话转述：把“您”改成“林爷爷”，把问句改成“是不值得的”。没有转述会被扣分。"]}],"group":"chinese-2026-prelim-tao-nan-g5"},{"id":"chinese-2026-prelim-tao-nan-p2-q39","cite":"2026 Prelim Tao Nan Paper 2 Question 39","year":2026,"exam":"Prelim","school":"Tao Nan","section":"p2","number":39,"topic":"comprehension-open","subtypes":["inference","character-and-feelings"],"format":"structured","marks":4,"difficulty":2,"stem":"“家乐听了，脸上一阵阵发烫”这句话说明了什么？","parts":[{"label":"","answer":{"type":"self","value":"这说明了家乐知道自己错了，感到很惭愧。他原本以为这把伞只是没用的“废物”，但原来林爷爷修好的不只是一把雨伞，更是妇女对爸爸的回忆。","accept":["这说明了家乐感到很惭愧。他原本以为这把伞只是没用的“废物”，但原来林爷爷修好的不只是一把雨伞，更是妇女对爸爸的回忆。"]},"explanation":["“脸上发烫”是不好意思、惭愧的时候才会有的感觉。先写出家乐的感受：知道自己错了／很惭愧／很内疚／不好意思／难为情。","再写出他为什么惭愧，答案在最后一段。","他原本的想法：以为这把伞只是没用的“废物”。","他现在明白的事：林爷爷修好的不只是一把雨伞，更是那位妇女对爸爸的回忆。"]}],"group":"chinese-2026-prelim-tao-nan-g5"}],"groups":{"chinese-2026-prelim-acsj-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-acsj-g1-img1","alt":"短文：伟强喜欢制作模型，他不怕失败，认真准备，在学校的模型制作比赛中获得冠军。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-acsj-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-acsj-g2-img1","alt":"短文：明华放学后在操场踢球时捡到一个钱包，本来想把钱拿去买玩具，后来看到丢钱包的小男生哭得很伤心，就把钱包还给了他。"}]},"chinese-2026-prelim-acsj-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-acsj-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句。下面是叶明和洋洋谈假期计划的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-acsj-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-acsj-g4-img1","alt":"通告：欢乐民众俱乐部的儿童节庆祝会，有欢乐运动会、变废为宝、小画家、探险家四个活动的内容、时间和注意事项，还有报名方法。"}]},"chinese-2026-prelim-acsj-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-acsj-g5-img1","alt":"短文：六年级甲班有同学的东西不见了，李明和丽华怀疑新同学小安。班长文文发现原来是小鸟把东西叼到了鸟窝里。"}]},"chinese-2026-prelim-ai-tong-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-ai-tong-g1-img1","alt":"短文：文华七岁开始学写毛笔字，在妈妈的鼓励下越写越好，十岁时在书法比赛中得了一等奖，妈妈要他继续争取更大的进步。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-ai-tong-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-ai-tong-g2-img1","alt":"短文：志明常把自己不要的旧东西当生日礼物送给同学。他生日时，妈妈送他一个旧书包，让他明白送礼物要考虑别人是否喜欢、是否需要。"}]},"chinese-2026-prelim-ai-tong-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-ai-tong-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 鱼丸面的队伍太长；2 我借了图书馆的书；3 为什么不去课室里找；4 连书的影子都没有看到；5 妈妈帮我找到了那本书；6 或者会不会是在课室里；7 你去失物招领处看一看；8 我要不要去找老师承认错误。下面是乐文和小丽谈找不到图书馆的书的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-ai-tong-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-ai-tong-g4-img1","alt":"广告：欢乐家庭节。今年的主题是“加倍幸福，由我开始”。7 月 1 日在滨海艺术中心举行开幕典礼，有亲子互动游戏（上午十点到十一点）和体育健身活动（下午两点到三点）。7 月 2 日至 31 日全岛多个民众俱乐部举办各种活动，可上民众俱乐部网站或拨打热线电话了解详情。"}]},"chinese-2026-prelim-ai-tong-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-ai-tong-g5-img1","alt":"短文：明华是学校足球队的队员，总爱迟到。教练警告他以后，他七点半赶到集合地点，教练却告诉他真正的准时是要提前做好准备。"}]},"chinese-2026-prelim-chij-st-nicholas-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-g1-img1","alt":"短文：小云跟奶奶学种花，前两次因为种得太深和太心急而失败，第三次才成功，明白了做事要用对方法、努力付出并耐心等待。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-chij-st-nicholas-g2":{"text":"根据短文的内容和上下文的意思，选出最适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-g2-img1","alt":"短文：马丽去医院面试的路上救了一名昏倒的女孩，错过了面试。院长知道后请她再来面试，并让她成为医院的医生。"}]},"chinese-2026-prelim-chij-st-nicholas-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在括号里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-g3-img1","alt":"上面的格子是编号 1 到 9 的九个短语或短句（第 9 句的最后一个字在扫描中被切掉了一部分：“希望收到文具的同学能好好珍惜这些”）。下面是伟明和小丽谈学校“大手牵小手”献爱心活动的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-chij-st-nicholas-g4":{"text":"根据短文和上下文的意思，回答下列问题。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-g4-img1","alt":"海报：武术班招生啦！介绍武术俱乐部两个月的武术课程，有日期、地点、初级班和高级班的招生对象、上课时间和学费，前 10 位报名者可获赠小礼物，还有报名网站和询问电话。"}]},"chinese-2026-prelim-chij-st-nicholas-g5":{"text":"根据短文和上下文的意思，回答下列问题。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-chij-st-nicholas-g5-img1","alt":"短文：杰克在学校成绩不好，母亲鼓励他，发现他对设计有兴趣后让他去上设计课。多年后杰克成为出色的设计师，实现了梦想。"}]},"chinese-2026-prelim-henry-park-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-henry-park-g1-img1","alt":"短文：“我”从小挑食，体能比同学差。妈妈改变了家里的饮食安排，“我”也开始晨跑、参加羽毛球队、早睡，半年后变得更健康。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-henry-park-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-henry-park-g2-img1","alt":"短文：班上养了小仓鼠球球，同学们太“热情”吓到了它。“我”打开箱子想让球球出来跑，结果球球躲进书架底下。老师没有骂“我”，还教“我”什么是真正的爱。"}]},"chinese-2026-prelim-henry-park-g3":{"text":"根据上下文的意思，从表中选出最适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-henry-park-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 也可以减少争吵，2 这里的环境恶劣，3 我们需要团结起来，4 我们可以主动打招呼，5 并且积极地和邻居交流，6 最近邻居们都互不来往，7 珍惜这美好的居住环境，8 还能认识住在周围的邻居。下面是王阿姨和小李谈邻居关系的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-henry-park-g4":{"text":"根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-henry-park-g4-img1","alt":"通告：爱心领养中心举办“给它一个家，给你一份爱”领养活动，写明活动时间、贴心配套（给领养者的优待）、注意事项和领养方法。"}]},"chinese-2026-prelim-henry-park-g5":{"text":"根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-henry-park-g5-img1","alt":"短文：小兔子欢欢不喜欢总要她重写作业的新老师山羊先生。山羊先生告诉她自己小时候的事，还送她一本旧字典，欢欢终于明白老师严格是为了让她成长。"}]},"chinese-2026-prelim-nan-hua-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-g1-img1","alt":"短文：小兔想学画画，开始总是画不好，兔妈妈鼓励它相信自己、多练习，后来小兔在学校的画画比赛中获得冠军。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-nan-hua-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-g2-img1","alt":"短文：林爷爷小时候家里穷，不能学钢琴。六十岁时他被钢琴老师拒绝，就自己买钢琴每天练习，几年后参加钢琴比赛，得到一位著名钢琴家的称赞。"}]},"chinese-2026-prelim-nan-hua-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句。下面是小华和哥哥谈地铁上有人乱丢垃圾的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-nan-hua-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-g4-img1","alt":"海报：“屋顶农场等你来！”介绍在屋顶种菜的好处，以及“屋顶种菜的秘密”讲座的日期、时间、地点、主讲人、活动内容和报名方法。"}]},"chinese-2026-prelim-nan-hua-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nan-hua-g5-img1","alt":"短文：外婆带着“我们”种花生，花生成熟后全家人一边喝花生汤一边谈花生的好处，外婆教“我们”要像花生一样默默付出，做对别人有帮助的人。"}]},"chinese-2026-prelim-nanyang-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-g1-img1","alt":"短文：“我”帮弟弟去旧书店买书，书店老板态度很差。一位中学生被老板冷漠对待却仍然保持笑容，他说不要让别人的态度影响自己的心情，“我”从此以他为榜样。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-nanyang-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-g2-img1","alt":"短文：杰西刚搬进新家，以为隔壁穿旧衣服的两个小男孩家里很穷。停电的晚上男孩来敲门问她有没有手电筒，她以为他们来借东西，就说没有；原来男孩是怕她害怕，来送手电筒给她的。"}]},"chinese-2026-prelim-nanyang-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 厕所的水管又滴水了；2 而且不是每层楼都停；3 这对老人来说很便利；4 这座组屋已经三十年了；5 对我那行动不便的爷爷来说；6 因为现在买车的人越来越多；7 因此大家都需要每天搭乘电梯；8 这样更方便小孩子们在楼下玩耍了。下面是志光和美如谈组屋翻新的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-nanyang-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-g4-img1","alt":"通告：创意机器人协会举办“机器人欢乐展”，有展览的日期、时间、地点、票价，10 月 3 号的四个现场体验活动（机器人对战、机器人推盒子、机器人抓小球、动手组装机器人），还有购票方法、询问电话和儿童节礼物的说明。"}]},"chinese-2026-prelim-nanyang-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-nanyang-g5-img1","alt":"短文：“我”（陈小允）本来不喜欢上华文课。爸爸说全家要移民美国，以后学不了华文，“我”才开始努力学习，听写得了满分。离别那天，张老师送“我”一套中学华文课本，鼓励“我”不要忘记母语。"}]},"chinese-2026-prelim-plmgs-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-plmgs-g1-img1","alt":"短文：志明做事不认真，妈妈让他去书店领取弟弟订的练习本，他拿错了练习本还忘了付钱，被妈妈骂了一顿，后来做事变得认真了。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-plmgs-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-plmgs-g2-img1","alt":"短文：一对夫妇外出时让狗守护五岁的儿子。他们回家看到满地血迹，孩子不见了，男主人以为狗伤了孩子，把狗打出家门。后来才知道是狗赶走了小偷，保护了孩子。"}]},"chinese-2026-prelim-plmgs-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-plmgs-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 你现在有空吗，2 烦恼怎么解决，3 发生了什么事，4 看我能不能帮忙，5 不要听别人的意见，6 实在很难做出决定，7 他们知道了又怎么样，8 让他们知道你的想法。下面是小乐和欢欢的对话，小乐烦恼要不要跟父母搬到国外，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-plmgs-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-plmgs-g4-img1","alt":"广告：安康民众俱乐部 10 月 25 日举办“防止沉迷网络”活动，有讲座和知识竞赛，写明活动地点、时间、费用、报名方式和报名日期，还有查看详情的网站。"}]},"chinese-2026-prelim-plmgs-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-plmgs-g5-img1","alt":"短文：老师选了美华做戏剧表演的主要演员，可是表演那晚妈妈发现主要演员不是美华，美华演的是小白兔。原来美华把机会让给了没有自信的小丽。"}]},"chinese-2026-prelim-raffles-girls-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-g1-img1","alt":"短文：美阳小学进行“安静十分钟”活动，同学们在上课前静下心来做准备，学习表现和态度都变好了。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-raffles-girls-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-g2-img1","alt":"短文：立明在外公的瘦肉粥店帮忙，一位顾客多给了五十元，立明想把钱收起来，外公教他做人要诚实，第二天把钱还给了顾客。"}]},"chinese-2026-prelim-raffles-girls-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 心里感到有点慌，2 遇到困难不能退缩，3 单独行动非常危险，4 便替我把晚饭做完呢，5 只好请级任老师来帮忙，6 那你们最后做出晚饭了吗，7 那你们最后做出了什么晚饭，8 一步一步地教我和队友们煎蛋呢。下面是妈妈和丁月谈露营做晚饭的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-raffles-girls-g4":{"text":"根据短文和上下文的意思回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-g4-img1","alt":"广告：欢乐民众俱乐部举办“书香伴我行”中文书展，有活动的日期、时间、地点，还有周末特别活动：诗人林美的讲座和漫画家胡田的签名会。"}]},"chinese-2026-prelim-raffles-girls-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-raffles-girls-g5-img1","alt":"短文：爷爷对手机很好奇，但担心学不会。明文和爸爸耐心地教他，爷爷终于学会了用手机，生活变得更加丰富多彩。"}]},"chinese-2026-prelim-red-swastika-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-g1-img1","alt":"短文：乡村发生水灾，一位有钱人带食物去分给村民，想得到称赞。一个村民告诉他帮助别人要真心诚意，有钱人很惭愧，学会了用真诚的心去帮助别人。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-red-swastika-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-g2-img1","alt":"短文：康康拿着辛苦存的五十元去买电子游戏机，在店里看到一个衣服破旧的卖报纸女孩把钱包还给妇女，又不肯收奖励。他想起自己小时候家里的困难，听到歌声后，握紧五十元向小女孩走去。"}]},"chinese-2026-prelim-red-swastika-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在作答簿上相应的格子里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 我身体很好；2 您不是才刚病好；3 去跑步有许多好处；4 听到树上鸟儿的叫声；5 为什么还要和您去跑步；6 因为让眼睛休息一会儿；7 周末我想在家里打打游戏；8 跑步后我们还可以一起去吃个早餐。下面是爸爸叫庆文一起去跑步的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-red-swastika-g4":{"text":"根据短文的内容和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-g4-img1","alt":"广告：康康民众俱乐部的智能手机学习班（初级班），有四个课程的名称、内容、日期和时间，还有地点、收费、参加者、报名方法、报名截止日期和优惠。"}]},"chinese-2026-prelim-red-swastika-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-red-swastika-g5-img1","alt":"短文：篮球决赛当天，最厉害的队员王乐因为脚受伤没来。队长子文建议让平时训练最认真的小杰上场，大华起初反对，后来支持他。球队虽然没有赢，但更像一个真正的团队了。"}]},"chinese-2026-prelim-tao-nan-g1":{"text":"根据短文的内容和上下文的意思，从括号中选出适当的词语。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-tao-nan-g1-img1","alt":"短文：老师教同学折纸飞机，康康试了两次不成功就不想折了。老师鼓励他多试几次，他的纸飞机终于越飞越远。短文里有 Q16 到 Q20 五个括号，每个括号有四个词语。"}]},"chinese-2026-prelim-tao-nan-g2":{"text":"根据短文的内容和上下文的意思，选出适当的答案。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-tao-nan-g2-img1","alt":"短文：作者喜欢打篮球。一次比赛，观众没有欢迎他的球队，他上半场打得很差。教练告诉他不应该受掌声影响，下半场他专心打球，最后赢了比赛。"}]},"chinese-2026-prelim-tao-nan-g3":{"text":"根据上下文的意思，从表中选出适当的短语或短句，然后把代表它们的数字填写在括号里。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-tao-nan-g3-img1","alt":"上面的格子是编号 1 到 8 的八个短语或短句：1 我很喜欢上网聊天；2 我在家过得很充实；3 手机是我们的好伙伴；4 什么事都要妈妈帮忙；5 在家不能随时使用手机；6 我的手机必须交给父母保管；7 我们都应该控制用手机的时间；8 花太多时间在手机上不但容易分心。下面是文丽和美芳谈在家使用手机的对话，对话里有 Q26 到 Q29 四个空格。"}]},"chinese-2026-prelim-tao-nan-g4":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-tao-nan-g4-img1","alt":"通告：欢乐民众俱乐部的“马年大吉”新年庆祝会，有举办的目的、日期、时间、地点，前 50 名到场民众可领取马年娃娃，还有新春猜灯谜、写春联送福气、动手做一做、舞龙舞狮表演、年味小吃摊五个活动的内容，以及查询详情的方法。"}]},"chinese-2026-prelim-tao-nan-g5":{"text":"根据短文和上下文的意思，回答问题，然后把答案填写在作答簿上。\n\n[[img1]]","images":[{"id":"img1","key":"chinese-2026-prelim-tao-nan-g5-img1","alt":"短文：林爷爷摆了一个修伞摊，生意不好，家乐觉得他在做没意义的事。一位妇女拿来父亲留给她的旧伞修理，修好后要给林爷爷五十元，林爷爷只收两元。家乐明白了林爷爷的工作的意义。"}]}}};
